async function requireObservationEventOrganizer(request: Request, env: Env, sessionId: string): Promise<{ auth: SessionSnapshot; session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>> } | Response> {
  const auth = await readCompatibleSession(request, env);
  if (!auth) return json({ error: "login required" }, 401, { "cache-control": "no-store" });
  const session = await getObservationEventSessionById(env, sessionId);
  if (!session) return json({ error: "session not found" }, 404, { "cache-control": "no-store" });
  if (session.organizerUserId !== auth.userId) return json({ error: "organizer only" }, 403, { "cache-control": "no-store" });
  return { auth, session };
}

function isObservationEventFunnelEventName(value: unknown): value is ObservationEventFunnelEventName {
  return typeof value === "string" && OBSERVATION_EVENT_FUNNEL_EVENT_NAME_SET.has(value);
}

function parseObservationEventFunnelPayload(input: Record<string, unknown>): ObservationEventFunnelPayload | null {
  if (Object.keys(input).some((key) => !OBSERVATION_EVENT_FUNNEL_PAYLOAD_KEYS.has(key))) return null;
  if (!isObservationEventFunnelEventName(input.event_name)) return null;
  if (typeof input.page !== "string" || !OBSERVATION_EVENT_FUNNEL_PAGES.has(input.page as ObservationEventFunnelPage)) return null;
  if (typeof input.auth_state !== "string" || !OBSERVATION_EVENT_FUNNEL_AUTH_STATES.has(input.auth_state as ObservationEventFunnelAuthState)) return null;
  const optionalValues: Array<[unknown, ReadonlySet<string>]> = [
    [input.device_class, OBSERVATION_EVENT_FUNNEL_DEVICE_CLASSES],
    [input.browser_family, OBSERVATION_EVENT_FUNNEL_BROWSER_FAMILIES],
    [input.network_state, OBSERVATION_EVENT_FUNNEL_NETWORK_STATES],
    [input.result_reason, OBSERVATION_EVENT_FUNNEL_RESULT_REASONS],
    [input.duration_bucket, OBSERVATION_EVENT_FUNNEL_DURATION_BUCKETS],
    [input.retry_kind, OBSERVATION_EVENT_FUNNEL_RETRY_KINDS]
  ];
  if (optionalValues.some(([value, allowed]) => value !== undefined && (typeof value !== "string" || !allowed.has(value)))) return null;
  return {
    event_name: input.event_name,
    page: input.page as ObservationEventFunnelPage,
    auth_state: input.auth_state as ObservationEventFunnelAuthState,
    ...(input.device_class ? { device_class: input.device_class as ObservationEventFunnelDeviceClass } : {}),
    ...(input.browser_family ? { browser_family: input.browser_family as ObservationEventFunnelBrowserFamily } : {}),
    ...(input.network_state ? { network_state: input.network_state as ObservationEventFunnelNetworkState } : {}),
    ...(input.result_reason ? { result_reason: input.result_reason as ObservationEventFunnelResultReason } : {}),
    ...(input.duration_bucket ? { duration_bucket: input.duration_bucket as ObservationEventFunnelDurationBucket } : {}),
    ...(input.retry_kind ? { retry_kind: input.retry_kind as ObservationEventFunnelRetryKind } : {})
  };
}

function serverObservationEventFunnelContext(
  request: Request,
  page: ObservationEventFunnelPage,
  signedIn: boolean
): Omit<ObservationEventFunnelPayload, "event_name"> {
  const userAgent = request.headers.get("user-agent") ?? "";
  const deviceClass: ObservationEventFunnelDeviceClass = /ipad|tablet/i.test(userAgent)
    ? "tablet"
    : /mobile|iphone|ipod|android/i.test(userAgent)
      ? "mobile"
      : "desktop";
  const browserFamily: ObservationEventFunnelBrowserFamily = /line\/|instagram|fban|fbav|; wv\)|webview/i.test(userAgent)
    ? "in_app"
    : /crios|chrome|chromium/i.test(userAgent)
      ? "chrome"
      : /safari/i.test(userAgent)
        ? "safari"
        : "other";
  return {
    page,
    auth_state: signedIn ? "signed_in" : "guest",
    device_class: deviceClass,
    browser_family: browserFamily,
    network_state: "unknown"
  };
}

async function appendObservationEventFunnelMetric(
  env: Env,
  sessionId: string,
  payload: ObservationEventFunnelPayload,
  actorKey: string
) {
  const metricIdentity = await sha256Hex(textToArrayBuffer(
    `observation-event-funnel-v1\u0000${sessionId}\u0000${payload.event_name}\u0000${actorKey}`
  ));
  try {
    const result = await env.OBS_DB.prepare(
      `INSERT INTO observation_event_live_events (
         live_event_id, session_id, type, scope, actor_user_id, actor_guest_token, team_id, payload_json
       )
       SELECT ?, ?, 'funnel_metric', 'organizer', NULL, NULL, NULL, ?
        WHERE (SELECT COUNT(*)
                 FROM observation_event_live_events
                WHERE session_id = ? AND type = 'funnel_metric') < ?
          AND (SELECT COUNT(*)
                 FROM observation_event_live_events
                WHERE session_id = ?
                  AND type = 'funnel_metric'
                  AND json_extract(payload_json, '$.event_name') = ?) < ?`
    ).bind(
      `event-funnel-${metricIdentity}`,
      sessionId,
      JSON.stringify(payload),
      sessionId,
      OBSERVATION_EVENT_FUNNEL_MAX_TOTAL,
      sessionId,
      payload.event_name,
      OBSERVATION_EVENT_FUNNEL_MAX_PER_EVENT_NAME
    ).run() as { meta?: { changes?: number } };
    if (Number(result.meta?.changes ?? 1) === 0) {
      return { created: false, reason: "event_metric_capacity" };
    }
    return { created: true, reason: null };
  } catch (error) {
    if (!isD1UniqueConstraintError(error)) throw error;
    return { created: false, reason: "duplicate_actor_event" };
  }
}

async function recordObservationEventServerFunnelMetric(
  env: Env,
  sessionId: string,
  payload: ObservationEventFunnelPayload,
  actorKey: string
): Promise<void> {
  try {
    await appendObservationEventFunnelMetric(env, sessionId, payload, actorKey);
  } catch (error) {
    console.warn(JSON.stringify({
      message: "observation_event_funnel_metric_skipped",
      eventName: payload.event_name,
      sessionId,
      error: error instanceof Error ? error.message : "unknown"
    }));
  }
}

async function recordObservationEventParticipantPageMetric(
  request: Request,
  env: Env,
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>,
  eventName: ObservationEventFunnelEventName,
  page: ObservationEventFunnelPage
): Promise<void> {
  if (request.method !== "GET") return;
  const { auth, guestToken } = await observationEventRequestActor(request, env, session.sessionId);
  const canManage = Boolean(auth?.userId && auth.userId === session.organizerUserId);
  const participant = canManage
    ? null
    : await findObservationEventParticipant(env, session.sessionId, auth?.userId ?? null, guestToken);
  if (!canManage && !participant) return;
  await recordObservationEventServerFunnelMetric(env, session.sessionId, {
    event_name: eventName,
    ...serverObservationEventFunnelContext(request, page, Boolean(auth))
  }, canManage && auth?.userId ? `user:${auth.userId}` : `participant:${participant!.participant_id}`);
}

async function recordObservationEventFunnelMetric(request: Request, env: Env, sessionId: string): Promise<Response> {
  const sameOriginError = assertSameOriginRequest(request, true);
  if (sameOriginError) return sameOriginError;
  const session = await getObservationEventSessionById(env, sessionId);
  if (!session) return json({ error: "session not found" }, 404, { "cache-control": "no-store" });
  const body = await readJson<Record<string, unknown>>(request);
  const payload = parseObservationEventFunnelPayload(body);
  if (!payload) return json({ ok: false, error: "invalid_analytics_payload" }, 400, { "cache-control": "no-store" });
  const { auth, guestToken } = await observationEventRequestActor(request, env, sessionId);
  const canManage = Boolean(auth?.userId && auth.userId === session.organizerUserId);
  let participant = canManage
    ? null
    : await findObservationEventParticipant(env, sessionId, auth?.userId ?? null, guestToken);
  if (!canManage && !participant && auth) {
    const registrationGuestCredential = await readObservationEventGuestCredential(request.headers.get("cookie"), sessionId);
    const registrationGuestToken = registrationGuestCredential
      ? await observationEventGuestCredentialDigest(registrationGuestCredential)
      : null;
    participant = registrationGuestToken
      ? await findObservationEventParticipant(env, sessionId, null, registrationGuestToken)
      : null;
  }
  if (!canManage && !participant) {
    return json({ ok: false, error: "event_participant_required" }, auth || guestToken ? 403 : 401, { "cache-control": "no-store" });
  }
  const actualAuthState: ObservationEventFunnelAuthState = auth ? "signed_in" : "guest";
  if (payload.auth_state !== actualAuthState) {
    return json({ ok: false, error: "analytics_auth_state_mismatch" }, 400, { "cache-control": "no-store" });
  }
  if (!OBSERVATION_EVENT_CLIENT_FUNNEL_EVENT_NAME_SET.has(payload.event_name)) {
    return json({ ok: false, error: "server_managed_analytics_event" }, 400, { "cache-control": "no-store" });
  }
  if (payload.event_name === "event_offline_queued") {
    return json({ ok: false, error: "durable_offline_queue_unavailable" }, 409, { "cache-control": "no-store" });
  }
  const actorKey = canManage && auth?.userId
    ? `user:${auth.userId}`
    : `participant:${participant!.participant_id}`;
  await appendObservationEventFunnelMetric(env, sessionId, payload, actorKey);
  return json({ ok: true, event_name: payload.event_name }, 202, { "cache-control": "no-store" });
}

async function buildObservationEventOperationsDashboard(
  env: Env,
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>
) {
  const [participants, events] = await Promise.all([
    listObservationEventParticipants(env, session.sessionId),
    listObservationEventLiveEvents(env, session.sessionId, 5000, true)
  ]);
  const funnelCounts = new Map<ObservationEventFunnelEventName, number>(
    OBSERVATION_EVENT_FUNNEL_EVENT_NAMES.map((name) => [name, 0])
  );
  for (const event of events) {
    if (event.type !== "funnel_metric" || event.scope !== "organizer") continue;
    const eventName = event.payload.event_name;
    if (!isObservationEventFunnelEventName(eventName)) continue;
    funnelCounts.set(eventName, (funnelCounts.get(eventName) ?? 0) + 1);
  }
  const funnelStages = [
    ["QR entry", "event_qr_open"],
    ["join", "event_join_loaded"],
    ["check-in", "event_checkin_succeeded"],
    ["rally", "event_rally_opened"],
    ["photo selected", "event_photo_selected"],
    ["submit started", "event_observation_submit_started"],
    ["observation saved", "event_observation_succeeded"],
    ["live", "event_live_viewed"],
    ["recap", "event_recap_viewed"]
  ] as const;
  let previousCount: number | null = null;
  const funnel = funnelStages.map(([label, eventName]) => {
    const count = funnelCounts.get(eventName) ?? 0;
    const conversionFromPreviousPct = previousCount && previousCount > 0
      ? Math.round((count / previousCount) * 1000) / 10
      : null;
    previousCount = count;
    return { label, eventName, count, conversionFromPreviousPct };
  });
  const observationIds = new Set(
    events
      .filter((event) => event.type === "observation_added")
      .map(observationEventObservationId)
      .filter((value): value is string => Boolean(value))
  );
  const latestCreatedAt = events
    .map((event) => event.createdAt)
    .filter(Boolean)
    .sort((a, b) => b.localeCompare(a))[0] ?? session.updatedAt;
  const endedAtMs = session.endedAt ? Date.parse(session.endedAt) : Number.NaN;
  return {
    sessionId: session.sessionId,
    allowedEventNames: [...OBSERVATION_EVENT_FUNNEL_EVENT_NAMES],
    funnel,
    failures: {
      checkin: funnelCounts.get("event_checkin_failed") ?? 0,
      observation: funnelCounts.get("event_observation_failed") ?? 0,
      classification: "untrusted_participant_telemetry",
      automaticFallbackEligible: false,
      requiredCorroboration: "staff_reproduction_or_domain_health_signal"
    },
    domain: {
      checkedInFamiliesOrGroups: participants.filter(isObservationEventParticipatingGroup).length,
      observationCount: observationIds.size,
      submissionSucceededCount: observationIds.size,
      submissionFailedSignalCount: funnelCounts.get("event_observation_failed") ?? 0,
      unsynced: { status: "not_measurable", count: null, reason: "durable_queue_not_available" },
      lastUpdatedAt: latestCreatedAt,
      liveAggregationDelay: { status: "not_measurable", seconds: null, reason: "snapshot_delivery_has_no_separate_reflection_timestamp" },
      recapStatus: Number.isFinite(endedAtMs) && endedAtMs <= Date.now() ? "ready" : "not_started"
    }
  };
}

async function getObservationEventOperationsDashboard(request: Request, env: Env, sessionId: string): Promise<Response> {
  const organizer = await requireObservationEventOrganizer(request, env, sessionId);
  if (organizer instanceof Response) return organizer;
  const dashboard = await buildObservationEventOperationsDashboard(env, organizer.session);
  return json({ dashboard }, 200, { "cache-control": "no-store" });
}

async function appendObservationEventLive(env: Env, input: {
  sessionId: string;
  type: string;
  scope?: string;
  actorUserId?: string | null;
  actorGuestToken?: string | null;
  teamId?: string | null;
  payload?: Record<string, unknown>;
}) {
  const liveEventId = crypto.randomUUID();
  await env.OBS_DB.prepare(
    `INSERT INTO observation_event_live_events (
       live_event_id, session_id, type, scope, actor_user_id, actor_guest_token, team_id, payload_json
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(liveEventId, input.sessionId, input.type, input.scope ?? "all", input.actorUserId ?? null, input.actorGuestToken ?? null, input.teamId ?? null, JSON.stringify(input.payload ?? {})).run();
  return {
    liveEventId,
    sessionId: input.sessionId,
    type: input.type,
    scope: input.scope ?? "all",
    teamId: input.teamId ?? null,
    payload: input.payload ?? {},
    createdAt: new Date().toISOString()
  };
}

async function listObservationEventLiveEvents(
  env: Env,
  sessionId: string,
  limit: number,
  includeFunnelMetrics = false
) {
  const rows = await env.OBS_DB.prepare(
    `SELECT live_event_id, session_id, type, scope, actor_user_id, actor_guest_token, team_id, payload_json, created_at
       FROM observation_event_live_events
      WHERE session_id = ?
        AND (? = 1 OR type <> 'funnel_metric')
      ORDER BY created_at DESC
      LIMIT ?`
  ).bind(sessionId, includeFunnelMetrics ? 1 : 0, limit).all<ObservationEventLiveD1Row>();
  return rows.results.map((row) => ({
    liveEventId: row.live_event_id,
    sessionId: row.session_id,
    type: row.type,
    scope: row.scope,
    actorUserId: row.actor_user_id ?? null,
    actorGuestToken: row.actor_guest_token ?? null,
    teamId: row.team_id,
    payload: jsonObject(row.payload_json),
    createdAt: row.created_at
  }));
}

async function listObservationEventTeams(env: Env, sessionId: string) {
  const rows = await env.OBS_DB.prepare(
    `SELECT team_id, name, color, lead_user_id, target_taxa_json, created_at
       FROM observation_event_teams
      WHERE session_id = ?
      ORDER BY created_at ASC`
  ).bind(sessionId).all<ObservationEventTeamD1Row>();
  return rows.results;
}

async function listObservationEventParticipants(env: Env, sessionId: string) {
  const rows = await env.OBS_DB.prepare(
    `SELECT participant_id, user_id, guest_token, display_name, team_id, role, status, share_location, location_share_until, is_minor
       FROM observation_event_participants
      WHERE session_id = ?
      ORDER BY checked_in_at ASC, created_at ASC`
  ).bind(sessionId).all<ObservationEventParticipantD1Row>();
  return rows.results;
}

async function listObservationEventAbsences(env: Env, sessionId: string) {
  const rows = await env.OBS_DB.prepare(
    `SELECT absence_id, session_id, user_id, guest_token, team_id, searched_taxon, public_lat, public_lng
       FROM observation_event_absences
      WHERE session_id = ?
      ORDER BY created_at ASC`
  ).bind(sessionId).all<{
    absence_id: string;
    session_id: string;
    user_id: string | null;
    guest_token: string | null;
    team_id: string | null;
    searched_taxon: string;
    public_lat: number;
    public_lng: number;
  }>();
  return rows.results;
}

function observationEventTaxonName(payload: Record<string, unknown>): string | null {
  return normalizeOptionalText(payload.taxon_name)
    ?? normalizeOptionalText(payload.taxonName)
    ?? normalizeOptionalText(payload.scientific_name)
    ?? normalizeOptionalText(payload.vernacular_name)
    ?? normalizeOptionalText(payload.taxon)
    ?? normalizeOptionalText(asPlainObject(payload.primary_subject)?.name)
    ?? normalizeOptionalText(asPlainObject(payload.primarySubject)?.name);
}

function countObservationEventTaxa(events: Array<{ payload: Record<string, unknown> }>): Map<string, number> {
  const counts = new Map<string, number>();
  for (const event of events) {
    const name = observationEventTaxonName(event.payload);
    if (!name) continue;
    counts.set(name, (counts.get(name) ?? 0) + 1);
  }
  return new Map([...counts.entries()].sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0], "ja")));
}

function durationMinutesBetween(startedAt: string, endedAt: string | null): number | null {
  const start = Date.parse(startedAt);
  const end = endedAt ? Date.parse(endedAt) : Date.now();
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null;
  return Math.max(0, Math.round((end - start) / 60000));
}

function isObservationEventParticipatingGroup(participant: ObservationEventParticipantD1Row): boolean {
  if (participant.role === "organizer") return false;
  return participant.status === "checked_in" || participant.status === "offline" || participant.status === "left";
}

function findObservationEventViewerParticipant(
  participants: ObservationEventParticipantD1Row[],
  userId: string | null,
  guestToken: string | null
): ObservationEventParticipantD1Row | null {
  if (!userId && !guestToken) return null;
  return participants.find((participant) =>
    (userId !== null && participant.user_id === userId) ||
    (guestToken !== null && participant.guest_token === guestToken)
  ) ?? null;
}

async function recordObservationEventRecapView(env: Env, sessionId: string, userId: string | null, guestToken: string | null): Promise<void> {
  try {
    await env.OBS_DB.prepare(
      "INSERT INTO observation_event_recap_views (view_id, session_id, viewer_user_id, viewer_guest_token) VALUES (?, ?, ?, ?)"
    ).bind(crypto.randomUUID(), sessionId, userId, guestToken).run();
  } catch {
    // Older D1 environments may not have the audit table before the migration is applied.
  }
}

function observationEventLocationShareUntil(
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>
): string | null {
  const startedAt = Date.parse(session.startedAt);
  if (!Number.isFinite(startedAt)) return null;
  const scheduledEnd = session.endedAt ? Date.parse(session.endedAt) : Number.NaN;
  return new Date(Number.isFinite(scheduledEnd) ? scheduledEnd : startedAt + 4 * 60 * 60 * 1000).toISOString();
}

async function claimObservationEventGuestParticipant(
  env: Env,
  sessionId: string,
  userId: string,
  guestToken: string,
  retriedAfterConflict = false
): Promise<void> {
  const [guestParticipant, userParticipant] = await Promise.all([
    findObservationEventParticipant(env, sessionId, null, guestToken),
    findObservationEventParticipant(env, sessionId, userId, null)
  ]);
  if (!guestParticipant || (guestParticipant.user_id && guestParticipant.user_id !== userId)) return;
  const statements = [
    env.OBS_DB.prepare(
      `UPDATE observation_event_live_events
          SET actor_user_id = CASE WHEN actor_guest_token = ? THEN ? ELSE actor_user_id END,
              actor_guest_token = CASE WHEN actor_guest_token = ? THEN NULL ELSE actor_guest_token END,
              payload_json = CASE
                WHEN json_extract(payload_json, '$.target_guest_token') = ?
                  THEN json_set(json_remove(payload_json, '$.target_guest_token'), '$.target_user_id', ?)
                ELSE payload_json
              END
        WHERE session_id = ?
          AND (actor_guest_token = ? OR json_extract(payload_json, '$.target_guest_token') = ?)`
    ).bind(guestToken, userId, guestToken, guestToken, userId, sessionId, guestToken, guestToken),
    env.OBS_DB.prepare(
      `UPDATE observation_event_absences
          SET user_id = ?, guest_token = NULL
        WHERE session_id = ? AND guest_token = ?`
    ).bind(userId, sessionId, guestToken),
    env.OBS_DB.prepare(
      `DELETE FROM observation_rally_submissions
        WHERE submission_id IN (
          SELECT guest.submission_id
            FROM observation_rally_submissions guest
            JOIN observation_rally_submissions account
              ON account.session_id = guest.session_id
             AND account.user_id = ?
             AND account.mission_id = guest.mission_id
             AND account.source_type = guest.source_type
             AND account.source_ref = guest.source_ref
           WHERE guest.session_id = ?
             AND guest.guest_token = ?
             AND guest.source_ref IS NOT NULL
             AND TRIM(guest.source_ref) <> ''
        )`
    ).bind(userId, sessionId, guestToken),
    env.OBS_DB.prepare(
      `UPDATE observation_rally_submissions
          SET user_id = ?, guest_token = NULL
        WHERE session_id = ? AND guest_token = ?`
    ).bind(userId, sessionId, guestToken),
    env.OBS_DB.prepare(
      `UPDATE observation_event_recap_views
          SET viewer_user_id = ?, viewer_guest_token = NULL
        WHERE session_id = ? AND viewer_guest_token = ?`
    ).bind(userId, sessionId, guestToken)
  ];

  if (userParticipant && userParticipant.participant_id !== guestParticipant.participant_id) {
    statements.push(
      env.OBS_DB.prepare(
        `UPDATE observation_event_participants
            SET display_name = COALESCE(NULLIF(display_name, ''), (SELECT display_name FROM observation_event_participants WHERE participant_id = ?)),
                team_id = COALESCE(team_id, (SELECT team_id FROM observation_event_participants WHERE participant_id = ?)),
                declared_job = COALESCE(declared_job, (SELECT declared_job FROM observation_event_participants WHERE participant_id = ?)),
                updated_at = CURRENT_TIMESTAMP
          WHERE participant_id = ?`
      ).bind(guestParticipant.participant_id, guestParticipant.participant_id, guestParticipant.participant_id, userParticipant.participant_id),
      env.OBS_DB.prepare(
        `DELETE FROM observation_event_participants
          WHERE participant_id = ?
            AND session_id = ?
            AND (user_id IS NULL OR user_id = ?)
            AND guest_token = ?`
      ).bind(guestParticipant.participant_id, sessionId, userId, guestToken)
    );
  } else {
    statements.push(
      env.OBS_DB.prepare(
        `UPDATE observation_event_participants
            SET user_id = ?, guest_token = NULL, updated_at = CURRENT_TIMESTAMP
          WHERE participant_id = ?
            AND session_id = ?
            AND (user_id IS NULL OR user_id = ?)
            AND guest_token = ?`
      ).bind(userId, guestParticipant.participant_id, sessionId, userId, guestToken)
    );
  }

  try {
    await env.OBS_DB.batch(statements);
  } catch (error) {
    if (!isD1UniqueConstraintError(error) || retriedAfterConflict) throw error;
    await claimObservationEventGuestParticipant(env, sessionId, userId, guestToken, true);
  }
}

async function upsertObservationEventParticipant(env: Env, input: {
  sessionId: string;
  userId: string | null;
  guestToken: string | null;
  displayName: string;
  teamId: string | null;
  isMinor: boolean;
  shareLocation?: boolean;
  locationShareUntil?: string | null;
  locationShareConsentType?: string | null;
}): Promise<{ participantId: string; created: boolean }> {
  const existing = await findObservationEventParticipant(env, input.sessionId, input.userId, input.guestToken);
  const shareLocation = input.shareLocation === true && (!input.isMinor || input.locationShareConsentType === "guardian") ? 1 : 0;
  const shareUntil = shareLocation ? input.locationShareUntil ?? new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString() : null;
  const consentType = shareLocation ? input.locationShareConsentType ?? "self" : null;
  if (existing) {
    await env.OBS_DB.prepare(
      `UPDATE observation_event_participants
          SET display_name = ?, team_id = COALESCE(?, team_id), status = 'checked_in',
              checked_in_at = CURRENT_TIMESTAMP, share_location = ?, is_minor = ?,
              location_share_until = ?, location_share_consent_type = ?, updated_at = CURRENT_TIMESTAMP
        WHERE participant_id = ?`
    ).bind(input.displayName, input.teamId, shareLocation, input.isMinor ? 1 : 0, shareUntil, consentType, existing.participant_id).run();
    return { participantId: existing.participant_id, created: false };
  }
  const participantId = crypto.randomUUID();
  try {
    await env.OBS_DB.prepare(
      `INSERT INTO observation_event_participants (
         participant_id, session_id, user_id, guest_token, display_name, team_id, role, status,
         checked_in_at, share_location, is_minor, location_share_until, location_share_consent_type
       ) VALUES (?, ?, ?, ?, ?, ?, 'participant', 'checked_in', CURRENT_TIMESTAMP, ?, ?, ?, ?)`
    ).bind(participantId, input.sessionId, input.userId, input.guestToken, input.displayName, input.teamId, shareLocation, input.isMinor ? 1 : 0, shareUntil, consentType).run();
    return { participantId, created: true };
  } catch (error) {
    if (!isD1UniqueConstraintError(error)) throw error;
    const concurrent = await findObservationEventParticipant(env, input.sessionId, input.userId, input.guestToken);
    if (!concurrent) throw error;
    return { participantId: concurrent.participant_id, created: false };
  }
}

async function findObservationEventParticipant(env: Env, sessionId: string, userId: string | null, guestToken: string | null) {
  if (!userId && !guestToken) return null;
  return env.OBS_DB.prepare(
    `SELECT participant_id, user_id, guest_token, display_name, team_id, role, status,
            share_location, location_share_until, is_minor
       FROM observation_event_participants
      WHERE session_id = ?
        AND ((user_id IS NOT NULL AND user_id = ?) OR (guest_token IS NOT NULL AND guest_token = ?))
      LIMIT 1`
  ).bind(sessionId, userId, guestToken).first<ObservationEventParticipantD1Row>();
}

async function observationEventParticipantContext(
  request: Request,
  env: Env,
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>
) {
  const auth = await readCompatibleSession(request, env).catch(() => null);
  const guestCredential = await readObservationEventGuestCredential(request.headers.get("cookie"), session.sessionId);
  const guestToken = guestCredential ? await observationEventGuestCredentialDigest(guestCredential) : null;
  const [userParticipant, guestParticipant] = await Promise.all([
    auth?.userId ? findObservationEventParticipant(env, session.sessionId, auth.userId, null) : Promise.resolve(null),
    guestToken ? findObservationEventParticipant(env, session.sessionId, null, guestToken) : Promise.resolve(null)
  ]);
  const participant = [userParticipant, guestParticipant]
    .filter((candidate): candidate is ObservationEventParticipantD1Row => candidate !== null)
    .find(isObservationEventParticipatingGroup) ?? null;
  return {
    userId: auth?.userId ?? null,
    guestToken,
    teamId: participant?.team_id ?? null,
    isOrganizer: Boolean(auth?.userId && auth.userId === session.organizerUserId),
    isCheckedInParticipant: Boolean(participant)
  };
}

type PublicObservationEventLiveEvent = {
  type: string;
  label: string;
  payload: Record<string, unknown>;
  createdAt: string;
};

const PUBLIC_OBSERVATION_EVENT_LIVE_LABELS: Readonly<Record<string, string>> = Object.freeze({
  observation_added: "観察が追加されました",
  field_scan_added: "フィールド観察が追加されました",
  guide_scene_added: "ガイド観察が追加されました",
  absence_recorded: "見つからなかった記録が追加されました",
  announce: "主催者からのお知らせ",
  mode_switch: "観察モードが変わりました",
  team_update: "観察グループの案内が更新されました",
  checkin: "チェックインがありました",
  participant_location_ping: "参加状況が更新されました",
  quest_offered: "追加の観察ヒント",
  quest_accepted: "観察ヒントに挑戦します",
  quest_declined: "観察ヒントを見送りました",
  quest_completed: "観察ヒントを達成しました",
  rally_station_opened: "観察地点が開きました",
  rally_mission_published: "観察ミッションが始まりました",
  rally_mission_paused: "観察ミッションを一時停止しました",
  rally_mission_replaced: "観察ミッションが更新されました",
  rally_mission_extended: "観察ミッションの時間が延長されました",
  rally_mission_closed: "観察ミッションが終了しました",
  rally_next_action: "次の観察案内があります",
  rally_task_submitted: "観察ミッションの記録が届きました",
  rally_task_cleared: "観察ミッションの確認が終わりました",
  rare_species: "注目のいきものが見つかりました",
  target_hit: "探していたいきものが見つかりました",
  milestone: "観察の節目に到達しました",
  fanfare: "観察会に新しい発見がありました"
});

function publicObservationEventLiveText(value: unknown, maxLength = 240): string | null {
  const normalized = normalizeOptionalText(value);
  return normalized ? normalized.slice(0, maxLength) : null;
}

function publicObservationEventLiveEvent(
  event: Awaited<ReturnType<typeof listObservationEventLiveEvents>>[number]
): PublicObservationEventLiveEvent | null {
  const label = PUBLIC_OBSERVATION_EVENT_LIVE_LABELS[event.type];
  if (!label) return null;
  const payload: Record<string, unknown> = {};
  const taxonName = observationEventTaxonName(event.payload);
  if (["observation_added", "field_scan_added", "guide_scene_added", "rare_species", "target_hit", "milestone", "fanfare"].includes(event.type)) {
    payload.taxonName = taxonName ?? "未同定";
  }
  if (event.type === "absence_recorded") {
    payload.searchedTaxon = publicObservationEventLiveText(event.payload.searched_taxon) ?? "未指定";
    payload.confidence = publicObservationEventLiveText(event.payload.confidence, 40) ?? "searched";
  }
  if (event.type === "announce") {
    payload.message = publicObservationEventLiveText(event.payload.message, 500) ?? "お知らせがあります。";
  }
  if (["quest_offered", "quest_accepted", "quest_declined", "quest_completed", "rare_species", "target_hit", "milestone", "fanfare"].includes(event.type)) {
    const headline = publicObservationEventLiveText(event.payload.headline, 160);
    if (headline) payload.headline = headline;
  }
  if (event.type === "quest_offered") {
    const prompt = publicObservationEventLiveText(event.payload.prompt, 300);
    if (prompt) payload.prompt = prompt;
  }
  if (event.type === "mode_switch") {
    payload.primaryMode = publicObservationEventLiveText(event.payload.primary_mode, 40) ?? "discovery";
    payload.activeModes = stringArray(event.payload.active_modes).slice(0, OBSERVATION_EVENT_MODES.length);
  }
  if (event.type === "team_update") {
    const updateKind = publicObservationEventLiveText(event.payload.kind, 40);
    const declaredJob = publicObservationEventLiveText(event.payload.declared_job, 80);
    if (updateKind) payload.updateKind = updateKind;
    if (declaredJob) payload.declaredJob = declaredJob;
    const targetTaxa = stringArray(asPlainObject(event.payload.team)?.target_taxa).slice(0, 12);
    if (targetTaxa.length > 0) payload.targetTaxa = targetTaxa;
  }
  if (event.type === "rally_station_opened") {
    const name = publicObservationEventLiveText(event.payload.name, 120);
    if (name) payload.name = name;
  }
  if (["rally_mission_published", "rally_mission_paused", "rally_mission_replaced", "rally_mission_extended", "rally_mission_closed"].includes(event.type)) {
    const status = publicObservationEventLiveText(event.payload.status, 40);
    if (status) payload.status = status;
  }
  if (event.type === "rally_next_action") {
    const mode = publicObservationEventLiveText(event.payload.mode, 40);
    if (mode) payload.mode = mode;
  }
  if (["rally_task_submitted", "rally_task_cleared"].includes(event.type)) {
    const reviewStatus = publicObservationEventLiveText(event.payload.review_status, 40);
    if (reviewStatus) payload.reviewStatus = reviewStatus;
  }
  return {
    type: event.type,
    label,
    payload,
    createdAt: event.createdAt
  };
}

function publicObservationEventLiveSession(
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>
) {
  const startsAt = Date.parse(session.startedAt);
  const endsAt = session.endedAt ? Date.parse(session.endedAt) : Number.NaN;
  const now = Date.now();
  const status = Number.isFinite(endsAt) && endsAt <= now
    ? "ended"
    : Number.isFinite(startsAt) && startsAt > now
      ? "scheduled"
      : "live";
  return {
    title: session.title,
    primaryMode: session.primaryMode,
    activeModes: session.activeModes,
    startedAt: session.startedAt,
    endedAt: session.endedAt,
    status
  };
}

function summarizePublicObservationEventLive(events: PublicObservationEventLiveEvent[]) {
  const observations = events.filter((event) => ["observation_added", "field_scan_added", "guide_scene_added"].includes(event.type));
  return {
    eventCount: events.length,
    observationCount: observations.length
  };
}

function observationEventLiveParticipantDetail(event: PublicObservationEventLiveEvent): string | null {
  const candidates = [
    event.payload.message,
    event.payload.headline,
    event.payload.prompt,
    event.payload.taxonName,
    event.payload.searchedTaxon,
    event.payload.name,
    event.payload.primaryMode,
    event.payload.status,
    event.payload.reviewStatus,
    event.payload.declaredJob
  ];
  for (const candidate of candidates) {
    const value = publicObservationEventLiveText(candidate, 500);
    if (value) return value;
  }
  const targetTaxa = stringArray(event.payload.targetTaxa);
  return targetTaxa.length > 0 ? targetTaxa.join("・") : null;
}

function shouldDeliverObservationEvent(
  event: { scope: string; teamId: string | null; payload: Record<string, unknown> },
  ctx: { userId: string | null; guestToken: string | null; teamId: string | null; isOrganizer: boolean; isCheckedInParticipant: boolean }
): boolean {
  if (ctx.isOrganizer) return true;
  if (!ctx.isCheckedInParticipant) return false;
  if (event.scope === "all") return true;
  if (event.scope === "team") return Boolean(ctx.teamId && ctx.teamId === event.teamId);
  if (event.scope === "self") {
    const targetUser = normalizeOptionalText(event.payload.target_user_id);
    const targetGuest = normalizeOptionalText(event.payload.target_guest_token);
    return Boolean((targetUser && targetUser === ctx.userId) || (targetGuest && targetGuest === ctx.guestToken));
  }
  return false;
}

async function recordObservationEventMeshVisit(env: Env, input: { sessionId: string; lat: number; lng: number; absenceDelta?: number; observationDelta?: number; visitSeconds?: number; teamId?: string | null }): Promise<void> {
  const meshKey = observationEventMeshKey(input.lat, input.lng);
  if (!meshKey) return;
  const center = observationEventMeshCenter(meshKey);
  if (!center) return;
  const meshId = crypto.randomUUID();
  await env.OBS_DB.prepare(
    `INSERT INTO observation_event_mesh_cells (
       mesh_cell_id, session_id, mesh_key, center_lat, center_lng, visit_seconds,
       observation_count, absence_count, last_visited_at, visited_team_ids_json, updated_at
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(session_id, mesh_key) DO UPDATE SET
       visit_seconds = visit_seconds + excluded.visit_seconds,
       observation_count = observation_count + excluded.observation_count,
       absence_count = absence_count + excluded.absence_count,
       last_visited_at = CURRENT_TIMESTAMP,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(meshId, input.sessionId, meshKey, center.lat, center.lng, Math.max(0, Math.round(input.visitSeconds ?? 0)), Math.max(0, Math.round(input.observationDelta ?? 0)), Math.max(0, Math.round(input.absenceDelta ?? 0)), JSON.stringify(input.teamId ? [input.teamId] : [])).run();
}

function isObservationEventMode(value: unknown): value is ObservationEventMode {
  return typeof value === "string" && (OBSERVATION_EVENT_MODES as readonly string[]).includes(value);
}

function observationEventMode(value: unknown): ObservationEventMode | null {
  return isObservationEventMode(value) ? value : null;
}

function observationEventModes(value: unknown, fallback: ObservationEventMode): ObservationEventMode[] {
  const modes = Array.isArray(value) ? value.filter(isObservationEventMode) : [];
  return modes.length > 0 ? modes : [fallback];
}

function normalizeRallyCourseStatus(value: unknown): typeof RALLY_COURSE_STATUSES[number] | null {
  return typeof value === "string" && (RALLY_COURSE_STATUSES as readonly string[]).includes(value) ? value as typeof RALLY_COURSE_STATUSES[number] : null;
}

function normalizeRallyScope(value: unknown): typeof RALLY_SCOPES[number] | null {
  return typeof value === "string" && (RALLY_SCOPES as readonly string[]).includes(value) ? value as typeof RALLY_SCOPES[number] : null;
}

function normalizeRallyLocationBinding(value: unknown): typeof RALLY_LOCATION_BINDINGS[number] | null {
  return typeof value === "string" && (RALLY_LOCATION_BINDINGS as readonly string[]).includes(value) ? value as typeof RALLY_LOCATION_BINDINGS[number] : null;
}

function normalizeRallyCountUnit(value: unknown): typeof RALLY_COUNT_UNITS[number] | null {
  return typeof value === "string" && (RALLY_COUNT_UNITS as readonly string[]).includes(value) ? value as typeof RALLY_COUNT_UNITS[number] : null;
}

function normalizeRallyVerificationPolicy(value: unknown): typeof RALLY_VERIFICATION_POLICIES[number] | null {
  return typeof value === "string" && (RALLY_VERIFICATION_POLICIES as readonly string[]).includes(value) ? value as typeof RALLY_VERIFICATION_POLICIES[number] : null;
}

function normalizeRallyWeatherSensitivity(value: unknown): typeof RALLY_WEATHER_SENSITIVITIES[number] | null {
  return typeof value === "string" && (RALLY_WEATHER_SENSITIVITIES as readonly string[]).includes(value) ? value as typeof RALLY_WEATHER_SENSITIVITIES[number] : null;
}

function normalizeRallyMissionStatus(value: unknown): typeof RALLY_MISSION_STATUSES[number] | null {
  return typeof value === "string" && (RALLY_MISSION_STATUSES as readonly string[]).includes(value) ? value as typeof RALLY_MISSION_STATUSES[number] : null;
}

function normalizeRallyRevisionAction(value: unknown): typeof RALLY_REVISION_ACTIONS[number] | null {
  return typeof value === "string" && (RALLY_REVISION_ACTIONS as readonly string[]).includes(value) ? value as typeof RALLY_REVISION_ACTIONS[number] : null;
}

function normalizeReferenceText(value: unknown, max = 240): string {
  return String(value ?? "").trim().replace(/\s+/g, " ").slice(0, max);
}

function normalizeReferenceIdentifierNative(value: unknown): string {
  return String(value ?? "").replace(/[^0-9Xx]/g, "").toUpperCase().slice(0, 32);
}

function normalizeReferenceUrlNative(value: unknown): string {
  const raw = normalizeReferenceText(value, 500);
  if (!raw) return "";
  try {
    const parsed = new URL(raw);
    return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.toString().slice(0, 500) : "";
  } catch {
    return "";
  }
}

function normalizeReferenceYearNative(value: unknown): number | null {
  const year = Number.parseInt(String(value ?? ""), 10);
  return Number.isInteger(year) && year >= 1500 && year <= 2200 ? year : null;
}

function normalizeReferenceKindNative(value: unknown): string {
  const raw = normalizeReferenceText(value, 40);
  return ["field_guide", "literature", "web", "book", "unknown"].includes(raw) ? raw : "unknown";
}

function normalizeReferenceTaxonLabelsNative(value: unknown): string[] {
  return Array.from(new Set(stringArray(value).map((item) => normalizeReferenceText(item, 120)).filter(Boolean))).slice(0, 16);
}

function referenceCardPayload(row: ReferenceSourceD1Row) {
  return {
    sourceId: row.source_id,
    title: row.title,
    authorText: row.author_text,
    publisher: row.publisher,
    publicationYear: row.publication_year,
    isbn: row.isbn,
    doi: row.doi,
    url: row.url,
    sourceKind: row.source_kind,
    ownedStatus: row.owned_status ?? "not_owned",
    latestProofAt: row.latest_proof_at ?? null,
    usedCount: Number(row.used_count ?? 0),
    taxonLabels: jsonArray(row.taxon_labels_json).map((item) => normalizeReferenceText(item, 120)).filter(Boolean),
    commerceLinks: jsonArray(row.commerce_links_json),
    officialCorrectionCount: Number(row.official_correction_count ?? 0),
  };
}

function referenceCorrectionPayload(row: ReferenceCorrectionD1Row) {
  return {
    correctionId: row.correction_id,
    sourceId: row.source_id,
    locator: row.locator,
    originalName: row.original_name,
    correctedName: row.corrected_name,
    originalTaxonName: row.original_taxon_name,
    correctedTaxonName: row.corrected_taxon_name,
    correctionKind: row.correction_kind,
    officialSourceUrl: row.official_source_url,
    officialReference: row.official_reference,
    verificationStatus: row.verification_status,
    appliesFrom: row.applies_from,
    createdAt: row.created_at,
  };
}

async function getReferenceProfileSummaryNative(env: Env, userId: string): Promise<{
  ownedVerifiedCount: number;
  needsReviewCount: number;
  recent: unknown[];
}> {
  const counts = await env.OBS_DB.prepare(
    `SELECT
        (SELECT COUNT(DISTINCT source_id) FROM reference_access_proofs
          WHERE user_id = ? AND verification_status IN ('ai_verified', 'user_confirmed', 'reviewer_confirmed')) AS owned_verified_count,
        (SELECT COUNT(DISTINCT source_id) FROM reference_access_proofs
          WHERE user_id = ? AND verification_status = 'needs_review') AS needs_review_count`
  ).bind(userId, userId).first<{ owned_verified_count: number; needs_review_count: number }>();
  const recent = (await env.OBS_DB.prepare(
    `SELECT rs.source_id, rs.title, rs.taxon_labels_json, p.verification_status AS status,
            (SELECT COUNT(*) FROM reference_identification_selections sel
              WHERE sel.source_id = rs.source_id AND sel.selected_by_user_id = ?) AS used_count
       FROM reference_access_proofs p
       JOIN reference_sources rs ON rs.source_id = p.source_id
      WHERE p.user_id = ?
      ORDER BY p.updated_at DESC
      LIMIT 5`
  ).bind(userId, userId).all<ReferenceSourceD1Row & { status: string; used_count: number }>()).results;
  return {
    ownedVerifiedCount: Number(counts?.owned_verified_count ?? 0),
    needsReviewCount: Number(counts?.needs_review_count ?? 0),
    recent: recent.map((row) => ({
      sourceId: row.source_id,
      title: row.title,
      taxonLabels: jsonArray(row.taxon_labels_json).map((item) => normalizeReferenceText(item, 120)).filter(Boolean),
      usedCount: Number(row.used_count ?? 0),
      status: row.status,
    })),
  };
}

async function listReferenceLibraryNative(env: Env, session: SessionSnapshot, url: URL): Promise<Response> {
  const tab = url.searchParams.get("tab") === "catalog" ? "catalog" : url.searchParams.get("tab") === "needs_review" ? "needs_review" : "owned";
  const countryCode = normalizeReferenceText(url.searchParams.get("countryCode") ?? "JP", 8).toUpperCase() || "JP";
  const limit = Math.min(80, Math.max(1, integerOrNull(url.searchParams.get("limit")) ?? 36));
  const rows = (await env.OBS_DB.prepare(
    `SELECT rs.source_id, rs.title, rs.author_text, rs.publisher, rs.publication_year,
            rs.isbn, rs.doi, rs.url, rs.source_kind, rs.catalog_status,
            rs.taxon_labels_json, rs.commerce_links_json, rs.created_by_user_id,
            rs.source_payload_json, rs.created_at, rs.updated_at,
            CASE
              WHEN EXISTS (
                SELECT 1 FROM reference_access_proofs p
                 WHERE p.source_id = rs.source_id AND p.user_id = ?
                   AND p.verification_status IN ('ai_verified', 'user_confirmed', 'reviewer_confirmed')
              ) THEN 'owned_verified'
              WHEN EXISTS (
                SELECT 1 FROM reference_access_proofs p
                 WHERE p.source_id = rs.source_id AND p.user_id = ?
                   AND p.verification_status = 'needs_review'
              ) THEN 'needs_review'
              ELSE 'not_owned'
            END AS owned_status,
            (SELECT MAX(p.updated_at) FROM reference_access_proofs p
              WHERE p.source_id = rs.source_id AND p.user_id = ?) AS latest_proof_at,
            (SELECT COUNT(*) FROM reference_identification_selections sel
              WHERE sel.source_id = rs.source_id AND sel.selected_by_user_id = ?) AS used_count,
            (SELECT COUNT(*) FROM reference_corrections c
              WHERE c.source_id = rs.source_id AND c.verification_status = 'official_confirmed') AS official_correction_count
       FROM reference_sources rs
      WHERE rs.catalog_status NOT IN ('withdrawn', 'duplicate')
      ORDER BY rs.updated_at DESC
      LIMIT ?`
  ).bind(session.userId, session.userId, session.userId, session.userId, limit).all<ReferenceSourceD1Row>()).results;
  const cards = rows
    .map(referenceCardPayload)
    .filter((card) => tab === "catalog" ? true : tab === "needs_review" ? card.ownedStatus === "needs_review" : card.ownedStatus === "owned_verified");
  return json({
    ok: true,
    snapshot: {
      tab,
      countryCode,
      summary: await getReferenceProfileSummaryNative(env, session.userId),
      cards,
    },
    compatibility: {
      source: "cloudflare_reference_library_runtime",
      aiCoverExtractionParity: false,
      note: "metadata-first D1 runtime replaces VPS PostgreSQL dependency; AI cover extraction remains a future Cloudflare enhancement",
    },
  }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "reference-library-runtime" });
}

async function createReferenceCaptureBatchNative(env: Env, session: SessionSnapshot, request: Request): Promise<Response> {
  const body = await readJson<Record<string, unknown>>(request);
  const items = Array.isArray(body.items) ? body.items.slice(0, 24) : [];
  if (items.length === 0) return json({ ok: false, error: "reference_capture_items_required" }, 400, { "cache-control": "no-store" });
  const batchId = crypto.randomUUID();
  const results: Array<{ sourceId: string; title: string; verificationStatus: string; taxonHints: string[]; useCases: string[]; duplicate: boolean }> = [];
  await env.OBS_DB.prepare(
    `INSERT INTO reference_capture_batches
       (batch_id, user_id, status, item_count, source_payload_json, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
  ).bind(batchId, session.userId, "completed", items.length, JSON.stringify({ source: "cloudflare_reference_capture_metadata_runtime" })).run();

  for (const rawItem of items) {
    const item = asPlainObject(rawItem) ?? {};
    const isbn = normalizeReferenceIdentifierNative(item.isbn);
    const url = normalizeReferenceUrlNative(item.url);
    const title = normalizeReferenceText(item.title, 240)
      || (isbn ? `ISBN ${isbn}` : "")
      || (url ? url : "")
      || normalizeReferenceText(item.filename, 120)
      || "Untitled reference";
    const sourceId = `ref_${crypto.randomUUID()}`;
    const taxonLabels = normalizeReferenceTaxonLabelsNative(item.taxonHints ?? item.taxon_labels ?? item.taxonLabels);
    const proofKind = normalizeReferenceText(item.proofKind, 40) || "manual";
    const sourcePayload = {
      source: "cloudflare_reference_capture_metadata_runtime",
      filename: normalizeReferenceText(item.filename, 180),
      mimeType: normalizeReferenceText(item.mimeType, 80),
      noPageBodyStored: true,
      aiCoverExtractionParity: false,
    };
    await env.OBS_DB.prepare(
      `INSERT INTO reference_sources
         (source_id, title, author_text, publisher, publication_year, isbn, doi, url,
          source_kind, catalog_status, taxon_labels_json, commerce_links_json,
          created_by_user_id, source_payload_json, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
    ).bind(
      sourceId,
      title,
      normalizeReferenceText(item.authorText ?? item.author_text, 240),
      normalizeReferenceText(item.publisher, 180),
      normalizeReferenceYearNative(item.publicationYear ?? item.publication_year),
      isbn,
      normalizeReferenceText(item.doi, 120),
      url,
      normalizeReferenceKindNative(item.sourceKind ?? item.source_kind),
      "active",
      JSON.stringify(taxonLabels),
      "[]",
      session.userId,
      JSON.stringify(sourcePayload)
    ).run();
    await env.OBS_DB.prepare(
      `INSERT INTO reference_access_proofs
         (proof_id, user_id, source_id, batch_id, proof_kind, verification_status,
          private_use_only, source_payload_json, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
    ).bind(
      crypto.randomUUID(),
      session.userId,
      sourceId,
      batchId,
      proofKind,
      "needs_review",
      1,
      JSON.stringify(sourcePayload)
    ).run();
    await env.OBS_DB.prepare(
      `INSERT INTO reference_capture_items
         (item_id, batch_id, source_id, filename, mime_type, proof_kind, classification_note, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)`
    ).bind(
      crypto.randomUUID(),
      batchId,
      sourceId,
      normalizeReferenceText(item.filename, 180),
      normalizeReferenceText(item.mimeType, 80),
      proofKind,
      "cloudflare metadata capture; AI cover extraction not run"
    ).run();
    results.push({
      sourceId,
      title,
      verificationStatus: "needs_review",
      taxonHints: taxonLabels,
      useCases: ["identification_reference"],
      duplicate: false,
    });
  }

  return json({
    ok: true,
    batchId,
    status: "completed",
    ownedCount: 0,
    needsReviewCount: results.length,
    items: results,
    compatibility: { source: "cloudflare_reference_library_runtime", aiCoverExtractionParity: false },
  }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "reference-library-runtime" });
}

async function mergeReferenceDuplicateNative(env: Env, session: SessionSnapshot, request: Request): Promise<Response> {
  if (!isSpecialistAuthorityAdminRole(session)) return json({ ok: false, error: "specialist_admin_required" }, 403, { "cache-control": "no-store" });
  const body = await readJson<Record<string, unknown>>(request);
  const canonicalSourceId = normalizeOptionalId(body.canonicalSourceId);
  const duplicateSourceId = normalizeOptionalId(body.duplicateSourceId);
  if (!canonicalSourceId || !duplicateSourceId) return json({ ok: false, error: "reference_source_id_required" }, 400, { "cache-control": "no-store" });
  if (canonicalSourceId === duplicateSourceId) return json({ ok: false, error: "reference_duplicate_same_source" }, 400, { "cache-control": "no-store" });
  const canonical = await env.OBS_DB.prepare("SELECT source_id FROM reference_sources WHERE source_id = ? LIMIT 1").bind(canonicalSourceId).first<{ source_id: string }>();
  const duplicate = await env.OBS_DB.prepare("SELECT source_id FROM reference_sources WHERE source_id = ? LIMIT 1").bind(duplicateSourceId).first<{ source_id: string }>();
  if (!canonical || !duplicate) return json({ ok: false, error: "reference_source_not_found" }, 404, { "cache-control": "no-store" });
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT INTO reference_duplicate_merges
         (merge_id, canonical_source_id, duplicate_source_id, actor_user_id, source_payload_json, created_at)
       VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)`
    ).bind(crypto.randomUUID(), canonicalSourceId, duplicateSourceId, session.userId, JSON.stringify({ source: "cloudflare_reference_duplicate_merge" })),
    env.OBS_DB.prepare(
      `UPDATE reference_sources
          SET catalog_status = 'duplicate',
              source_payload_json = ?,
              updated_at = CURRENT_TIMESTAMP
        WHERE source_id = ?`
    ).bind(JSON.stringify({ duplicateOfSourceId: canonicalSourceId, duplicateConfirmedByUserId: session.userId }), duplicateSourceId),
  ]);
  return json({
    ok: true,
    result: {
      canonicalSourceId,
      duplicateSourceId,
      identificationReferencesCopied: 0,
      identificationReferencesRemoved: 0,
      accessProofsCopied: 0,
      taxonLinksCopied: 0,
      compatibility: "d1_duplicate_status_ledger",
    },
  }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "reference-library-runtime" });
}

async function createReferenceCorrectionNative(env: Env, session: SessionSnapshot, sourceId: string, request: Request): Promise<Response> {
  if (!isIdentificationSpecialistRole(session)) return json({ ok: false, error: "specialist_role_required" }, 403, { "cache-control": "no-store" });
  const normalizedSourceId = normalizeOptionalId(sourceId);
  if (!normalizedSourceId) return json({ ok: false, error: "reference_source_id_required" }, 400, { "cache-control": "no-store" });
  const source = await env.OBS_DB.prepare("SELECT source_id FROM reference_sources WHERE source_id = ? LIMIT 1").bind(normalizedSourceId).first<{ source_id: string }>();
  if (!source) return json({ ok: false, error: "reference_source_not_found" }, 404, { "cache-control": "no-store" });
  const body = await readJson<Record<string, unknown>>(request);
  const status = normalizeReferenceText(body.verificationStatus ?? body.verification_status, 40) || "pending";
  const officialSourceUrl = normalizeReferenceUrlNative(body.officialSourceUrl ?? body.official_source_url);
  const officialReference = normalizeReferenceText(body.officialReference ?? body.official_reference, 240);
  if (status === "official_confirmed" && !officialSourceUrl && !officialReference) {
    return json({ ok: false, error: "official_correction_source_required" }, 400, { "cache-control": "no-store" });
  }
  const correctionId = crypto.randomUUID();
  await env.OBS_DB.prepare(
    `INSERT INTO reference_corrections
       (correction_id, source_id, locator, original_name, corrected_name,
        original_taxon_name, corrected_taxon_name, correction_kind,
        official_source_url, official_reference, verification_status, verified_by_user_id,
        applies_from, source_payload_json, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
  ).bind(
    correctionId,
    normalizedSourceId,
    normalizeReferenceText(body.locator, 160),
    normalizeReferenceText(body.originalName ?? body.original_name, 180),
    normalizeReferenceText(body.correctedName ?? body.corrected_name, 180),
    normalizeReferenceText(body.originalTaxonName ?? body.original_taxon_name, 180),
    normalizeReferenceText(body.correctedTaxonName ?? body.corrected_taxon_name, 180),
    normalizeReferenceText(body.correctionKind ?? body.correction_kind, 80) || "misidentification",
    officialSourceUrl,
    officialReference,
    status,
    status === "official_confirmed" ? session.userId : null,
    normalizeReferenceText(body.appliesFrom ?? body.applies_from, 40) || null,
    JSON.stringify({ source: "cloudflare_reference_correction", policy: "official_metadata_only_no_page_body" })
  ).run();
  return json({ ok: true, correctionId }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "reference-library-runtime" });
}

async function listReferenceCorrectionsNative(env: Env, sourceId: string): Promise<Response> {
  const normalizedSourceId = normalizeOptionalId(sourceId);
  if (!normalizedSourceId) return json({ ok: false, error: "reference_source_id_required" }, 400, { "cache-control": "no-store" });
  const rows = (await env.OBS_DB.prepare(
    `SELECT correction_id, source_id, locator, original_name, corrected_name,
            original_taxon_name, corrected_taxon_name, correction_kind,
            official_source_url, official_reference, verification_status,
            verified_by_user_id, applies_from, source_payload_json, created_at, updated_at
       FROM reference_corrections
      WHERE source_id = ?
      ORDER BY verification_status = 'official_confirmed' DESC, created_at DESC
      LIMIT 40`
  ).bind(normalizedSourceId).all<ReferenceCorrectionD1Row>()).results;
  return json({ ok: true, corrections: rows.map(referenceCorrectionPayload) }, 200, { "cache-control": "no-store" });
}

async function handleReferenceLibraryRuntime(request: Request, url: URL, env: Env): Promise<Response | null> {
  const pathname = stripPublicLangPrefix(url.pathname);
  const correctionMatch = pathname.match(/^\/api\/v1\/references\/([^/]+)\/corrections$/);
  const isReferencePath = pathname === "/api/v1/references"
    || pathname === "/api/v1/references/capture-batches"
    || pathname === "/api/v1/references/duplicates/merge"
    || Boolean(correctionMatch?.[1]);
  if (!isReferencePath) return null;

  const session = await readCompatibleSession(request, env);
  if (!session) return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
  if (session.banned) return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });

  if (pathname === "/api/v1/references" && request.method === "GET") {
    return listReferenceLibraryNative(env, session, url);
  }
  if (pathname === "/api/v1/references/capture-batches" && request.method === "POST") {
    return createReferenceCaptureBatchNative(env, session, request);
  }
  if (pathname === "/api/v1/references/duplicates/merge" && request.method === "POST") {
    return mergeReferenceDuplicateNative(env, session, request);
  }
  if (correctionMatch?.[1] && request.method === "GET") {
    return listReferenceCorrectionsNative(env, decodeURIComponent(correctionMatch[1]));
  }
  if (correctionMatch?.[1] && request.method === "POST") {
    return createReferenceCorrectionNative(env, session, decodeURIComponent(correctionMatch[1]), request);
  }
  return json({ ok: false, error: "method_not_allowed" }, 405, { "cache-control": "no-store" });
}

function stringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

function asPlainObject(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function jsonArray(value: string): unknown[] {
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function jsonObject(value: string): Record<string, unknown> {
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}

function roundPublicEventCoordinate(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function observationEventMeshKey(lat: number, lng: number): string {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return "";
  const rounded = (v: number): string => {
    const sign = v < 0 ? "-" : "";
    const abs = Math.abs(v);
    return `${sign}${Math.floor(abs * 1000) / 1000}`;
  };
  return `${rounded(lat)},${rounded(lng)}`;
}

function observationEventMeshCenter(meshKey: string): { lat: number; lng: number } | null {
  const [latRaw, lngRaw] = meshKey.split(",");
  const lat = Number(latRaw);
  const lng = Number(lngRaw);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat: lat + 0.0005, lng: lng + 0.0005 };
}

async function listCompatibleReferenceCandidates(occurrenceId: string, request: Request, env: Env): Promise<Response> {
  const normalizedOccurrenceId = normalizeOptionalId(occurrenceId);
  if (!normalizedOccurrenceId || normalizedOccurrenceId.length > 160) {
    return json({ ok: false, error: "not_found" }, 404, { "cache-control": "no-store" });
  }

  let session: SessionSnapshot | null = null;
  try {
    session = await readCompatibleSession(request, env);
  } catch {
    return json({ ok: false, error: "auth_store_unavailable" }, 503, { "cache-control": "no-store" });
  }
  if (!session) {
    return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
  }
  if (session.banned) {
    return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });
  }

  const proposedName = normalizeReferenceText(new URL(request.url).searchParams.get("proposedName"), 120).toLowerCase();
  const limit = Math.min(12, Math.max(1, integerOrNull(new URL(request.url).searchParams.get("limit")) ?? 8));
  const rows = (await env.OBS_DB.prepare(
    `SELECT rs.source_id, rs.title, rs.author_text, rs.publisher, rs.publication_year,
            rs.isbn, rs.doi, rs.url, rs.source_kind, rs.catalog_status,
            rs.taxon_labels_json, rs.commerce_links_json, rs.created_by_user_id,
            rs.source_payload_json, rs.created_at, rs.updated_at,
            CASE WHEN EXISTS (
              SELECT 1 FROM reference_access_proofs p
               WHERE p.source_id = rs.source_id AND p.user_id = ?
                 AND p.verification_status IN ('ai_verified', 'user_confirmed', 'reviewer_confirmed')
            ) THEN 'owned_verified' ELSE 'not_owned' END AS owned_status,
            (SELECT COUNT(*) FROM reference_identification_selections sel
              WHERE sel.source_id = rs.source_id AND sel.selected_by_user_id = ?) AS used_count
       FROM reference_sources rs
      WHERE rs.catalog_status NOT IN ('withdrawn', 'duplicate')
      ORDER BY rs.updated_at DESC
      LIMIT ?`
  ).bind(session.userId, session.userId, limit).all<ReferenceSourceD1Row>()).results;
  const candidates = rows
    .map((row) => {
      const labels = jsonArray(row.taxon_labels_json).map((item) => normalizeReferenceText(item, 120)).filter(Boolean);
      const matched = proposedName ? labels.some((label) => label.toLowerCase().includes(proposedName) || proposedName.includes(label.toLowerCase())) : false;
      return {
        sourceId: row.source_id,
        title: row.title,
        authorText: row.author_text,
        publisher: row.publisher,
        publicationYear: row.publication_year,
        isbn: row.isbn,
        taxonLabels: labels,
        owned: row.owned_status === "owned_verified",
        verificationStatus: row.owned_status ?? "not_owned",
        linkType: matched ? "user_confirmed" : "catalog",
        usedCount: Number(row.used_count ?? 0),
        reason: row.owned_status === "owned_verified"
          ? "自分の所有確認済み資料"
          : matched
            ? "共有カタログで分類群一致"
            : "共有カタログ候補",
      };
    })
    .filter((candidate) => !proposedName || candidate.taxonLabels.length === 0 || candidate.taxonLabels.some((label) => label.toLowerCase().includes(proposedName) || proposedName.includes(label.toLowerCase())))
    .slice(0, limit);

  return json({
    ok: true,
    candidates,
    source: "cloudflare_reference_library_runtime",
    referenceCatalogStatus: "d1_native",
    occurrenceId: normalizedOccurrenceId,
  }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "reference-library-runtime" });
}

async function confirmCompatibleManagementCandidate(observationId: string, index: string, request: Request, env: Env): Promise<Response> {
  const normalizedObservationId = normalizeOptionalId(observationId);
  if (!normalizedObservationId || normalizedObservationId.length > 160) {
    return json({ ok: false, error: "not_found" }, 404, { "cache-control": "no-store" });
  }
  const candidateIndex = Number(index);
  if (!Number.isInteger(candidateIndex) || candidateIndex < 0) {
    return json({ ok: false, error: "invalid_candidate_index" }, 400, { "cache-control": "no-store" });
  }

  let session: SessionSnapshot | null = null;
  try {
    session = await readCompatibleSession(request, env);
  } catch {
    return json({ ok: false, error: "auth_store_unavailable" }, 503, { "cache-control": "no-store" });
  }
  if (!session) {
    return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
  }
  if (session.banned) {
    return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });
  }
  const ownerUserId = await resolveCompatibleObservationOwnerUserId(normalizedObservationId, env);
  if (!ownerUserId) {
    return json({ ok: false, error: "observation_not_found" }, 404, { "cache-control": "no-store" });
  }
  if (ownerUserId !== session.userId) {
    return json({ ok: false, error: "observation_not_owned" }, 403, { "cache-control": "no-store" });
  }

  let body: Record<string, unknown>;
  try {
    body = await readJson<Record<string, unknown>>(request);
  } catch {
    return json({ ok: false, error: "invalid_json" }, 400, { "cache-control": "no-store" });
  }
  const confirmState = normalizeOptionalText(body.confirmState);
  if (confirmState !== "suggested" && confirmState !== "confirmed" && confirmState !== "rejected") {
    return json({ ok: false, error: "invalid_confirm_state" }, 400, { "cache-control": "no-store" });
  }

  const confirmationId = newId("mgmt_confirm");
  const sourcePayload = {
    source: "cloudflare_management_candidate_confirmation_ledger",
    observationId: normalizedObservationId,
    candidateIndex,
    confirmState
  };
  await env.OBS_DB.prepare(
    `INSERT INTO management_candidate_confirmations (
       confirmation_id, observation_id, candidate_index, confirm_state, actor_user_id, source_payload_json
     ) VALUES (?, ?, ?, ?, ?, ?)
     ON CONFLICT(observation_id, candidate_index, actor_user_id) DO UPDATE SET
       confirm_state = excluded.confirm_state,
       source_payload_json = excluded.source_payload_json,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(
    confirmationId,
    normalizedObservationId,
    candidateIndex,
    confirmState,
    session.userId,
    JSON.stringify(sourcePayload)
  ).run();

  return json({
    ok: true,
    candidate: {
      actionKind: "unknown",
      label: "",
      why: "",
      confidence: null,
      source: "cloudflare_management_candidate_confirmation_ledger",
      sourceAssetId: null,
      confirmState
    },
    stewardshipActionId: null,
    compatibility: {
      source: "cloudflare_management_candidate_confirmation_ledger",
      stewardshipActionStatus: "not_migrated"
    }
  }, 200, { "cache-control": "no-store" });
}

const MANAGEMENT_GOALS: ManagementGoal[] = ["balanced", "keep_clear", "native_patch", "flowering_allowed", "invasive_watch"];
const WEED_TOLERANCES: WeedTolerance[] = ["low", "medium", "high"];
const INVASIVE_RESPONSES: InvasivePolicyResponse[] = ["ask_first", "controlled_removal", "observe"];
const MOWING_FREQUENCIES: MowingFrequency[] = ["as_needed", "monthly", "seasonal", "rare"];

function pickAllowed<T extends string>(value: unknown, allowed: readonly T[], fallback: T): T {
  return typeof value === "string" && allowed.includes(value as T) ? value as T : fallback;
}

function normalizeManagementPolicyNotes(value: unknown): string {
  if (typeof value !== "string") return "";
  return value.replace(/\s+/g, " ").trim().slice(0, 600);
}

function normalizeCompatiblePlaceManagementPolicyInput(
  input: CompatiblePlaceManagementPolicyInput
): Omit<CompatiblePlaceManagementPolicy, "placeId" | "userId" | "updatedAt"> {
  return {
    managementGoal: pickAllowed(input.managementGoal, MANAGEMENT_GOALS, "balanced"),
    weedTolerance: pickAllowed(input.weedTolerance, WEED_TOLERANCES, "medium"),
    invasiveResponse: pickAllowed(input.invasiveResponse, INVASIVE_RESPONSES, "ask_first"),
    mowingFrequency: pickAllowed(input.mowingFrequency, MOWING_FREQUENCIES, "as_needed"),
    notes: normalizeManagementPolicyNotes(input.notes)
  };
}

function mapPlaceManagementPolicyRow(row: {
  place_id: string;
  user_id: string;
  management_goal: string;
  weed_tolerance: string;
  invasive_response: string;
  mowing_frequency: string;
  notes: string | null;
  updated_at: string | null;
}): CompatiblePlaceManagementPolicy {
  return {
    placeId: row.place_id,
    userId: row.user_id,
    managementGoal: pickAllowed(row.management_goal, MANAGEMENT_GOALS, "balanced"),
    weedTolerance: pickAllowed(row.weed_tolerance, WEED_TOLERANCES, "medium"),
    invasiveResponse: pickAllowed(row.invasive_response, INVASIVE_RESPONSES, "ask_first"),
    mowingFrequency: pickAllowed(row.mowing_frequency, MOWING_FREQUENCIES, "as_needed"),
    notes: row.notes ?? "",
    updatedAt: row.updated_at
  };
}

async function saveCompatiblePlaceManagementPolicy(placeId: string, request: Request, env: Env): Promise<Response> {
  const normalizedPlaceId = placeId.trim();
  if (!normalizedPlaceId) return json({ ok: false, error: "place_id_required" }, 400, { "cache-control": "no-store" });
  let session: SessionSnapshot | null = null;
  try {
    session = await readCompatibleSession(request, env);
  } catch {
    return json({ ok: false, error: "auth_store_unavailable" }, 503, { "cache-control": "no-store" });
  }
  if (!session) return json({ ok: false, error: "login_required" }, 401, { "cache-control": "no-store" });
  if (session.banned) return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });

  let body: CompatiblePlaceManagementPolicyInput = {};
  try {
    body = await request.json() as CompatiblePlaceManagementPolicyInput;
  } catch {
    body = {};
  }
  const policy = normalizeCompatiblePlaceManagementPolicyInput(body);
  const row = await env.OBS_DB.prepare(
    `INSERT INTO place_management_policies (
       place_id, user_id, management_goal, weed_tolerance, invasive_response,
       mowing_frequency, notes, policy_json, updated_at
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(place_id, user_id) DO UPDATE SET
       management_goal = excluded.management_goal,
       weed_tolerance = excluded.weed_tolerance,
       invasive_response = excluded.invasive_response,
       mowing_frequency = excluded.mowing_frequency,
       notes = excluded.notes,
       policy_json = excluded.policy_json,
       updated_at = CURRENT_TIMESTAMP
     RETURNING place_id, user_id, management_goal, weed_tolerance, invasive_response,
       mowing_frequency, notes, updated_at`
  ).bind(
    normalizedPlaceId,
    session.userId,
    policy.managementGoal,
    policy.weedTolerance,
    policy.invasiveResponse,
    policy.mowingFrequency,
    policy.notes || null,
    JSON.stringify({ source: "cloudflare_place_management_policy_runtime" })
  ).first<{
    place_id: string;
    user_id: string;
    management_goal: string;
    weed_tolerance: string;
    invasive_response: string;
    mowing_frequency: string;
    notes: string | null;
    updated_at: string | null;
  }>();
  if (!row) return json({ ok: false, error: "save_failed" }, 500, { "cache-control": "no-store" });
  return json({ ok: true, policy: mapPlaceManagementPolicyRow(row) }, 200, {
    "cache-control": "no-store",
    "x-ikimon-cloudflare-native": "place-management-policy-runtime"
  });
}

async function requestCompatibleCandidateAction(
  observationId: string,
  candidateId: string,
  actionKind: "propose" | "adopt",
  request: Request,
  env: Env
): Promise<Response> {
  const normalizedObservationId = normalizeOptionalId(observationId);
  const normalizedCandidateId = normalizeOptionalId(candidateId);
  if (!normalizedObservationId || normalizedObservationId.length > 160 || !normalizedCandidateId || normalizedCandidateId.length > 160) {
    return json({ ok: false, error: "not_found" }, 404, { "cache-control": "no-store" });
  }

  let session: SessionSnapshot | null = null;
  try {
    session = await readCompatibleSession(request, env);
  } catch {
    return json({ ok: false, error: "auth_store_unavailable" }, 503, { "cache-control": "no-store" });
  }
  if (!session) {
    return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
  }
  if (session.banned) {
    return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });
  }

  const ownerUserId = await resolveCompatibleObservationOwnerUserId(normalizedObservationId, env);
  if (!ownerUserId) {
    return json({ ok: false, error: "observation_not_found" }, 404, { "cache-control": "no-store" });
  }
  if (actionKind === "adopt" && ownerUserId !== session.userId) {
    return json({ ok: false, error: "observation_not_owned" }, 403, { "cache-control": "no-store" });
  }

  const requestId = newId("candidate_action_req");
  const sourcePayload = {
    source: "cloudflare_candidate_action_request_ledger",
    observationId: normalizedObservationId,
    candidateId: normalizedCandidateId,
    actionKind,
    ownerUserId
  };
  await env.OBS_DB.prepare(
    `INSERT INTO candidate_action_requests (
       request_id, observation_id, candidate_id, action_kind, actor_user_id, request_state, source_payload_json
     ) VALUES (?, ?, ?, ?, ?, 'pending', ?)
     ON CONFLICT(observation_id, candidate_id, action_kind, actor_user_id) DO UPDATE SET
       request_state = 'pending',
       source_payload_json = excluded.source_payload_json,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(
    requestId,
    normalizedObservationId,
    normalizedCandidateId,
    actionKind,
    session.userId,
    JSON.stringify(sourcePayload)
  ).run();

  return json({
    ok: true,
    candidateAction: {
      requestId,
      state: "pending",
      actionKind
    },
    compatibility: {
      source: "cloudflare_candidate_action_request_ledger",
      occurrenceStatus: "not_migrated"
    }
  }, 202, { "cache-control": "no-store" });
}

async function requestCompatibleObservationReassessment(observationId: string, requestKind: "standard" | "video", request: Request, env: Env): Promise<Response> {
  const normalizedObservationId = normalizeOptionalId(observationId);
  if (!normalizedObservationId || normalizedObservationId.length > 160) {
    return json({ ok: false, error: "not_found" }, 404, { "cache-control": "no-store" });
  }

  let session: SessionSnapshot | null = null;
  try {
    session = await readCompatibleSession(request, env);
  } catch {
    return json({ ok: false, error: "auth_store_unavailable" }, 503, { "cache-control": "no-store" });
  }
  if (!session) {
    return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
  }
  if (session.banned) {
    return json({ ok: false, error: "account_unavailable" }, 403, { "cache-control": "no-store" });
  }

  const ownerUserId = await resolveCompatibleObservationOwnerUserId(normalizedObservationId, env);
  if (!ownerUserId) {
    return json({ ok: false, error: "observation_not_found" }, 404, { "cache-control": "no-store" });
  }
  if (ownerUserId !== session.userId) {
    return json({ ok: false, error: "observation_not_owned" }, 403, { "cache-control": "no-store" });
  }

  if (requestKind === "standard") {
    const image = await env.OBS_DB.prepare(
      `SELECT asset_id
         FROM asset_ledger
        WHERE observation_id = ?
          AND processing_state = 'uploaded'
          AND mime LIKE 'image/%'
        LIMIT 1`
    ).bind(normalizedObservationId).first<{ asset_id: string }>();
    if (!image?.asset_id) {
      return json({ ok: false, error: "observation_image_required" }, 422, { "cache-control": "no-store" });
    }
  }

  const emptyDispatch = { sent: 0, pending: 0, errors: [] as string[] };
  const responseFor = (row: { request_id: string; request_state: string }, dispatch = emptyDispatch): Response => json({
    ok: true,
    reassessment: {
      requestId: row.request_id,
      state: row.request_state,
      kind: requestKind
    },
    compatibility: {
      source: "cloudflare_observation_reassessment_request_ledger",
      executionStatus: requestKind === "standard" ? "queued" : "not_migrated"
    },
    dispatch
  }, row.request_state === "completed" ? 200 : 202, { "cache-control": "no-store" });

  const existing = await env.OBS_DB.prepare(
    `SELECT request_id, request_state, source_payload_json
       FROM observation_reassessment_requests
      WHERE observation_id = ? AND request_kind = ? AND actor_user_id = ?
      LIMIT 1`
  ).bind(normalizedObservationId, requestKind, session.userId).first<{
    request_id: string;
    request_state: string;
    source_payload_json: string;
  }>();
  const obsoleteCompletedInteractiveResult = existing?.request_state === "completed"
    && requestKind === "standard"
    && isObsoleteInteractiveGeminiResult(existing.source_payload_json);
  if (existing && (["pending", "processing"].includes(existing.request_state)
    || (existing.request_state === "completed" && !obsoleteCompletedInteractiveResult))) {
    return responseFor(existing);
  }
  if (existing && existing.request_state !== "failed" && !obsoleteCompletedInteractiveResult) {
    return json({ ok: false, error: "reassessment_not_retryable" }, 409, { "cache-control": "no-store" });
  }

  if (existing) {
    const attemptCount = reassessmentAttemptCount(existing.source_payload_json);
    if (requestKind === "standard" && (obsoleteCompletedInteractiveResult || attemptCount >= 3)) {
      const previous = reassessmentPayload(existing.source_payload_json);
      const previousErrorCode = typeof previous.errorCode === "string" ? previous.errorCode.slice(0, 180) : null;
      const previousFailedAt = typeof previous.failedAt === "string" ? previous.failedAt : null;
      const previousCompletedAt = typeof previous.completedAt === "string" ? previous.completedAt : null;
      const outboxAiId = "outbox_" + existing.request_id + "_manual_" + crypto.randomUUID().replace(/-/gu, "");
      delete previous.batchExecution;
      delete previous.errorCode;
      delete previous.failedAt;
      const nextPayload = JSON.stringify({
        ...previous,
        source: "cloudflare_observation_reassessment_request_ledger",
        enqueueId: outboxAiId,
        executionStatus: "pending",
        attemptCount: 0,
        requestedAt: new Date().toISOString(),
        retryTrigger: "explicit_owner",
        previousErrorCode,
        previousAttemptCount: attemptCount,
        ...(previousFailedAt ? { previousFailedAt } : {}),
        ...(previousCompletedAt ? { previousCompletedAt } : {}),
      });
      const updated = await env.OBS_DB.prepare(
        "UPDATE observation_reassessment_requests SET request_state = 'pending', source_payload_json = ?, updated_at = CURRENT_TIMESTAMP WHERE request_id = ? AND request_state = ? AND source_payload_json = ?"
      ).bind(nextPayload, existing.request_id, obsoleteCompletedInteractiveResult ? "completed" : "failed", existing.source_payload_json).run() as { meta?: { changes?: number } };
      if (Number(updated.meta?.changes ?? 0) === 0) {
        const current = await env.OBS_DB.prepare(
          "SELECT request_id, request_state, source_payload_json FROM observation_reassessment_requests WHERE observation_id = ? AND request_kind = ? AND actor_user_id = ? LIMIT 1"
        ).bind(normalizedObservationId, requestKind, session.userId).first<{ request_id: string; request_state: string; source_payload_json: string }>();
        return current ? responseFor(current) : json({ ok: false, error: "reassessment_state_unavailable" }, 503, { "cache-control": "no-store" });
      }
      await env.OBS_DB.prepare(
        "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
      ).bind(outboxAiId, "observation.reassess", normalizedObservationId, JSON.stringify({ observationId: normalizedObservationId, requestKind, retryTrigger: "explicit_owner" }), null).run();
      const dispatch = await dispatchOutboxBestEffort(env, [{ outboxId: outboxAiId, topic: "observation.reassess", targetId: normalizedObservationId }]);
      return responseFor({ request_id: existing.request_id, request_state: "pending" }, dispatch);
    }
    if (attemptCount >= 3) {
      return json({ ok: false, error: "reassessment_retry_exhausted" }, 409, { "cache-control": "no-store" });
    }
    const outboxAiId = `outbox_${existing.request_id}_retry_${attemptCount + 1}`;
    const nextPayload = reassessmentPayloadWithResult(existing.source_payload_json, {
      source: "cloudflare_observation_reassessment_request_ledger",
      enqueueId: outboxAiId,
      retryRequestedAt: new Date().toISOString(),
    });
    const updated = await env.OBS_DB.prepare(
      `UPDATE observation_reassessment_requests
          SET request_state = 'pending', source_payload_json = ?, updated_at = CURRENT_TIMESTAMP
        WHERE request_id = ? AND request_state = 'failed' AND source_payload_json = ?`
    ).bind(nextPayload, existing.request_id, existing.source_payload_json).run() as { meta?: { changes?: number } };
    if (Number(updated.meta?.changes ?? 0) === 0) {
      const current = await env.OBS_DB.prepare(
        `SELECT request_id, request_state, source_payload_json
           FROM observation_reassessment_requests
          WHERE observation_id = ? AND request_kind = ? AND actor_user_id = ?
          LIMIT 1`
      ).bind(normalizedObservationId, requestKind, session.userId).first<{ request_id: string; request_state: string; source_payload_json: string }>();
      return current ? responseFor(current) : json({ ok: false, error: "reassessment_state_unavailable" }, 503, { "cache-control": "no-store" });
    }
    if (requestKind === "standard") {
      await env.OBS_DB.prepare(
        "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
      ).bind(outboxAiId, "observation.reassess", normalizedObservationId, JSON.stringify({ observationId: normalizedObservationId, requestKind }), null).run();
      const dispatch = await dispatchOutboxBestEffort(env, [{ outboxId: outboxAiId, topic: "observation.reassess", targetId: normalizedObservationId }]);
      return responseFor({ request_id: existing.request_id, request_state: "pending" }, dispatch);
    }
    return responseFor({ request_id: existing.request_id, request_state: "pending" });
  }

  const requestId = newId("reassess_req");
  const outboxAiId = `outbox_${requestId}_initial`;
  const sourcePayload = {
    source: "cloudflare_observation_reassessment_request_ledger",
    observationId: normalizedObservationId,
    requestKind,
    attemptCount: 0,
    enqueueId: requestKind === "standard" ? outboxAiId : null,
    requestedAt: new Date().toISOString()
  };
  await env.OBS_DB.prepare(
    `INSERT OR IGNORE INTO observation_reassessment_requests (
       request_id, observation_id, request_kind, actor_user_id, request_state, source_payload_json
     ) VALUES (?, ?, ?, ?, 'pending', ?)`
  ).bind(requestId, normalizedObservationId, requestKind, session.userId, JSON.stringify(sourcePayload)).run();
  const persisted = await env.OBS_DB.prepare(
    `SELECT request_id, request_state, source_payload_json
       FROM observation_reassessment_requests
      WHERE observation_id = ? AND request_kind = ? AND actor_user_id = ?
      LIMIT 1`
  ).bind(normalizedObservationId, requestKind, session.userId).first<{ request_id: string; request_state: string; source_payload_json: string }>();
  if (!persisted) return json({ ok: false, error: "reassessment_state_unavailable" }, 503, { "cache-control": "no-store" });
  if (persisted.request_id !== requestId) return responseFor(persisted);

  if (requestKind === "standard") {
    await env.OBS_DB.prepare(
      "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxAiId, "observation.reassess", normalizedObservationId, JSON.stringify({ observationId: normalizedObservationId, requestKind }), null).run();
    const dispatch = await dispatchOutboxBestEffort(env, [{ outboxId: outboxAiId, topic: "observation.reassess", targetId: normalizedObservationId }]);
    return responseFor(persisted, dispatch);
  }
  return responseFor(persisted);
}

async function resolveCompatibleObservationOwnerUserId(observationId: string, env: Env): Promise<string | null> {
  const nativeObservation = await env.OBS_DB.prepare(
    "SELECT owner_user_id FROM observations WHERE observation_id = ?"
  ).bind(observationId).first<{ owner_user_id: string | null }>();
  if (nativeObservation?.owner_user_id) return nativeObservation.owner_user_id;

  const importedVisit = await env.OBS_DB.prepare(
    `SELECT user_id
     FROM production_import_visits
     WHERE visit_id = ? OR legacy_observation_id = ?
     LIMIT 1`
  ).bind(observationId, observationId).first<{ user_id: string | null }>();
  if (importedVisit?.user_id) return importedVisit.user_id;

  const importedOccurrence = await env.OBS_DB.prepare(
    `SELECT v.user_id
     FROM production_import_occurrences o
     JOIN production_import_visits v ON v.visit_id = o.visit_id
     WHERE o.occurrence_id = ?
     LIMIT 1`
  ).bind(observationId).first<{ user_id: string | null }>();
  return importedOccurrence?.user_id ?? null;
}

