async function createPublicMapPlaceCorrectionProposal(request: Request, env: Env): Promise<Response> {
  const session = await readCompatibleSession(request, env).catch(() => null);
  if (!session || session.banned) {
    return json({ error: "authentication_required" }, 401, {
      "cache-control": "no-store",
      "x-ikimon-cloudflare-native": "map-place-correction-proposal",
    });
  }
  const body = await request.json().catch(() => null) as {
    placeId?: unknown;
    proposalType?: unknown;
    proposedPayload?: unknown;
  } | null;
  const proposalType = normalizeOptionalText(body?.proposalType);
  const allowedTypes = new Set([
    "name", "alias", "boundary", "place_kind", "relationship", "membership", "policy",
  ]);
  if (!proposalType || !allowedTypes.has(proposalType)) {
    return json({ error: "invalid_proposal_type" }, 400, {
      "cache-control": "no-store",
      "x-ikimon-cloudflare-native": "map-place-correction-proposal",
    });
  }
  const payload = JSON.stringify(body?.proposedPayload ?? null);
  if (payload.length < 2 || payload.length > 20_000) {
    return json({ error: "invalid_proposal_payload" }, 400, {
      "cache-control": "no-store",
      "x-ikimon-cloudflare-native": "map-place-correction-proposal",
    });
  }
  const proposalId = crypto.randomUUID();
  try {
    await env.OBS_DB.prepare(
      `INSERT INTO place_correction_proposals (
         proposal_id, place_id, proposer_user_id, proposal_type,
         proposed_payload_json, proposal_status
       ) VALUES (?, ?, ?, ?, ?, 'pending')`
    ).bind(
      proposalId,
      normalizeOptionalText(body?.placeId),
      session.userId,
      proposalType,
      payload,
    ).run();
    return json({
      proposal: { proposalId, status: "pending" },
      directMutation: false,
    }, 202, {
      "cache-control": "no-store",
      "x-ikimon-cloudflare-native": "map-place-correction-proposal",
    });
  } catch (error) {
    console.warn("[map-place-correction-proposal] queue unavailable", error);
    return json({ error: "place_correction_queue_unavailable", retryable: true }, 503, {
      "cache-control": "no-store",
      "x-ikimon-cloudflare-native": "map-place-correction-proposal",
    });
  }
}

async function getPublicMapObservations(url: URL, env: Env): Promise<Response> {
  const bbox = parseBboxParam(url.searchParams.get("bbox"));
  const rawCellId = normalizeOptionalText(url.searchParams.get("cell_id"));
  const selectedCell = rawCellId ? cellIdToPublicCell(rawCellId) : null;
  if (!bbox && !selectedCell) {
    return json({ error: "missing_scope" }, 400);
  }

  const limit = clampInteger(Number(url.searchParams.get("limit") ?? "300"), 1, 1200);
  const rows = await queryPublicMapRows(env);
  const scopedRows = rows
    .filter((row) => selectedCell ? row.public_cell === selectedCell : publicCellInBbox(row.public_cell, bbox as [number, number, number, number]))
    .sort((a, b) => b.observed_at.localeCompare(a.observed_at))
    .slice(0, limit);
  const photoUrls = await queryPublicMapPhotoUrls(env);

  return json({
    items: scopedRows.map((row) => publicMapObservationItem(row, photoUrls.get(row.observation_id) ?? null)),
    stats: {
      totalReturned: scopedRows.length,
      totalAll: scopedRows.length,
      markerProfile: "all_research_artifacts",
      gridM: MAP_DEFAULT_GRID_M,
      selectedCellId: selectedCell ? publicCellToCellId(selectedCell) : null,
      privacy: publicMapExactCoordinateGate(),
      provenance: publicMapEmptyProvenance(scopedRows.length)
    }
  }, 200, { "cache-control": "no-store" });
}

