const GBIF_OCCURRENCE_SEARCH_ENDPOINT = "https://api.gbif.org/v1/occurrence/search";
const GBIF_SPECIES_ENDPOINT = "https://api.gbif.org/v1/species";
const GBIF_AREA_CACHE_TTL_DAYS = 30;
const GBIF_AREA_MIN_QUERY_GRID_M = 10_000;
const GBIF_AREA_JAPAN_BBOX = { minLng: 122.9, minLat: 24.0, maxLng: 146.0, maxLat: 45.6 };
const GBIF_AREA_SCHEDULE_GRID_DEGREES = 1.8;
const GBIF_AREA_DAILY_REFRESH_LIMIT = 12;

async function getGbifAreaSummary(url: URL, env: Env): Promise<Response> {
  const cellId = normalizeOptionalText(url.searchParams.get("cell_id"));
  if (!cellId) return json({ error: "missing_cell_id" }, 400, { "cache-control": "no-store" });
  const queryCell = resolveGbifQueryCell(cellId);
  if (!queryCell) return json({ error: "invalid_cell_id" }, 400, { "cache-control": "no-store" });
  const summary = await getGbifAreaSummaryForCell(env, queryCell);
  return json(summary, 200, { "cache-control": "no-store" });
}

async function getGbifAreaSummaryForCell(env: Env, queryCell: GbifQueryCell, options: { forceRefresh?: boolean } = {}): Promise<GbifAreaSummary> {
  const cached = options.forceRefresh ? null : await readCachedGbifAreaSummary(env, queryCell.cellId, true);
  if (cached) return cached;
  try {
    const refreshed = await fetchGbifAreaSummary(env, queryCell);
    await writeGbifAreaSummary(env, refreshed);
    return refreshed;
  } catch (error) {
    await writeGbifAreaSummaryRefreshError(env, queryCell, error);
    const stale = await readCachedGbifAreaSummary(env, queryCell.cellId, false);
    if (stale) return stale;
    const now = new Date();
    const expires = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    return {
      cellId: queryCell.cellId,
      queryCellId: queryCell.queryCellId,
      queryGridM: queryCell.queryGridM,
      totalRecords: 0,
      latestYear: null,
      topTaxa: [],
      sourceProvider: "GBIF",
      sourceUrl: sourceUrlForGbifQueryCell(queryCell),
      licenseScope: "CC0_1_0,CC_BY_4_0",
      citationText: gbifAreaCitationText(),
      generatedAt: now.toISOString(),
      expiresAt: expires.toISOString(),
      policy: gbifAreaDisplayPolicy(),
      evidenceContract: gbifAreaEvidenceContract(sourceUrlForGbifQueryCell(queryCell), "CC0_1_0,CC_BY_4_0")
    };
  }
}

async function readCachedGbifAreaSummary(env: Env, cellId: string, freshOnly: boolean): Promise<GbifAreaSummary | null> {
  const now = new Date().toISOString();
  const row = await env.OBS_DB.prepare(
    `SELECT cell_id, query_cell_id, query_grid_m, source_url, license_scope, total_records,
            top_taxa_json, latest_year, citation_text, generated_at, expires_at
       FROM gbif_area_summary_cache
      WHERE cell_id = ?
        AND (? = 0 OR expires_at > ?)
      LIMIT 1`
  ).bind(cellId, freshOnly ? 1 : 0, now).first<GbifAreaSummaryRow>();
  return row ? gbifAreaSummaryFromRow(row) : null;
}

async function writeGbifAreaSummary(env: Env, summary: GbifAreaSummary): Promise<void> {
  await env.OBS_DB.prepare(
    `INSERT INTO gbif_area_summary_cache (
       cell_id, query_cell_id, query_grid_m, source_url, license_scope, total_records,
       top_taxa_json, latest_year, citation_text, generated_at, expires_at, refresh_error
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)
     ON CONFLICT(cell_id) DO UPDATE SET
       query_cell_id = excluded.query_cell_id,
       query_grid_m = excluded.query_grid_m,
       source_url = excluded.source_url,
       license_scope = excluded.license_scope,
       total_records = excluded.total_records,
       top_taxa_json = excluded.top_taxa_json,
       latest_year = excluded.latest_year,
       citation_text = excluded.citation_text,
       generated_at = excluded.generated_at,
       expires_at = excluded.expires_at,
       refresh_error = NULL`
  ).bind(
    summary.cellId,
    summary.queryCellId,
    summary.queryGridM,
    summary.sourceUrl,
    summary.licenseScope,
    summary.totalRecords,
    JSON.stringify(summary.topTaxa),
    summary.latestYear,
    summary.citationText,
    summary.generatedAt,
    summary.expiresAt
  ).run();
}

async function writeGbifAreaSummaryRefreshError(env: Env, queryCell: GbifQueryCell, error: unknown): Promise<void> {
  const now = new Date();
  const expires = new Date(now.getTime() + 24 * 60 * 60 * 1000);
  const message = error instanceof Error ? error.message.slice(0, 300) : "unknown_error";
  await env.OBS_DB.prepare(
    `INSERT INTO gbif_area_summary_cache (
       cell_id, query_cell_id, query_grid_m, source_url, license_scope, total_records,
       top_taxa_json, citation_text, generated_at, expires_at, refresh_error
     ) VALUES (?, ?, ?, ?, 'CC0_1_0,CC_BY_4_0', 0, '[]', ?, ?, ?, ?)
     ON CONFLICT(cell_id) DO UPDATE SET
       refresh_error = excluded.refresh_error,
       expires_at = excluded.expires_at`
  ).bind(
    queryCell.cellId,
    queryCell.queryCellId,
    queryCell.queryGridM,
    sourceUrlForGbifQueryCell(queryCell),
    gbifAreaCitationText(),
    now.toISOString(),
    expires.toISOString(),
    message
  ).run();
}

async function fetchGbifAreaSummary(env: Env, queryCell: GbifQueryCell): Promise<GbifAreaSummary> {
  const payload = await fetchGbifJson<GbifOccurrenceSearchResponse>(occurrenceSummaryUrlForGbifQueryCell(queryCell));
  const speciesCounts = gbifFacetCounts(payload, "SPECIES_KEY")
    .map((item) => ({ taxonKey: toFiniteNumber(item.name), recordCount: toFiniteNumber(item.count) }))
    .filter((item): item is { taxonKey: number; recordCount: number } => Boolean(item.taxonKey && item.recordCount))
    .slice(0, 8);
  const taxonResults = (await Promise.all(speciesCounts.map((item) => fetchGbifSpecies(env, item.taxonKey, item.recordCount))))
    .filter((item): item is GbifAreaTaxonBuildResult => item !== null);
  const topTaxa = taxonResults.map((result) => result.taxon);
  const sourceUrl = sourceUrlForGbifQueryCell(queryCell);
  await writeGbifJapaneseNameGapCandidates(env, queryCell, topTaxa, sourceUrl);
  await writeGbifJapaneseNameDisplayAudit(env, queryCell, taxonResults.map((result) => result.audit), sourceUrl);
  const latestYear = gbifFacetCounts(payload, "YEAR")
    .map((item) => toFiniteNumber(item.name))
    .filter((year): year is number => year !== null && year >= 1800 && year <= new Date().getUTCFullYear())
    .sort((a, b) => b - a)[0] ?? null;
  const now = new Date();
  const expires = new Date(now.getTime() + GBIF_AREA_CACHE_TTL_DAYS * 24 * 60 * 60 * 1000);
  return {
    cellId: queryCell.cellId,
    queryCellId: queryCell.queryCellId,
    queryGridM: queryCell.queryGridM,
    totalRecords: toFiniteNumber(payload.count) ?? 0,
    latestYear,
    topTaxa,
    sourceProvider: "GBIF",
    sourceUrl,
    licenseScope: "CC0_1_0,CC_BY_4_0",
    citationText: gbifAreaCitationText(),
    generatedAt: now.toISOString(),
    expiresAt: expires.toISOString(),
    policy: gbifAreaDisplayPolicy(),
    evidenceContract: gbifAreaEvidenceContract(sourceUrl, "CC0_1_0,CC_BY_4_0")
  };
}

async function fetchGbifSpecies(env: Env, taxonKey: number, recordCount: number): Promise<GbifAreaTaxonBuildResult | null> {
  try {
    const payload = await fetchGbifJson<GbifSpeciesResponse>(`${GBIF_SPECIES_ENDPOINT}/${encodeURIComponent(String(taxonKey))}`);
    const scientificName = gbifStringValue(payload.scientificName) || gbifStringValue(payload.canonicalName);
    if (!scientificName) return null;
    const taxonGroup = inferGbifTaxonGroup(payload);
    const gbifCommonNameJa = await fetchGbifJapaneseCommonName(taxonKey);
    const override = gbifCommonNameJa ? null : await readApprovedGbifJapaneseNameOverride(env, taxonKey);
    const commonNameJa = gbifCommonNameJa ?? override?.name_ja ?? null;
    const commonNameSource = gbifCommonNameJa ? "gbif_vernacular" : override ? "approved_override" : null;
    const canonicalName = gbifStringValue(payload.canonicalName) || scientificName;
    const rank = gbifStringValue(payload.rank) || "SPECIES";
    const displayNameJa = commonNameJa ?? `${gbifTaxonGroupLabelJa(taxonGroup)}（和名未確認）`;
    const nameStatus = commonNameJa ? "japanese_common_name" : "scientific_name_only";
    const taxon: GbifAreaTaxon = {
      taxonKey,
      scientificName,
      canonicalName,
      rank,
      taxonGroup,
      commonNameJa,
      commonNameSource,
      displayNameJa,
      nameStatus,
      recordCount
    };
    return {
      taxon,
      audit: {
        taxonKey,
        scientificName,
        canonicalName,
        rank,
        taxonGroup,
        displayNameJa,
        commonNameJa,
        commonNameSource: commonNameSource ?? "none",
        nameStatus,
        overrideStatus: override?.status ?? null,
        overrideSourceKind: override?.source_kind ?? null,
        overrideReviewedBy: override?.reviewed_by ?? null,
        overrideReviewedAt: override?.reviewed_at ?? null,
        decisionReason: gbifCommonNameJa
          ? "gbif_japanese_vernacular_name"
          : override
            ? "approved_override_name"
            : "no_approved_japanese_name"
      }
    };
  } catch {
    return null;
  }
}

async function readApprovedGbifJapaneseNameOverride(env: Env, taxonKey: number): Promise<GbifJapaneseNameOverrideRow | null> {
  return await env.OBS_DB.prepare(
    `SELECT taxon_key, name_ja, status, source_kind, source_note, reviewed_by, reviewed_at
       FROM gbif_japanese_name_overrides
      WHERE taxon_key = ?
        AND status = 'approved'
      LIMIT 1`
  ).bind(taxonKey).first<GbifJapaneseNameOverrideRow>();
}

async function writeGbifJapaneseNameGapCandidates(env: Env, queryCell: GbifQueryCell, topTaxa: GbifAreaTaxon[], sourceUrl: string): Promise<void> {
  const now = new Date().toISOString();
  const gapTaxa = topTaxa.filter((taxon) => taxon.nameStatus === "scientific_name_only" && taxon.commonNameSource === null);
  for (const taxon of gapTaxa) {
    await env.OBS_DB.prepare(
      `INSERT INTO gbif_japanese_name_gap_candidates (
         taxon_key, scientific_name, canonical_name, rank, taxon_group,
         first_seen_at, last_seen_at, seen_count, record_count_total,
         example_cell_id, example_query_cell_id, source_url, updated_at
       ) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)
       ON CONFLICT(taxon_key) DO UPDATE SET
         scientific_name = excluded.scientific_name,
         canonical_name = excluded.canonical_name,
         rank = excluded.rank,
         taxon_group = excluded.taxon_group,
         last_seen_at = excluded.last_seen_at,
         seen_count = gbif_japanese_name_gap_candidates.seen_count + 1,
         record_count_total = gbif_japanese_name_gap_candidates.record_count_total + excluded.record_count_total,
         example_cell_id = excluded.example_cell_id,
         example_query_cell_id = excluded.example_query_cell_id,
         source_url = excluded.source_url,
         updated_at = excluded.updated_at`
    ).bind(
      taxon.taxonKey,
      taxon.scientificName,
      taxon.canonicalName,
      taxon.rank,
      taxon.taxonGroup,
      now,
      now,
      taxon.recordCount,
      queryCell.cellId,
      queryCell.queryCellId,
      sourceUrl,
      now
    ).run();
  }
}

async function writeGbifJapaneseNameDisplayAudit(
  env: Env,
  queryCell: GbifQueryCell,
  decisions: GbifJapaneseNameDisplayAuditDecision[],
  sourceUrl: string
): Promise<void> {
  const now = new Date().toISOString();
  for (const decision of decisions) {
    const auditKey = `${queryCell.queryCellId}:${decision.taxonKey}:${decision.commonNameSource}:${decision.nameStatus}`;
    try {
      await env.OBS_DB.prepare(
        `INSERT INTO gbif_japanese_name_display_audit (
           audit_key, taxon_key, cell_id, query_cell_id,
           scientific_name, canonical_name, rank, taxon_group,
           display_name_ja, common_name_ja, common_name_source, name_status,
           override_status, override_source_kind, override_reviewed_by, override_reviewed_at,
           decision_reason, policy_version, source_url,
           first_seen_at, last_seen_at, seen_count, updated_at
         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'gbif_name_governance_v1', ?, ?, ?, 1, ?)
         ON CONFLICT(audit_key) DO UPDATE SET
           scientific_name = excluded.scientific_name,
           canonical_name = excluded.canonical_name,
           rank = excluded.rank,
           taxon_group = excluded.taxon_group,
           display_name_ja = excluded.display_name_ja,
           common_name_ja = excluded.common_name_ja,
           common_name_source = excluded.common_name_source,
           name_status = excluded.name_status,
           override_status = excluded.override_status,
           override_source_kind = excluded.override_source_kind,
           override_reviewed_by = excluded.override_reviewed_by,
           override_reviewed_at = excluded.override_reviewed_at,
           decision_reason = excluded.decision_reason,
           policy_version = excluded.policy_version,
           source_url = excluded.source_url,
           last_seen_at = excluded.last_seen_at,
           seen_count = gbif_japanese_name_display_audit.seen_count + 1,
           updated_at = excluded.updated_at`
      ).bind(
        auditKey,
        decision.taxonKey,
        queryCell.cellId,
        queryCell.queryCellId,
        decision.scientificName,
        decision.canonicalName,
        decision.rank,
        decision.taxonGroup,
        decision.displayNameJa,
        decision.commonNameJa,
        decision.commonNameSource,
        decision.nameStatus,
        decision.overrideStatus,
        decision.overrideSourceKind,
        decision.overrideReviewedBy,
        decision.overrideReviewedAt,
        decision.decisionReason,
        sourceUrl,
        now,
        now,
        now
      ).run();
    } catch (error) {
      if (isMissingD1TableError(error, "gbif_japanese_name_display_audit")) return;
      throw error;
    }
  }
}

async function internalListGbifJapaneseNameDisplayAudit(url: URL, env: Env): Promise<Response> {
  const limit = Math.min(100, Math.max(1, toFiniteNumber(url.searchParams.get("limit")) ?? 50));
  const taxonKey = toFiniteNumber(url.searchParams.get("taxon_key"));
  const commonNameSource = normalizeGbifNameAuditSource(url.searchParams.get("common_name_source"));
  const nameStatus = normalizeGbifNameAuditStatus(url.searchParams.get("name_status"));
  const where: string[] = [];
  const binds: Array<string | number> = [];
  if (taxonKey && taxonKey > 0) {
    where.push("taxon_key = ?");
    binds.push(taxonKey);
  }
  if (commonNameSource) {
    where.push("common_name_source = ?");
    binds.push(commonNameSource);
  }
  if (nameStatus) {
    where.push("name_status = ?");
    binds.push(nameStatus);
  }
  try {
    const rows = (await env.OBS_DB.prepare(
      `SELECT audit_key, taxon_key, cell_id, query_cell_id,
              scientific_name, canonical_name, rank, taxon_group,
              display_name_ja, common_name_ja, common_name_source, name_status,
              override_status, override_source_kind, override_reviewed_by, override_reviewed_at,
              decision_reason, policy_version, source_url,
              first_seen_at, last_seen_at, seen_count
         FROM gbif_japanese_name_display_audit
        ${where.length ? `WHERE ${where.join(" AND ")}` : ""}
        ORDER BY last_seen_at DESC, seen_count DESC, taxon_key ASC
        LIMIT ?`
    ).bind(...binds, limit).all<GbifJapaneseNameDisplayAuditRow>()).results;
    return json({ items: rows, limit, filters: { taxonKey: taxonKey ?? null, commonNameSource, nameStatus } }, 200, { "cache-control": "no-store" });
  } catch (error) {
    if (isMissingD1TableError(error, "gbif_japanese_name_display_audit")) {
      return json({ items: [], limit, filters: { taxonKey: taxonKey ?? null, commonNameSource, nameStatus } }, 200, { "cache-control": "no-store" });
    }
    throw error;
  }
}

function normalizeGbifNameAuditSource(value: unknown): "gbif_vernacular" | "approved_override" | "none" | null {
  const source = normalizeOptionalText(value);
  if (source === "gbif_vernacular" || source === "approved_override" || source === "none") return source;
  return null;
}

function normalizeGbifNameAuditStatus(value: unknown): "japanese_common_name" | "scientific_name_only" | null {
  const status = normalizeOptionalText(value);
  if (status === "japanese_common_name" || status === "scientific_name_only") return status;
  return null;
}

async function internalListGbifJapaneseNameGapCandidates(url: URL, env: Env): Promise<Response> {
  const state = normalizeGbifGapCandidateReviewState(url.searchParams.get("state")) ?? "pending";
  const limit = Math.min(100, Math.max(1, toFiniteNumber(url.searchParams.get("limit")) ?? 50));
  const rows = (await env.OBS_DB.prepare(
    `SELECT taxon_key, scientific_name, canonical_name, rank, taxon_group,
            first_seen_at, last_seen_at, seen_count, record_count_total,
            example_cell_id, example_query_cell_id, source_url, review_state, resolved_at
       FROM gbif_japanese_name_gap_candidates
      WHERE review_state = ?
      ORDER BY record_count_total DESC, seen_count DESC, last_seen_at DESC
      LIMIT ?`
  ).bind(state, limit).all<GbifJapaneseNameGapCandidateRow>()).results;
  return json({ items: rows, state, limit }, 200, { "cache-control": "no-store" });
}

function normalizeGbifGapCandidateReviewState(value: unknown): "pending" | "reviewing" | "resolved" | "ignored" | null {
  const state = normalizeOptionalText(value) ?? "pending";
  if (state === "pending" || state === "reviewing" || state === "resolved" || state === "ignored") return state;
  return null;
}

async function internalGetGbifJapaneseNameOverride(url: URL, env: Env): Promise<Response> {
  const taxonKey = toFiniteNumber(url.searchParams.get("taxon_key"));
  if (!taxonKey || taxonKey < 1) return json({ error: "invalid_taxon_key" }, 400, { "cache-control": "no-store" });
  const row = await env.OBS_DB.prepare(
    `SELECT taxon_key, name_ja, status, source_kind, source_note, reviewed_by, reviewed_at
       FROM gbif_japanese_name_overrides
      WHERE taxon_key = ?
      LIMIT 1`
  ).bind(taxonKey).first<GbifJapaneseNameOverrideRow>();
  return json({ item: row ?? null }, 200, { "cache-control": "no-store" });
}

async function internalUpsertGbifJapaneseNameOverride(request: Request, env: Env): Promise<Response> {
  const input = await readJson<Record<string, unknown>>(request);
  const taxonKey = toFiniteNumber(input.taxonKey ?? input.taxon_key);
  const nameJa = normalizeGbifJapaneseOverrideName(input.nameJa ?? input.name_ja);
  const status = normalizeGbifOverrideStatus(input.status);
  const sourceKind = normalizeGbifOverrideSourceKind(input.sourceKind ?? input.source_kind);
  const sourceNote = normalizeOptionalText(input.sourceNote ?? input.source_note) ?? "";
  const reviewedBy = normalizeOptionalText(input.reviewedBy ?? input.reviewed_by) ?? "internal";
  if (!taxonKey || taxonKey < 1) return json({ error: "invalid_taxon_key" }, 400, { "cache-control": "no-store" });
  if (!nameJa) return json({ error: "invalid_japanese_name" }, 400, { "cache-control": "no-store" });
  if (!status) return json({ error: "invalid_status" }, 400, { "cache-control": "no-store" });
  if (!sourceKind) return json({ error: "invalid_source_kind" }, 400, { "cache-control": "no-store" });
  if (status === "approved" && sourceNote.length < 3) {
    return json({ error: "source_note_required_for_approved_name" }, 400, { "cache-control": "no-store" });
  }
  const reviewedAt = status === "approved" ? new Date().toISOString() : null;
  await env.OBS_DB.prepare(
    `INSERT INTO gbif_japanese_name_overrides (
       taxon_key, name_ja, status, source_kind, source_note, reviewed_by, reviewed_at, updated_at
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(taxon_key) DO UPDATE SET
       name_ja = excluded.name_ja,
       status = excluded.status,
       source_kind = excluded.source_kind,
       source_note = excluded.source_note,
       reviewed_by = excluded.reviewed_by,
       reviewed_at = excluded.reviewed_at,
       updated_at = excluded.updated_at`
  ).bind(taxonKey, nameJa, status, sourceKind, sourceNote || null, reviewedBy, reviewedAt, new Date().toISOString()).run();
  if (status === "approved") {
    await env.OBS_DB.prepare(
      `UPDATE gbif_japanese_name_gap_candidates
          SET review_state = 'resolved',
              resolved_at = COALESCE(resolved_at, ?),
              updated_at = ?
        WHERE taxon_key = ?`
    ).bind(reviewedAt, reviewedAt, taxonKey).run();
  }
  const row = await env.OBS_DB.prepare(
    `SELECT taxon_key, name_ja, status, source_kind, source_note, reviewed_by, reviewed_at
       FROM gbif_japanese_name_overrides
      WHERE taxon_key = ?
      LIMIT 1`
  ).bind(taxonKey).first<GbifJapaneseNameOverrideRow>();
  return json({ ok: true, item: row }, 200, { "cache-control": "no-store" });
}

function normalizeGbifJapaneseOverrideName(value: unknown): string | null {
  const name = normalizeOptionalText(value);
  if (!name || name.length > 80) return null;
  if (!/[一-龯ぁ-んァ-ヶー]/u.test(name)) return null;
  return name;
}

function normalizeGbifOverrideStatus(value: unknown): "candidate" | "approved" | "rejected" | "retired" | null {
  const status = normalizeOptionalText(value) ?? "candidate";
  if (status === "candidate" || status === "approved" || status === "rejected" || status === "retired") return status;
  return null;
}

function normalizeGbifOverrideSourceKind(value: unknown): "manual_review" | "curated_source" | "operator_import" | "gbif_gap_review" | null {
  const kind = normalizeOptionalText(value) ?? "manual_review";
  if (kind === "manual_review" || kind === "curated_source" || kind === "operator_import" || kind === "gbif_gap_review") return kind;
  return null;
}

async function fetchGbifJapaneseCommonName(taxonKey: number): Promise<string | null> {
  try {
    const payload = await fetchGbifJson<GbifVernacularNameResponse>(`${GBIF_SPECIES_ENDPOINT}/${encodeURIComponent(String(taxonKey))}/vernacularNames?limit=100`);
    const candidates = (payload.results ?? [])
      .map((item) => ({
        name: gbifStringValue(item.vernacularName),
        language: gbifStringValue(item.language).toLowerCase(),
        country: gbifStringValue(item.country).toUpperCase(),
        preferred: item.preferred === true
      }))
      .filter((item) => item.name && (item.language === "jpn" || item.language === "ja" || item.country === "JP"));
    const preferred = candidates.find((item) => item.preferred) ?? candidates[0];
    return preferred?.name ?? null;
  } catch {
    return null;
  }
}

async function fetchGbifJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { headers: { accept: "application/json" } });
  if (!response.ok) throw new Error(`gbif_fetch_failed:${response.status}`);
  return await response.json() as T;
}

function gbifFacetCounts(payload: GbifOccurrenceSearchResponse, field: string): Array<{ name?: unknown; count?: unknown }> {
  const facet = (payload.facets ?? []).find((item) => gbifStringValue(item.field).toUpperCase() === field.toUpperCase());
  return Array.isArray(facet?.counts) ? facet.counts : [];
}

function gbifAreaSummaryFromRow(row: GbifAreaSummaryRow): GbifAreaSummary {
  let topTaxa: GbifAreaTaxon[] = [];
  try {
    const parsed = JSON.parse(row.top_taxa_json);
    if (Array.isArray(parsed)) {
      topTaxa = parsed
        .map((item): GbifAreaTaxon | null => {
          if (!item || typeof item !== "object") return null;
          const raw = item as Record<string, unknown>;
          const taxonKey = toFiniteNumber(raw.taxonKey);
          const recordCount = toFiniteNumber(raw.recordCount);
          const scientificName = gbifStringValue(raw.scientificName);
          if (!taxonKey || !recordCount || !scientificName) return null;
          return {
            taxonKey,
            scientificName,
            canonicalName: gbifStringValue(raw.canonicalName) || scientificName,
            commonNameJa: gbifStringValue(raw.commonNameJa) || null,
            commonNameSource: gbifAreaTaxonCommonNameSource(raw.commonNameSource),
            displayNameJa: gbifStringValue(raw.displayNameJa) || gbifStringValue(raw.commonNameJa) || scientificName,
            nameStatus: gbifStringValue(raw.nameStatus) === "japanese_common_name" ? "japanese_common_name" : "scientific_name_only",
            rank: gbifStringValue(raw.rank) || "SPECIES",
            taxonGroup: validGbifTaxonGroup(gbifStringValue(raw.taxonGroup)),
            recordCount
          };
        })
        .filter((item): item is GbifAreaTaxon => item !== null);
    }
  } catch {
    topTaxa = [];
  }
  return {
    cellId: row.cell_id,
    queryCellId: row.query_cell_id,
    queryGridM: Number(row.query_grid_m),
    totalRecords: Number(row.total_records) || 0,
    latestYear: toFiniteNumber(row.latest_year),
    topTaxa,
    sourceProvider: "GBIF",
    sourceUrl: row.source_url,
    licenseScope: "CC0_1_0,CC_BY_4_0",
    citationText: row.citation_text,
    generatedAt: row.generated_at,
    expiresAt: row.expires_at,
    policy: gbifAreaDisplayPolicy(),
    evidenceContract: gbifAreaEvidenceContract(row.source_url, "CC0_1_0,CC_BY_4_0")
  };
}

function gbifAreaTaxonCommonNameSource(value: unknown): GbifAreaTaxon["commonNameSource"] {
  const source = gbifStringValue(value);
  if (source === "gbif_vernacular" || source === "approved_override") return source;
  return null;
}

function resolveGbifQueryCell(rawCellId: string): GbifQueryCell | null {
  const normalized = rawCellId.startsWith("cell:") ? rawCellId.slice("cell:".length) : rawCellId;
  const scheduled = normalized.match(/^gbif:(\d+)km:(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)$/);
  if (scheduled) {
    const gridKm = Number(scheduled[1]);
    const lat = Number(scheduled[2]);
    const lng = Number(scheduled[3]);
    if (!validJapanLatLng(lat, lng) || !Number.isFinite(gridKm) || gridKm < 10) return null;
    const half = Math.max(0.05, gridKm / 111 / 2);
    return {
      cellId: rawCellId,
      queryCellId: `gbif:${gridKm}km:${lat.toFixed(2)},${lng.toFixed(2)}`,
      centerLat: lat,
      centerLng: lng,
      halfLat: half,
      halfLng: half,
      queryGridM: Math.round(gridKm * 1000)
    };
  }
  const parsed = parsePublicCell(normalized);
  if (!parsed || !validJapanLatLng(parsed.lat, parsed.lng)) return null;
  const centerLat = Math.round(parsed.lat * 10) / 10;
  const centerLng = Math.round(parsed.lng * 10) / 10;
  return {
    cellId: rawCellId,
    queryCellId: `gbif:10km:${centerLat.toFixed(1)},${centerLng.toFixed(1)}`,
    centerLat,
    centerLng,
    halfLat: 0.05,
    halfLng: 0.05,
    queryGridM: GBIF_AREA_MIN_QUERY_GRID_M
  };
}

function sourceUrlForGbifQueryCell(queryCell: GbifQueryCell): string {
  const url = new URL(GBIF_OCCURRENCE_SEARCH_ENDPOINT);
  url.searchParams.set("country", "JP");
  url.searchParams.set("hasCoordinate", "true");
  url.searchParams.set("hasGeospatialIssue", "false");
  url.searchParams.append("license", "CC0_1_0");
  url.searchParams.append("license", "CC_BY_4_0");
  url.searchParams.set("geometry", wktPolygonForGbifQueryCell(queryCell));
  return url.toString();
}

function occurrenceSummaryUrlForGbifQueryCell(queryCell: GbifQueryCell): string {
  const url = new URL(sourceUrlForGbifQueryCell(queryCell));
  url.searchParams.set("limit", "0");
  url.searchParams.append("facet", "speciesKey");
  url.searchParams.set("speciesKey.facetLimit", "8");
  url.searchParams.append("facet", "year");
  url.searchParams.set("year.facetLimit", "5");
  return url.toString();
}

function wktPolygonForGbifQueryCell(queryCell: GbifQueryCell): string {
  const minLat = clampGbifCoordinate(queryCell.centerLat - queryCell.halfLat, GBIF_AREA_JAPAN_BBOX.minLat, GBIF_AREA_JAPAN_BBOX.maxLat);
  const maxLat = clampGbifCoordinate(queryCell.centerLat + queryCell.halfLat, GBIF_AREA_JAPAN_BBOX.minLat, GBIF_AREA_JAPAN_BBOX.maxLat);
  const minLng = clampGbifCoordinate(queryCell.centerLng - queryCell.halfLng, GBIF_AREA_JAPAN_BBOX.minLng, GBIF_AREA_JAPAN_BBOX.maxLng);
  const maxLng = clampGbifCoordinate(queryCell.centerLng + queryCell.halfLng, GBIF_AREA_JAPAN_BBOX.minLng, GBIF_AREA_JAPAN_BBOX.maxLng);
  return `POLYGON((${minLng.toFixed(6)} ${minLat.toFixed(6)},${maxLng.toFixed(6)} ${minLat.toFixed(6)},${maxLng.toFixed(6)} ${maxLat.toFixed(6)},${minLng.toFixed(6)} ${maxLat.toFixed(6)},${minLng.toFixed(6)} ${minLat.toFixed(6)}))`;
}

function gbifAreaDisplayPolicy(): GbifAreaSummary["policy"] {
  return {
    displayMode: "area_summary",
    occurrenceClaim: "recorded_not_current_presence",
    exactCoordinatesExposed: false,
    thirdPartyMediaUsed: false,
    minQueryGridM: GBIF_AREA_MIN_QUERY_GRID_M
  };
}

function gbifAreaCitationText(): string {
  return "GBIF.org occurrence search summary, filtered to georeferenced Japan records without geospatial issues and CC0/CC BY licenses. This is an aggregate record summary, not a current-presence or population estimate.";
}

function gbifAreaEvidenceContract(sourceUrl: string, licenseScope: string): PublicEvidenceContract {
  return {
    contractVersion: "public_evidence_contract_v1",
    claimLevel: "surrounding_area_recorded",
    claimText: "この周辺で記録された公開記録のエリア集計です。現在その場所にいることや個体数を意味しません。",
    sourceProvider: "GBIF",
    sourceTypes: ["external_occurrence_area_summary"],
    rights: {
      licenseScope,
      attribution: "GBIF.org",
      attributionUrl: sourceUrl,
      commercialUse: "license_conditioned_by_cc0_cc_by_attribution",
      thirdPartyMediaUsed: false
    },
    location: {
      publicLocationMode: "area_summary",
      exactCoordinatesExposed: false,
      geometryExposed: false,
      minQueryGridM: GBIF_AREA_MIN_QUERY_GRID_M
    },
    suppression: {
      status: "source_area_summary_only",
      countRulesApplied: false,
      sensitiveTaxaPolicy: "suppress_before_count_rules",
      reason: "GBIFはエリア集計だけを返し、個別観察点・第三者写真・正確座標は公開レスポンスに含めません。"
    },
    limitations: [
      "現在の生息や個体数を保証しません。",
      "正確な観察座標と第三者写真は表示しません。",
      "CC0/CC BY の公開記録だけをエリア集計として扱います。"
    ]
  };
}

function inferGbifTaxonGroup(payload: GbifSpeciesResponse): GbifAreaTaxon["taxonGroup"] {
  const className = gbifStringValue(payload.class).toLowerCase();
  const phylum = gbifStringValue(payload.phylum).toLowerCase();
  const kingdom = gbifStringValue(payload.kingdom).toLowerCase();
  if (className === "aves") return "bird";
  if (className === "mammalia") return "mammal";
  if (className === "insecta") return "insect";
  if (className === "amphibia" || className === "reptilia") return "amphibian_reptile";
  if (kingdom === "plantae") return "plant";
  if (kingdom === "fungi" || phylum.includes("mycota")) return "fungi";
  return "other";
}

function validGbifTaxonGroup(value: string): GbifAreaTaxon["taxonGroup"] {
  if (value === "bird" || value === "plant" || value === "insect" || value === "amphibian_reptile" || value === "mammal" || value === "fungi") return value;
  return "other";
}

function gbifTaxonGroupLabelJa(group: GbifAreaTaxon["taxonGroup"]): string {
  switch (group) {
    case "bird":
      return "鳥類";
    case "mammal":
      return "哺乳類";
    case "insect":
      return "昆虫類";
    case "amphibian_reptile":
      return "両生類・爬虫類";
    case "plant":
      return "植物";
    case "fungi":
      return "菌類";
    default:
      return "生物";
  }
}

function toFiniteNumber(value: unknown): number | null {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function gbifStringValue(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

function clampGbifCoordinate(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function validJapanLatLng(lat: number, lng: number): boolean {
  return Number.isFinite(lat)
    && Number.isFinite(lng)
    && lat >= GBIF_AREA_JAPAN_BBOX.minLat
    && lat <= GBIF_AREA_JAPAN_BBOX.maxLat
    && lng >= GBIF_AREA_JAPAN_BBOX.minLng
    && lng <= GBIF_AREA_JAPAN_BBOX.maxLng;
}

async function runScheduledGbifAreaSummaryRefresh(env: Env, controller: ScheduledController): Promise<void> {
  if (!shouldRunGbifAreaSummarySchedule(controller)) return;
  const cells = buildGbifJapanScheduleCells();
  if (cells.length === 0) return;
  const cursor = await readGbifAreaSummaryCursor(env);
  const limit = GBIF_AREA_DAILY_REFRESH_LIMIT;
  for (let offset = 0; offset < limit; offset += 1) {
    const cell = cells[(cursor + offset) % cells.length];
    if (!cell) continue;
    try {
      await getGbifAreaSummaryForCell(env, cell, { forceRefresh: true });
    } catch (error) {
      console.error("gbif_area_summary_scheduled_refresh_failed", error);
    }
  }
  await writeGbifAreaSummaryCursor(env, (cursor + limit) % cells.length);
}

function shouldRunGbifAreaSummarySchedule(controller: ScheduledController): boolean {
  const scheduledAt = new Date(controller.scheduledTime ?? Date.now());
  return scheduledAt.getUTCHours() === 18 && scheduledAt.getUTCMinutes() < 5;
}

function buildGbifJapanScheduleCells(): GbifQueryCell[] {
  const cells: GbifQueryCell[] = [];
  const step = GBIF_AREA_SCHEDULE_GRID_DEGREES;
  for (let lat = GBIF_AREA_JAPAN_BBOX.minLat + step / 2; lat <= GBIF_AREA_JAPAN_BBOX.maxLat; lat += step) {
    for (let lng = GBIF_AREA_JAPAN_BBOX.minLng + step / 2; lng <= GBIF_AREA_JAPAN_BBOX.maxLng; lng += step) {
      const cellId = `gbif:200km:${lat.toFixed(2)},${lng.toFixed(2)}`;
      const cell = resolveGbifQueryCell(cellId);
      if (cell) cells.push(cell);
    }
  }
  return cells;
}

async function readGbifAreaSummaryCursor(env: Env): Promise<number> {
  const row = await env.OBS_DB.prepare(
    "SELECT state_value FROM gbif_area_summary_state WHERE state_key = 'japan_schedule_cursor' LIMIT 1"
  ).first<{ state_value: string }>();
  const value = row ? Number(row.state_value) : 0;
  return Number.isInteger(value) && value >= 0 ? value : 0;
}

async function writeGbifAreaSummaryCursor(env: Env, cursor: number): Promise<void> {
  await env.OBS_DB.prepare(
    `INSERT INTO gbif_area_summary_state (state_key, state_value, updated_at)
     VALUES ('japan_schedule_cursor', ?, ?)
     ON CONFLICT(state_key) DO UPDATE SET
       state_value = excluded.state_value,
       updated_at = excluded.updated_at`
  ).bind(String(cursor), new Date().toISOString()).run();
}

async function getPublicMapCoverage(url: URL, env: Env): Promise<Response> {
  const rawYear = numberFromSearchParam(url.searchParams.get("year"));
  const year = rawYear !== null && Number.isInteger(rawYear) && rawYear >= 2000 && rawYear <= 2100 ? rawYear : null;
  const rows = await queryPublicMapRows(env);
  const grouped = new Map<string, { lat: number; lng: number; count: number }>();
  for (const row of rows) {
    if (year !== null && !row.observed_at.startsWith(String(year))) continue;
    const parsed = parsePublicCell(row.public_cell);
    if (!parsed) continue;
    const lat = Math.round(parsed.lat * 100) / 100;
    const lng = Math.round(parsed.lng * 100) / 100;
    const mesh = `${lat.toFixed(2)},${lng.toFixed(2)}`;
    const current = grouped.get(mesh);
    if (current) current.count += 1;
    else grouped.set(mesh, { lat, lng, count: 1 });
  }
  const features = [...grouped.entries()]
    .sort((a, b) => b[1].count - a[1].count || a[0].localeCompare(b[0]))
    .slice(0, 1500)
    .map(([mesh, group]) => ({
      type: "Feature" as const,
      geometry: {
        type: "Polygon" as const,
        coordinates: [publicCellPolygon(group.lat, group.lng)]
      },
      properties: {
        mesh,
        count: group.count
      }
    }));
  const maxCount = features.reduce((max, feature) => Math.max(max, feature.properties.count), 0);
  return json({
    type: "FeatureCollection",
    features,
    maxCount,
    compatibility: {
      source: "cloudflare_readmodel_public_observations",
      exactLocationExposed: false,
      privacy: publicMapExactCoordinateGate()
    }
  }, 200, { "cache-control": "no-store" });
}

async function getPublicMapSnapshotStatusResponse(env: Env): Promise<Response> {
  const meta = await queryPublicMapSnapshotMeta(env);
  if (!meta) {
    return json({
      ok: true,
      status: "missing",
      snapshotKey: "public-map:v1:global",
      generatedAt: null,
      sourceSampleSize: 0,
      publicRecordCount: 0,
      source: "cloudflare_public_map_snapshot_missing"
    }, 200, { "cache-control": "no-store" });
  }
  return json({
    ok: true,
    status: "fresh",
    snapshotKey: meta.snapshot_key,
    generatedAt: meta.generated_at,
    sourceSampleSize: meta.source_sample_size,
    publicRecordCount: meta.public_record_count,
    refreshedBy: meta.refreshed_by,
    policy: parseJsonRecord(meta.policy_json),
    source: "cloudflare_public_map_snapshot_records_v1"
  }, 200, { "cache-control": "no-store" });
}

type JmaNowcastTarget = {
  basetime?: unknown;
  validtime?: unknown;
  member?: unknown;
  elements?: unknown;
};

type JmaNowcastSelectedTarget = {
  basetime: string;
  validtime: string;
  member?: string;
};

function isValidJmaTimestamp(value: unknown): value is string {
  return typeof value === "string" && /^\d{14}$/.test(value);
}

function parseJmaTimestamp(value: string): number | null {
  if (!isValidJmaTimestamp(value)) return null;
  const ms = Date.UTC(
    Number(value.slice(0, 4)),
    Number(value.slice(4, 6)) - 1,
    Number(value.slice(6, 8)),
    Number(value.slice(8, 10)),
    Number(value.slice(10, 12)),
    Number(value.slice(12, 14))
  );
  return Number.isFinite(ms) ? ms : null;
}

function jmaTargetSupportsRain(target: JmaNowcastTarget): boolean {
  return !Array.isArray(target.elements) || target.elements.includes("hrpns");
}

function jmaTargetSupportsShortRangeRain(target: JmaNowcastTarget): boolean {
  return !Array.isArray(target.elements) || target.elements.includes("rasrf");
}

function jmaOffsetMinutes(target: JmaNowcastTarget): number | null {
  if (!isValidJmaTimestamp(target.basetime) || !isValidJmaTimestamp(target.validtime)) return null;
  const base = parseJmaTimestamp(target.basetime);
  const valid = parseJmaTimestamp(target.validtime);
  if (base === null || valid === null) return null;
  return Math.round((valid - base) / 60_000);
}

function chooseJmaNowcastTarget(targets: JmaNowcastTarget[], offsetMinutes: number): JmaNowcastSelectedTarget | null {
  const candidates = targets
    .filter((target) => isValidJmaTimestamp(target.basetime) && isValidJmaTimestamp(target.validtime) && jmaTargetSupportsRain(target))
    .map((target) => ({
      target: { basetime: target.basetime as string, validtime: target.validtime as string },
      offset: jmaOffsetMinutes(target)
    }))
    .filter((item): item is { target: JmaNowcastSelectedTarget; offset: number } => item.offset !== null);
  candidates.sort((a, b) => {
    const delta = Math.abs(a.offset - offsetMinutes) - Math.abs(b.offset - offsetMinutes);
    return delta !== 0 ? delta : b.target.validtime.localeCompare(a.target.validtime);
  });
  return candidates[0]?.target ?? null;
}

function chooseJmaShortRangeTarget(targets: JmaNowcastTarget[], offsetMinutes: number): JmaNowcastSelectedTarget | null {
  const candidates = targets
    .filter((target) => isValidJmaTimestamp(target.basetime) && isValidJmaTimestamp(target.validtime) && jmaTargetSupportsShortRangeRain(target))
    .map((target): { target: JmaNowcastSelectedTarget; offset: number | null } => ({
      target: {
        basetime: target.basetime as string,
        validtime: target.validtime as string,
        member: typeof target.member === "string" ? target.member : undefined
      },
      offset: jmaOffsetMinutes(target)
    }))
    .filter((item): item is { target: JmaNowcastSelectedTarget; offset: number } => item.offset !== null);
  candidates.sort((a, b) => {
    const delta = Math.abs(a.offset - offsetMinutes) - Math.abs(b.offset - offsetMinutes);
    if (delta !== 0) return delta;
    const memberRank = (value: string | undefined) => value === "immed" ? 0 : 1;
    const memberDelta = memberRank(a.target.member) - memberRank(b.target.member);
    return memberDelta !== 0 ? memberDelta : b.target.validtime.localeCompare(a.target.validtime);
  });
  return candidates[0]?.target ?? null;
}

async function fetchJmaTargets(url: string): Promise<JmaNowcastTarget[]> {
  const response = await fetch(url, { headers: { accept: "application/json" } });
  if (!response.ok) throw new Error(`jma_nowcast_fetch_failed:${response.status}`);
  const payload = await response.json();
  return Array.isArray(payload) ? payload as JmaNowcastTarget[] : [];
}

async function getJmaNowcastTimesResponse(): Promise<Response> {
  try {
    const [currentTargets, forecastTargets, shortRangeTargets] = await Promise.all([
      fetchJmaTargets(JMA_NOWCAST_TARGET_N1),
      fetchJmaTargets(JMA_NOWCAST_TARGET_N2),
      fetchJmaTargets(JMA_SHORT_RANGE_TARGET)
    ]);
    const times = [];
    for (const offsetMinutes of JMA_NOWCAST_OFFSETS) {
      const source = offsetMinutes === 0 ? currentTargets : forecastTargets;
      const target = chooseJmaNowcastTarget(source, offsetMinutes);
      if (!target) continue;
      times.push({
        offsetMinutes,
        basetime: target.basetime,
        validtime: target.validtime,
        product: "nowcast",
        member: "none",
        highResolution: offsetMinutes <= 30
      });
    }
    for (const offsetMinutes of JMA_SHORT_RANGE_OFFSETS) {
      const target = chooseJmaShortRangeTarget(shortRangeTargets, offsetMinutes);
      if (!target) continue;
      times.push({
        offsetMinutes,
        basetime: target.basetime,
        validtime: target.validtime,
        product: "short_range",
        member: target.member || "none",
        highResolution: false
      });
    }
    return json({
      source: "jma_precipitation_map",
      attribution: "Source: JMA High-resolution Precipitation Nowcast / Very Short-range Forecasts of Precipitation",
      attributionUrl: "https://www.jma.go.jp/jma/en/Activities/forecast.html",
      generatedAt: new Date().toISOString(),
      tileUrlTemplate: "/api/v1/weather/jma-nowcast/tile?product={product}&member={member}&basetime={basetime}&validtime={validtime}&z={z}&x={x}&y={y}",
      times
    }, 200, { "cache-control": "public, max-age=60" });
  } catch {
    return json({ error: "jma_nowcast_unavailable" }, 502, { "cache-control": "no-store" });
  }
}

function parseJmaTileNumber(raw: string | null, max: number): number | null {
  if (raw === null) return null;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 0 || value > max) return null;
  return value;
}

async function getJmaNowcastTileResponse(url: URL): Promise<Response> {
  const rawProduct = url.searchParams.get("product");
  const product = rawProduct === "short_range" ? "short_range" : "nowcast";
  const rawMember = url.searchParams.get("member");
  const member = rawMember === null || rawMember === ""
    ? "none"
    : /^[a-z0-9_-]{1,24}$/i.test(rawMember) ? rawMember : null;
  const basetime = url.searchParams.get("basetime");
  const validtime = url.searchParams.get("validtime");
  const z = parseJmaTileNumber(url.searchParams.get("z"), JMA_RAIN_TILE_MAX_ZOOM);
  const maxTile = z === null ? 0 : (2 ** z) - 1;
  const x = parseJmaTileNumber(url.searchParams.get("x"), maxTile);
  const y = parseJmaTileNumber(url.searchParams.get("y"), maxTile);
  if (member === null || !isValidJmaTimestamp(basetime) || !isValidJmaTimestamp(validtime) || z === null || x === null || y === null) {
    return json({ error: "invalid_jma_nowcast_tile" }, 400, { "cache-control": "no-store" });
  }

  const jmaUrl = product === "short_range"
    ? `${JMA_SHORT_RANGE_ROOT}/${basetime}/${member}/${validtime}/surf/rasrf/${z}/${x}/${y}.png`
    : `${JMA_NOWCAST_ROOT}/${basetime}/none/${validtime}/surf/hrpns/${z}/${x}/${y}.png`;
  const cache = (globalThis as typeof globalThis & { caches?: { default?: { match(request: Request): Promise<Response | undefined>; put(request: Request, response: Response): Promise<void> } } }).caches?.default;
  const cacheRequest = new Request(jmaUrl, { method: "GET" });
  const cached = await cache?.match(cacheRequest);
  if (cached) {
    const headers = new Headers(cached.headers);
    headers.set("cache-control", "public, max-age=300");
    headers.set("x-ikimon-weather-cache", "hit");
    headers.set("x-content-type-options", "nosniff");
    return new Response(cached.body, { status: cached.status, headers });
  }

  const upstream = await fetch(jmaUrl, { headers: { accept: "image/png" } });
  if (!upstream.ok) {
    return json({ error: "jma_nowcast_tile_unavailable" }, upstream.status === 404 ? 404 : 502, { "cache-control": "no-store" });
  }
  const bytes = await upstream.arrayBuffer();
  const response = new Response(bytes, {
    status: 200,
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=300",
      "x-ikimon-weather-cache": "miss",
      "x-content-type-options": "nosniff"
    }
  });
  await cache?.put(cacheRequest, response.clone());
  return response;
}

interface PublicMapAreaPolygonOptions {
  allowApproximateFallback?: boolean;
}

const LIVE_SCHOOL_OSM_TIMEOUT_MS = 2_500;
const LIVE_SCHOOL_OSM_MAX_SPAN_DEGREES = 0.18;
const LIVE_SCHOOL_OSM_MIN_ZOOM = 13;
const LIVE_SCHOOL_OSM_MIN_RESPONSE_LIMIT = 220;
const LIVE_SCHOOL_OSM_MAX_ENDPOINT_ATTEMPTS = 1;
const LIVE_SCHOOL_OSM_ENDPOINTS = [
  "https://overpass-api.de/api/interpreter",
  "https://z.overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter"
];

type OverpassAreaElement = {
  type: "way" | "relation" | "node";
  id: number;
  tags?: Record<string, string>;
  geometry?: Array<{ lat: number; lon: number }>;
  members?: Array<{ type: string; ref: number; role: string; geometry?: Array<{ lat: number; lon: number }> }>;
  center?: { lat?: number; lon?: number };
  bounds?: { minlat: number; minlon: number; maxlat: number; maxlon: number };
};

async function getPublicMapAreaPolygons(url: URL, env: Env, options: PublicMapAreaPolygonOptions = {}): Promise<Response | null> {
  const bbox = parseBboxParam(url.searchParams.get("bbox"));
  if (!bbox) {
    return json({ error: "missing_or_invalid_bbox" }, 400, { "cache-control": "no-store" });
  }
  const sources = parseSourceParam(url.searchParams.get("sources"));
  const rawZoom = url.searchParams.get("zoom");
  const zoom = rawZoom == null || rawZoom.trim() === "" ? null : Number(rawZoom);
  const defaultLimit = mapAreaPolygonsFallbackLimit(zoom);
  const requestedLimit = clampInteger(Number(url.searchParams.get("limit") ?? String(defaultLimit)), 1, 1000);
  const limit = mapAreaPolygonsResponseLimit(bbox, sources, zoom, requestedLimit);
  const nativeRows = await queryNativeAreaPolygonRows(env, bbox, sources, limit);
  const liveNamedFeatures = await fetchLiveNamedAreaPolygonsWhenRequested(
    env,
    bbox,
    sources,
    zoom,
    limit
  );
  if (nativeRows.length > 0) {
    const nativeFeatures = nativeRows
      .map((row) => areaPolygonFeatureFromGeometryReadmodel(row))
      .filter((feature): feature is NonNullable<typeof feature> => Boolean(feature))
      .filter(isDisplayableAreaPolygonFeature);
    const liveSchoolFeatures = await fetchLiveSchoolAreaPolygonsWhenNativeSchoolIsOnlyApproximate(
      env,
      bbox,
      sources,
      zoom,
      nativeRows,
      nativeFeatures,
      limit
    );
    const features = dedupePublicAreaPolygonFeatures(
      [...nativeFeatures, ...liveSchoolFeatures, ...liveNamedFeatures],
      limit
    );
    if (
      options.allowApproximateFallback === false
      && sources.includes("school")
      && !features.some((feature) => feature.properties?.source === "school")
    ) {
      return null;
    }
    return json({
      type: "FeatureCollection",
      features,
      truncated: nativeRows.length >= limit || features.length >= limit,
      stats: {
        totalReturned: features.length,
        totalAll: features.length,
        source: [
          "cloudflare_area_polygon_readmodel",
          liveSchoolFeatures.length > 0 ? "live_osm_school" : "",
          liveNamedFeatures.length > 0 ? "live_osm_named_area" : "",
        ].filter(Boolean).join("+"),
        kind: "area-polygons"
      }
    }, 200, { "cache-control": "public, max-age=60" });
  }
  if (liveNamedFeatures.length > 0) {
    return json({
      type: "FeatureCollection",
      features: liveNamedFeatures,
      truncated: liveNamedFeatures.length >= limit,
      stats: {
        totalReturned: liveNamedFeatures.length,
        totalAll: liveNamedFeatures.length,
        source: "live_osm_named_area",
        kind: "area-polygons"
      }
    }, 200, { "cache-control": "public, max-age=60" });
  }
  if (options.allowApproximateFallback === false) return null;

  const rows = await queryAreaPolygonRows(env, bbox, sources, limit);
  const fallbackFeatures = rows
    .map((row) => areaPolygonFeatureFromReadmodel(row))
    .filter((feature): feature is NonNullable<typeof feature> => Boolean(feature))
    .filter(isDisplayableAreaPolygonFeature);
  const features = dedupePublicAreaPolygonFeatures(
    [...fallbackFeatures, ...liveNamedFeatures],
    limit
  );

  return json({
    type: "FeatureCollection",
    features,
    truncated: rows.length >= limit,
    stats: {
      totalReturned: features.length,
      totalAll: features.length,
      source: "cloudflare_field_detail_readmodel",
      kind: "area-polygons"
    }
  }, 200, { "cache-control": "public, max-age=60" });
}

function isSchoolAreaSourceRequested(sources: string[]): boolean {
  return sources.length === 0 || sources.includes("school");
}

function isHumanScaleSchoolAreaBbox(bbox: [number, number, number, number]): boolean {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  if (maxLng <= minLng || maxLat <= minLat) return false;
  return (maxLng - minLng) <= LIVE_SCHOOL_OSM_MAX_SPAN_DEGREES
    && (maxLat - minLat) <= LIVE_SCHOOL_OSM_MAX_SPAN_DEGREES;
}

function isHumanScaleSchoolAreaRequest(
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null
): boolean {
  if (!isSchoolAreaSourceRequested(sources)) return false;
  if (!isHumanScaleSchoolAreaBbox(bbox)) return false;
  if (zoom == null) return true;
  return Number.isFinite(zoom) && zoom >= LIVE_SCHOOL_OSM_MIN_ZOOM;
}

function mapAreaPolygonsResponseLimit(
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null,
  requestedLimit: number
): number {
  if (!isHumanScaleSchoolAreaRequest(bbox, sources, zoom)) return requestedLimit;
  return Math.max(requestedLimit, LIVE_SCHOOL_OSM_MIN_RESPONSE_LIMIT);
}

function shouldFetchLiveSchoolAreaPolygons(
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null,
  nativeRows: AreaPolygonGeometryReadmodelRow[],
  _displayableFeatures: unknown[]
): boolean {
  if (!isHumanScaleSchoolAreaRequest(bbox, sources, zoom)) return false;
  if (!nativeRows.some((row) => row.source === "school")) return false;
  return nativeRows.some((row) => row.source === "school" && (
    row.approximate_boundary === 1 ||
    row.boundary_approximation === "point_buffer"
  ));
}

async function fetchLiveSchoolAreaPolygonsWhenNativeSchoolIsOnlyApproximate(
  env: Env,
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null,
  nativeRows: AreaPolygonGeometryReadmodelRow[],
  displayableFeatures: unknown[],
  remainingLimit: number
): Promise<LiveSchoolAreaPolygonFeature[]> {
  if (remainingLimit <= 0) return [];
  if (!shouldFetchLiveSchoolAreaPolygons(bbox, sources, zoom, nativeRows, displayableFeatures)) return [];
  const live = await fetchLiveSchoolAreaPolygons(env, bbox, remainingLimit);
  if (!live.ok && live.error) {
    console.warn("[area-polygons] live school OSM fallback failed", live.error);
  }
  return live.features;
}

function buildLiveSchoolOsmAreaQuery(bbox: [number, number, number, number]): string {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  const bb = `${minLat},${minLng},${maxLat},${maxLng}`;
  return `
[out:json][timeout:8];
(
  way["amenity"~"^(school|college|university|kindergarten|childcare)$"](${bb});
  relation["amenity"~"^(school|college|university|kindergarten|childcare)$"](${bb});
  way["landuse"~"^(education|school|college|university|kindergarten)$"](${bb});
  relation["landuse"~"^(education|school|college|university|kindergarten)$"](${bb});
  way["building"~"^(school|college|university|kindergarten)$"](${bb});
  relation["building"~"^(school|college|university|kindergarten)$"](${bb});
);
out tags geom;
`;
}

function liveOsmRingFromGeometry(geometry: Array<{ lat: number; lon: number }> | undefined): number[][] | null {
  if (!Array.isArray(geometry) || geometry.length < 3) return null;
  const ring = geometry
    .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lon))
    .map((point) => [point.lon, point.lat]);
  if (ring.length < 3) return null;
  const first = ring[0];
  const last = ring[ring.length - 1];
  if (!first || !last) return null;
  const firstLng = first[0] ?? NaN;
  const firstLat = first[1] ?? NaN;
  const lastLng = last[0] ?? NaN;
  const lastLat = last[1] ?? NaN;
  if (
    !Number.isFinite(firstLng) ||
    !Number.isFinite(firstLat) ||
    !Number.isFinite(lastLng) ||
    !Number.isFinite(lastLat)
  ) return null;
  if (firstLng !== lastLng || firstLat !== lastLat) ring.push([firstLng, firstLat]);
  return ring;
}

function liveSchoolElementToPolygon(element: OverpassAreaElement): { type: "Polygon" | "MultiPolygon"; coordinates: unknown[] } | null {
  if (element.type === "way") {
    const ring = liveOsmRingFromGeometry(element.geometry);
    return ring ? { type: "Polygon", coordinates: [ring] } : null;
  }
  if (element.type === "relation" && Array.isArray(element.members)) {
    const polygons = element.members
      .filter((member) => member.type === "way" && member.role !== "inner")
      .map((member) => liveOsmRingFromGeometry(member.geometry))
      .filter((ring): ring is number[][] => Boolean(ring))
      .map((ring) => [ring]);
    for (const member of element.members) {
      if (member.type !== "way" || member.role !== "inner") continue;
      const ring = liveOsmRingFromGeometry(member.geometry);
      const first = ring?.[0];
      if (!ring || !first) continue;
      const owner = polygons.find((polygon) =>
        pointInPlaceGeometry(
          { lng: Number(first[0]), lat: Number(first[1]) },
          { type: "Polygon", coordinates: polygon }
        )
      );
      if (owner) owner.push(ring);
    }
    if (polygons.length === 0) return null;
    if (polygons.length === 1) return { type: "Polygon", coordinates: polygons[0] ?? [] };
    return { type: "MultiPolygon", coordinates: polygons };
  }
  return null;
}

function liveSchoolElementHasName(element: OverpassAreaElement): boolean {
  const tags = element.tags ?? {};
  return Boolean((tags["name:ja"] ?? tags.name ?? tags.alt_name ?? "").trim());
}

function liveSchoolElementDisplayName(element: OverpassAreaElement): string {
  const tags = element.tags ?? {};
  return tags["name:ja"] ?? tags.name ?? tags.alt_name ?? "OSMの学校・キャンパス";
}

function liveSchoolElementIsSchool(element: OverpassAreaElement): boolean {
  const tags = element.tags ?? {};
  const amenity = tags.amenity ?? "";
  const landuse = tags.landuse ?? "";
  const building = tags.building ?? "";
  const namedEducationBuilding = liveSchoolElementHasName(element)
    && ["school", "college", "university", "kindergarten"].includes(building);
  return ["school", "college", "university", "kindergarten", "childcare"].includes(amenity)
    || ["education", "school", "college", "university", "kindergarten"].includes(landuse)
    || namedEducationBuilding;
}

function liveSchoolElementCenter(element: OverpassAreaElement, geometry: { coordinates: unknown[] }): [number, number] | null {
  if (Number.isFinite(element.center?.lat) && Number.isFinite(element.center?.lon)) {
    return [Number(element.center!.lon), Number(element.center!.lat)];
  }
  if (element.bounds) {
    return [
      (element.bounds.minlon + element.bounds.maxlon) / 2,
      (element.bounds.minlat + element.bounds.maxlat) / 2
    ];
  }
  const ring = Array.isArray(geometry.coordinates[0]) ? geometry.coordinates[0] : null;
  if (!Array.isArray(ring) || ring.length === 0) return null;
  let lng = 0;
  let lat = 0;
  let count = 0;
  for (const point of ring) {
    if (!Array.isArray(point) || point.length < 2) continue;
    const pointLng = Number(point[0]);
    const pointLat = Number(point[1]);
    if (!Number.isFinite(pointLng) || !Number.isFinite(pointLat)) continue;
    lng += pointLng;
    lat += pointLat;
    count += 1;
  }
  return count > 0 ? [lng / count, lat / count] : null;
}

function liveSchoolElementToFeature(element: OverpassAreaElement) {
  if (element.type !== "way" && element.type !== "relation") return null;
  if (!liveSchoolElementIsSchool(element)) return null;
  const geometry = liveSchoolElementToPolygon(element);
  if (!geometry) return null;
  const center = liveSchoolElementCenter(element, geometry);
  if (!center) return null;
  const tags = element.tags ?? {};
  const website = tags.website ?? tags["contact:website"] ?? "";
  const hasName = liveSchoolElementHasName(element);
  return {
    type: "Feature",
    geometry,
    properties: {
      field_id: `osm-live:${element.type}:${element.id}`,
      name: liveSchoolElementDisplayName(element),
      source: "school",
      source_label: "学校・キャンパス (OSM live)",
      admin_level: "school",
      prefecture: "",
      city: "",
      area_ha: null,
      official_url: website,
      owner_url: website,
      story_url: "",
      certification_url: "",
      source_confidence: website ? 0.75 : 0.45,
      verification_level: "unverified",
      verification_label: website ? "公式ページ候補あり" : "未確認",
      center,
      access: tags.access ?? "",
      transient: true,
      entity_key: `osm:${element.type}:${element.id}`,
      osm_type: element.type,
      osm_id: element.id,
      osm_named: hasName,
      biodiversity_groups: []
    }
  };
}

type LiveSchoolAreaPolygonFeature = NonNullable<ReturnType<typeof liveSchoolElementToFeature>>;

const LIVE_NAMED_AREA_CACHE_TTL_MS = 15 * 60 * 1_000;
const LIVE_NAMED_AREA_NEGATIVE_CACHE_TTL_MS = 2 * 60 * 1_000;
const liveNamedAreaCache = new Map<string, {
  expiresAt: number;
  features: LiveNamedAreaPolygonFeature[];
}>();

function isGenericNamedAreaRequest(
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null
): boolean {
  return sources.includes("osm_named_area")
    && isHumanScaleSchoolAreaBbox(bbox)
    && zoom !== null
    && Number.isFinite(zoom)
    && zoom >= LIVE_SCHOOL_OSM_MIN_ZOOM;
}

function buildLiveNamedOsmAreaQuery(bbox: [number, number, number, number]): string {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  const bb = `${minLat},${minLng},${maxLat},${maxLng}`;
  return `
[out:json][timeout:8];
(
  way["tourism"~"^(theme_park|museum|zoo|aquarium|attraction|resort)$"]["name"](${bb});
  relation["tourism"~"^(theme_park|museum|zoo|aquarium|attraction|resort)$"]["name"](${bb});
  way["shop"~"^(mall|shopping_centre|shopping_center)$"]["name"](${bb});
  relation["shop"~"^(mall|shopping_centre|shopping_center)$"]["name"](${bb});
  way["landuse"~"^(retail|commercial)$"]["name"](${bb});
  relation["landuse"~"^(retail|commercial)$"]["name"](${bb});
  way["leisure"~"^(water_park|stadium|sports_centre|sports_center|sports_hall)$"]["name"](${bb});
  relation["leisure"~"^(water_park|stadium|sports_centre|sports_center|sports_hall)$"]["name"](${bb});
  way["amenity"~"^(marketplace|community_centre|community_center|arts_centre|arts_center|place_of_worship|events_venue|conference_centre|conference_center|townhall|library|theatre)$"]["name"](${bb});
  relation["amenity"~"^(marketplace|community_centre|community_center|arts_centre|arts_center|place_of_worship|events_venue|conference_centre|conference_center|townhall|library|theatre)$"]["name"](${bb});
  way["landuse"~"^(farmland|farmyard|orchard|vineyard)$"]["name"](${bb});
  relation["landuse"~"^(farmland|farmyard|orchard|vineyard)$"]["name"](${bb});
);
out tags geom;
`;
}

function liveNamedElementToFeature(element: OverpassAreaElement, zoom: number) {
  if (element.type !== "way" && element.type !== "relation") return null;
  const tags = element.tags ?? {};
  const placeKind = classifyOsmPlaceKind(tags);
  if (!placeKind) return null;
  const geometry = liveSchoolElementToPolygon(element);
  if (!geometry) return null;
  const universalGeometry = geometry as UniversalPlaceGeometry;
  const bbox = bboxForPlaceGeometry(universalGeometry);
  const areaHa = bboxAreaHa(bbox);
  if (!isDiscoverableNamedArea({
    osmType: element.type,
    tags,
    geometry: universalGeometry,
    areaHa,
    zoom,
    context: "viewport",
  })) return null;
  const center = liveSchoolElementCenter(element, geometry);
  if (!center) return null;
  const names = collectOsmPlaceNames(tags);
  if (!names.canonicalName) return null;
  const website = tags.website ?? tags["contact:website"] ?? "";
  const policy = defaultPlacePolicy({
    placeKind,
    osmAccess: tags.access,
  });
  const entityKey = `osm:${element.type}:${element.id}`;
  const canonicalPlaceId = initialCanonicalPlaceId({
    canonicalName: names.canonicalName,
    localityLabel: "",
    placeKind,
  });
  return {
    type: "Feature",
    geometry,
    properties: {
      field_id: `osm-live:${element.type}:${element.id}`,
      name: names.canonicalName,
      source: "osm_named_area",
      source_label: "場所・施設 (OSM live)",
      admin_level: placeKind,
      place_kind: placeKind,
      canonical_place_id: canonicalPlaceId,
      aliases: names.aliases,
      multilingual_names: names.multilingualNames,
      prefecture: "",
      city: "",
      area_ha: areaHa,
      official_url: website,
      owner_url: website,
      story_url: "",
      certification_url: "",
      source_confidence: website ? 0.75 : 0.55,
      verification_level: "unverified",
      verification_label: website ? "公式ページ候補あり" : "OSM出典・未確認",
      center,
      access: tags.access ?? "",
      transient: true,
      entity_key: entityKey,
      osm_type: element.type,
      osm_id: element.id,
      osm_named: true,
      recording_policy: policy.recordingPolicy,
      contribution_cta_mode: policy.contributionCtaMode,
      policy_reason: policy.reason,
      source_references: [{
        source_type: `osm_${element.type}`,
        source_id: String(element.id),
        confidence: website ? 0.75 : 0.55,
        verification_status: "unverified",
      }],
      biodiversity_groups: []
    }
  };
}

type LiveNamedAreaPolygonFeature = NonNullable<ReturnType<typeof liveNamedElementToFeature>>;

function liveNamedAreaCacheKey(
  bbox: [number, number, number, number],
  zoom: number
): string {
  return `${bbox.map((value) => value.toFixed(4)).join(",")}|z${Math.floor(zoom)}`;
}

async function fetchLiveNamedAreaPolygonsWhenRequested(
  env: Env,
  bbox: [number, number, number, number],
  sources: string[],
  zoom: number | null,
  limit: number
): Promise<LiveNamedAreaPolygonFeature[]> {
  if (limit <= 0 || !isGenericNamedAreaRequest(bbox, sources, zoom)) return [];
  const startedAt = Date.now();
  const logResolve = (status: string, cache: string, count: number, error?: string) => {
    console.info("[place-atlas-osm]", JSON.stringify({
      event: "named_area_resolve",
      status,
      cache,
      count,
      latencyMs: Math.max(0, Date.now() - startedAt),
      error: error ?? null,
    }));
  };
  const cacheKey = liveNamedAreaCacheKey(bbox, zoom as number);
  const cached = liveNamedAreaCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) {
    const features = cached.features.slice(0, limit);
    logResolve(features.length > 0 ? "success" : "empty", "hit", features.length);
    return features;
  }
  const endpoints = Array.from(new Set([
    ...(env.OVERPASS_API_URL?.trim() ? [env.OVERPASS_API_URL.trim()] : []),
    ...LIVE_SCHOOL_OSM_ENDPOINTS
  ])).slice(0, LIVE_SCHOOL_OSM_MAX_ENDPOINT_ATTEMPTS);
  const body = `data=${encodeURIComponent(buildLiveNamedOsmAreaQuery(bbox))}`;
  for (const endpoint of endpoints) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), LIVE_SCHOOL_OSM_TIMEOUT_MS);
    try {
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "Accept": "application/json",
          "User-Agent": "ZUKAN universal place atlas contact: https://zukan.earth",
          "X-Ikimon-Client": "ikimon.life-named-area-polygons"
        },
        body,
        signal: controller.signal
      });
      if (!response.ok) continue;
      const payload = await response.json() as { elements?: OverpassAreaElement[] };
      const features = dedupePublicAreaPolygonFeatures(
        (payload.elements ?? [])
          .map((element) => liveNamedElementToFeature(element, zoom as number))
          .filter((feature): feature is LiveNamedAreaPolygonFeature => Boolean(feature)),
        limit,
        bbox
      );
      liveNamedAreaCache.set(cacheKey, {
        features,
        expiresAt: Date.now() + (features.length > 0
          ? LIVE_NAMED_AREA_CACHE_TTL_MS
          : LIVE_NAMED_AREA_NEGATIVE_CACHE_TTL_MS),
      });
      logResolve(features.length > 0 ? "success" : "empty", "miss", features.length);
      return features;
    } catch (error) {
      console.warn("[area-polygons] live named area OSM fallback failed", error);
    } finally {
      clearTimeout(timeout);
    }
  }
  liveNamedAreaCache.set(cacheKey, {
    features: [],
    expiresAt: Date.now() + LIVE_NAMED_AREA_NEGATIVE_CACHE_TTL_MS,
  });
  logResolve("error", "miss", 0, "overpass_unavailable");
  return [];
}

function walkPublicAreaPolygonGeometry(value: unknown, visit: (lng: number, lat: number) => void): void {
  if (!Array.isArray(value)) return;
  if (value.length >= 2 && typeof value[0] === "number" && typeof value[1] === "number") {
    visit(value[0], value[1]);
    return;
  }
  for (const item of value) walkPublicAreaPolygonGeometry(item, visit);
}

function publicAreaPolygonFeatureTouchesBbox(feature: unknown, bbox: [number, number, number, number]): boolean {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  const props = areaPolygonFeatureProps(feature);
  const center = props?.center;
  if (Array.isArray(center) && center.length >= 2) {
    const lng = Number(center[0]);
    const lat = Number(center[1]);
    if (lng >= minLng && lng <= maxLng && lat >= minLat && lat <= maxLat) return true;
  }
  if (!feature || typeof feature !== "object" || Array.isArray(feature)) return false;
  const geometry = (feature as { geometry?: { coordinates?: unknown } }).geometry;
  let fMinLng = Infinity;
  let fMinLat = Infinity;
  let fMaxLng = -Infinity;
  let fMaxLat = -Infinity;
  walkPublicAreaPolygonGeometry(geometry?.coordinates, (lng, lat) => {
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return;
    fMinLng = Math.min(fMinLng, lng);
    fMinLat = Math.min(fMinLat, lat);
    fMaxLng = Math.max(fMaxLng, lng);
    fMaxLat = Math.max(fMaxLat, lat);
  });
  if (!Number.isFinite(fMinLng)) return false;
  return fMaxLat >= minLat && fMinLat <= maxLat && fMaxLng >= minLng && fMinLng <= maxLng;
}

function osmEntityKeyFromAreaPolygonProps(props: Record<string, unknown>): string {
  const explicit = textProp(props, "entity_key");
  if (/^osm:(way|relation):[0-9]+$/.test(explicit)) return explicit;
  const fieldId = textProp(props, "field_id");
  const liveIdMatch = fieldId.match(/^osm-live:(way|relation):([0-9]+)$/);
  if (liveIdMatch?.[1] && liveIdMatch[2]) return `osm:${liveIdMatch[1]}:${liveIdMatch[2]}`;
  const osmType = textProp(props, "osm_type");
  const osmId = String(props.osm_id ?? "").trim();
  if (/^(way|relation)$/.test(osmType) && /^[0-9]+$/.test(osmId)) return `osm:${osmType}:${osmId}`;
  const label = [
    textProp(props, "verification_label"),
    textProp(props, "official_url"),
    textProp(props, "owner_url"),
    textProp(props, "certification_url"),
    textProp(props, "story_url")
  ].join(" ");
  const urlMatch = label.match(/openstreetmap\.org\/(way|relation)\/([0-9]+)/);
  return urlMatch?.[1] && urlMatch[2] ? `osm:${urlMatch[1]}:${urlMatch[2]}` : "";
}

function dedupePublicAreaPolygonFeatures<T>(features: T[], limit: number, bbox?: [number, number, number, number]): T[] {
  const seen = new Set<string>();
  const unique: T[] = [];
  for (const feature of features) {
    if (bbox && !publicAreaPolygonFeatureTouchesBbox(feature, bbox)) continue;
    const props = areaPolygonFeatureProps(feature);
    const osmKey = props ? osmEntityKeyFromAreaPolygonProps(props) : "";
    if (osmKey && seen.has(osmKey)) continue;
    const key = textProp(props ?? {}, "entity_key") || textProp(props ?? {}, "field_id");
    if (!key || seen.has(key)) continue;
    seen.add(key);
    if (osmKey) seen.add(osmKey);
    unique.push(feature);
  }
  const byCandidateId = new Map<string, T>();
  const candidates = unique.flatMap((feature) => {
    const props = areaPolygonFeatureProps(feature);
    if (!props || !feature || typeof feature !== "object" || Array.isArray(feature)) return [];
    const geometry = (feature as { geometry?: UniversalPlaceGeometry }).geometry;
    if (!geometry || (geometry.type !== "Polygon" && geometry.type !== "MultiPolygon")) return [];
    const placeKind = String(props.place_kind ?? props.admin_level ?? "");
    const tags = { name: textProp(props, "name") };
    const classified = classifyOsmPlaceKind(tags);
    const supportedKind = [
      "park", "school", "nature_area", "theme_park", "shopping_mall",
      "commercial_complex", "museum", "zoo", "aquarium", "stadium",
      "sports_facility", "resort", "market", "farm", "temple_shrine",
      "cultural_facility", "public_facility", "event_venue", "neighborhood",
      "administrative_area", "other_named_area",
    ].includes(placeKind)
      ? placeKind
      : classified;
    if (!supportedKind) return [];
    const candidateId = textProp(props, "entity_key") || textProp(props, "field_id");
    if (!candidateId) return [];
    byCandidateId.set(candidateId, feature);
    return [{
      candidateId,
      canonicalName: textProp(props, "name"),
      aliases: Array.isArray(props.aliases)
        ? props.aliases.filter((value): value is string => typeof value === "string")
        : [],
      placeKind: supportedKind as Parameters<typeof initialCanonicalPlaceId>[0]["placeKind"],
      geometry,
      bbox: bboxForPlaceGeometry(geometry),
      areaHa: Number.isFinite(Number(props.area_ha)) ? Number(props.area_ha) : null,
      sourceType: candidateId.startsWith("osm:")
        ? `osm_${textProp(props, "osm_type") || "area"}`
        : "observation_field",
      sourceId: candidateId,
      sourceConfidence: Number.isFinite(Number(props.source_confidence))
        ? Number(props.source_confidence)
        : 0.45,
      verificationStatus: textProp(props, "verification_level") || "unverified",
      localityLabel: [textProp(props, "prefecture"), textProp(props, "city")].filter(Boolean).join(" "),
    }];
  });
  if (candidates.length < 2) return unique.slice(0, limit);
  const represented = new Set(candidates.map((candidate) => candidate.candidateId));
  const merged = dedupePlaceCandidates(candidates).flatMap((candidate) => {
    const feature = byCandidateId.get(candidate.candidateId);
    if (!feature || typeof feature !== "object" || Array.isArray(feature)) return [];
    const current = feature as { properties?: Record<string, unknown> };
    return [{
      ...current,
      properties: {
        ...(current.properties ?? {}),
        name: candidate.canonicalName,
        aliases: candidate.aliases,
        place_kind: candidate.placeKind,
        canonical_place_id: textProp(current.properties ?? {}, "canonical_place_id") ||
          initialCanonicalPlaceId({
            canonicalName: candidate.canonicalName,
            localityLabel: candidate.localityLabel ?? "",
            placeKind: candidate.placeKind,
          }),
        merged_candidate_ids: candidate.mergedCandidateIds,
        source_references: candidate.sourceReferences.map((source) => ({
          source_type: source.sourceType,
          source_id: source.sourceId,
          confidence: source.confidence,
          verification_status: source.verificationStatus,
        })),
      },
    } as T];
  });
  const untouched = unique.filter((feature) => {
    const props = areaPolygonFeatureProps(feature);
    const candidateId = props
      ? textProp(props, "entity_key") || textProp(props, "field_id")
      : "";
    return !represented.has(candidateId);
  });
  return [...merged, ...untouched].slice(0, limit);
}

async function fetchLiveSchoolAreaPolygons(
  env: Env,
  bbox: [number, number, number, number],
  limit: number
): Promise<{ ok: boolean; features: LiveSchoolAreaPolygonFeature[]; error?: string }> {
  const endpoints = Array.from(new Set([
    ...(env.OVERPASS_API_URL?.trim() ? [env.OVERPASS_API_URL.trim()] : []),
    ...LIVE_SCHOOL_OSM_ENDPOINTS
  ])).slice(0, LIVE_SCHOOL_OSM_MAX_ENDPOINT_ATTEMPTS);
  const body = `data=${encodeURIComponent(buildLiveSchoolOsmAreaQuery(bbox))}`;
  let lastError = "overpass_failed";
  for (const endpoint of endpoints) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), LIVE_SCHOOL_OSM_TIMEOUT_MS);
    try {
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "Accept": "application/json",
          "User-Agent": "ZUKAN area polygon repair contact: https://zukan.earth",
          "X-Ikimon-Client": "ikimon.life-area-polygons"
        },
        body,
        signal: controller.signal
      });
      if (!response.ok) {
        lastError = `overpass_${response.status}`;
        continue;
      }
      const payload = await response.json() as { elements?: OverpassAreaElement[] };
      const features = (payload.elements ?? [])
        .map((element) => liveSchoolElementToFeature(element))
        .filter((feature): feature is NonNullable<typeof feature> => Boolean(feature))
        .filter(isDisplayableAreaPolygonFeature);
      return {
        ok: true,
        features: dedupePublicAreaPolygonFeatures(features, limit, bbox)
      };
    } catch (error) {
      lastError = error instanceof Error ? error.message : "overpass_failed";
    } finally {
      clearTimeout(timeout);
    }
  }
  return { ok: false, features: [], error: lastError };
}

function getPublicMapGuideSpots(url: URL): Response {
  const bbox = parseBboxParam(url.searchParams.get("bbox"));
  if (!bbox) {
    return json({ error: "missing_or_invalid_bbox" }, 400, { "cache-control": "no-store" });
  }
  const limit = clampInteger(Number(url.searchParams.get("limit") ?? "80"), 1, 120);
  const [minLng, minLat, maxLng, maxLat] = bbox;
  const scoped = SHADOW_MAP_GUIDE_SPOTS
    .filter((spot) => spot.lng >= minLng && spot.lng <= maxLng && spot.lat >= minLat && spot.lat <= maxLat)
    .slice(0, limit);
  return json({
    type: "FeatureCollection",
    features: scoped.map((spot) => {
      const { lat: _lat, lng: _lng, ...properties } = spot;
      return {
        type: "Feature",
        properties,
        geometry: {
          type: "Point",
          coordinates: [spot.lng, spot.lat]
        }
      };
    }),
    truncated: scoped.length >= limit,
    stats: {
      totalReturned: scoped.length,
      totalAll: scoped.length,
      source: "cloudflare_static_global_guide_spots",
      kind: "guide-spots",
      coverage: "global_bbox"
    }
  }, 200, { "cache-control": "public, max-age=300" });
}

