async function existingOwnerObservationDualWritePlan(
  recordId: string,
  ownerUserId: string,
  env: Env
): Promise<ObservationDualWritePlan | null> {
  if (!observationDualWriteEnabled(env)) return null;
  const record = await env.OBS_DB.prepare(
    `SELECT observed_at, taxon_label, visibility, organism_origin
       FROM observations WHERE observation_id = ? AND owner_user_id = ? LIMIT 1`
  ).bind(recordId, ownerUserId).first<{
    observed_at: string;
    taxon_label: string | null;
    visibility: string;
    organism_origin: string | null;
  }>();
  if (!record) return null;
  const captiveContext = record.organism_origin === "wild"
    ? "wild"
    : record.organism_origin === "planted"
      ? "cultivated"
      : record.organism_origin === "captive"
        ? "captive"
        : "unknown";
  return buildOwnerObservationUpsertPlan({
    recordId,
    ownerUserId,
    visibility: record.visibility === "public" ? "public" : "private",
    subjectType: record.taxon_label ? "organism" : "unknown_subject",
    captiveContext,
    sourceSnapshot: {
      observedAt: record.observed_at,
      taxonLabel: record.taxon_label,
      visibility: record.visibility,
      organismOrigin: record.organism_origin,
    },
  });
}

async function updateCompatibleOccurrenceDetail(
  occurrenceId: string,
  kind: CompatibleOccurrenceDetailEditKind,
  request: Request,
  env: Env
): Promise<Response> {
  if (!isAppRuntime(env)) {
    return json({ ok: false, error: "not_available" }, 404);
  }
  const session = await readCompatibleSession(request, env);
  if (!session) {
    return json({ ok: false, error: "session_required" }, 401);
  }
  try {
    await assertObservationOwnedByUser(occurrenceId, session.userId, env);
    const body = await readJson<Record<string, unknown>>(request);
    if (kind === "origin") return await updateCompatibleOccurrenceOrigin(occurrenceId, session, body, env);
    if (kind === "observed-at") return await updateCompatibleOccurrenceObservedAt(occurrenceId, session, body, env);
    if (kind === "location") return await updateCompatibleOccurrenceLocation(occurrenceId, session, body, env);
    if (kind === "environment-field") return await updateCompatibleOccurrenceEnvironmentField(occurrenceId, session, body, env);
    return await updateCompatibleOccurrenceEnvironmentRecord(occurrenceId, session, body, env);
  } catch (error) {
    const status = error instanceof HttpError ? error.status : 400;
    return json({ ok: false, error: error instanceof Error ? error.message : "occurrence_detail_update_failed" }, status);
  }
}

async function updateCompatibleOccurrenceOrigin(
  occurrenceId: string,
  session: SessionSnapshot,
  body: Record<string, unknown>,
  env: Env
): Promise<Response> {
  const organismOrigin = normalizeCompatibleOrganismOrigin(body.organismOrigin);
  const ownerPlan = await existingOwnerObservationDualWritePlan(occurrenceId, session.userId, env);
  const editPlan = observationDualWriteEnabled(env)
    ? await buildHumanObservationEditPlan({
      recordId: occurrenceId,
      actorUserId: session.userId,
      editKind: "origin",
      payload: { organismOrigin },
      captiveContext: organismOrigin === "wild" ? "wild"
        : organismOrigin === "planted" ? "cultivated"
          : organismOrigin === "captive" ? "captive" : "unknown",
    })
    : null;
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      "UPDATE observations SET organism_origin = ? WHERE observation_id = ?"
    ).bind(organismOrigin, occurrenceId),
    compatibleOccurrenceDetailEditEvent(env, occurrenceId, session.userId, "origin", { organismOrigin }),
    ...observationDualWriteStatements(env, ownerPlan),
    ...observationDualWriteStatements(env, editPlan),
  ]);
  return json({
    ok: true,
    occurrenceId,
    organismOrigin,
    label: compatibleOrganismOriginLabel(organismOrigin)
  }, 200, { "x-ikimon-cloudflare-native": "occurrence-detail-edit" });
}

async function updateCompatibleOccurrenceObservedAt(
  occurrenceId: string,
  session: SessionSnapshot,
  body: Record<string, unknown>,
  env: Env
): Promise<Response> {
  const observedAt = normalizeCompatibleObservedAt(body.observedAt);
  const partitionMonth = partitionMonthFromDate(observedAt);
  const ownerPlan = await existingOwnerObservationDualWritePlan(occurrenceId, session.userId, env);
  const editPlan = observationDualWriteEnabled(env)
    ? await buildHumanObservationEditPlan({
      recordId: occurrenceId,
      actorUserId: session.userId,
      editKind: "observed-at",
      payload: { observedAt },
    })
    : null;
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      "UPDATE observations SET observed_at = ?, partition_month = ? WHERE observation_id = ?"
    ).bind(observedAt, partitionMonth, occurrenceId),
    env.OBS_DB.prepare(
      "UPDATE readmodel_public_observations SET observed_at = ?, updated_at = CURRENT_TIMESTAMP WHERE observation_id = ?"
    ).bind(observedAt, occurrenceId),
    compatibleOccurrenceDetailEditEvent(env, occurrenceId, session.userId, "observed-at", { observedAt }),
    compatibleReadmodelRefreshOutbox(env, occurrenceId, partitionMonth),
    ...observationDualWriteStatements(env, ownerPlan),
    ...observationDualWriteStatements(env, editPlan),
  ]);
  return json({
    ok: true,
    occurrenceId,
    visitId: occurrenceId,
    observedAt
  }, 200, { "x-ikimon-cloudflare-native": "occurrence-detail-edit" });
}

async function updateCompatibleOccurrenceLocation(
  occurrenceId: string,
  session: SessionSnapshot,
  body: Record<string, unknown>,
  env: Env
): Promise<Response> {
  const latitude = normalizeCompatibleLatitude(body.latitude);
  const longitude = normalizeCompatibleLongitude(body.longitude);
  const publicCell = blurLocation(latitude, longitude);
  const ownerPlan = await existingOwnerObservationDualWritePlan(occurrenceId, session.userId, env);
  const editPlan = observationDualWriteEnabled(env)
    ? await buildHumanObservationEditPlan({
      recordId: occurrenceId,
      actorUserId: session.userId,
      editKind: "location",
      payload: { publicLocationChanged: true },
    })
    : null;
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      "UPDATE observations SET exact_lat = ?, exact_lng = ?, public_cell = ?, public_area_label = NULL WHERE observation_id = ?"
    ).bind(latitude, longitude, publicCell, occurrenceId),
    env.OBS_DB.prepare(
      "UPDATE readmodel_public_observations SET public_cell = ?, public_area_label = NULL, updated_at = CURRENT_TIMESTAMP WHERE observation_id = ?"
    ).bind(publicCell, occurrenceId),
    compatibleOccurrenceDetailEditEvent(env, occurrenceId, session.userId, "location", { latitude, longitude, publicCell }),
    compatibleReadmodelRefreshOutbox(env, occurrenceId, null),
    ...observationDualWriteStatements(env, ownerPlan),
    ...observationDualWriteStatements(env, editPlan),
  ]);
  return json({
    ok: true,
    occurrenceId,
    visitId: occurrenceId,
    latitude,
    longitude,
    label: `${latitude.toFixed(6)}, ${longitude.toFixed(6)}`
  }, 200, { "x-ikimon-cloudflare-native": "occurrence-detail-edit" });
}

async function updateCompatibleOccurrenceEnvironmentField(
  occurrenceId: string,
  session: SessionSnapshot,
  body: Record<string, unknown>,
  env: Env
): Promise<Response> {
  const field = normalizeCompatibleEnvironmentRecordField(body.field);
  const value = normalizeCompatibleEnvironmentRecordValue(field, body.value);
  const result = await insertCompatibleEnvironmentRecord(occurrenceId, session.userId, { [field]: value }, env);
  return json({
    ok: true,
    occurrenceId,
    field,
    value,
    label: compatibleEnvironmentRecordLabel(field, value),
    recordId: result.recordId
  }, 200, { "x-ikimon-cloudflare-native": "occurrence-detail-edit" });
}

async function updateCompatibleOccurrenceEnvironmentRecord(
  occurrenceId: string,
  session: SessionSnapshot,
  body: Record<string, unknown>,
  env: Env
): Promise<Response> {
  const rawValues = body.values && typeof body.values === "object" && !Array.isArray(body.values)
    ? body.values as Record<string, unknown>
    : {};
  const values: Partial<Record<CompatibleEnvironmentRecordField, string>> = {};
  for (const [rawField, rawValue] of Object.entries(rawValues)) {
    const field = normalizeCompatibleEnvironmentRecordField(rawField);
    values[field] = normalizeCompatibleEnvironmentRecordValue(field, rawValue);
  }
  if (Object.keys(values).length === 0) {
    throw new HttpError(400, "invalid_environment_record_value");
  }
  await insertCompatibleEnvironmentRecord(occurrenceId, session.userId, values, env);
  return json({
    ok: true,
    occurrenceId,
    values: Object.fromEntries(Object.entries(values).map(([field, value]) => [field, {
      value,
      label: compatibleEnvironmentRecordLabel(field as CompatibleEnvironmentRecordField, value),
      source: "user"
    }]))
  }, 200, { "x-ikimon-cloudflare-native": "occurrence-detail-edit" });
}

async function insertCompatibleEnvironmentRecord(
  occurrenceId: string,
  userId: string,
  values: Partial<Record<CompatibleEnvironmentRecordField, string>>,
  env: Env
): Promise<{ recordId: string }> {
  await requireCompatibleEnvironmentRecordStorage(env);
  const observation = await env.OBS_DB.prepare(
    "SELECT observation_id, exact_lat, exact_lng, public_cell FROM observations WHERE observation_id = ?"
  ).bind(occurrenceId).first<{ observation_id: string; exact_lat: number | null; exact_lng: number | null; public_cell: string }>();
  if (!observation) {
    throw new HttpError(404, "observation_not_found");
  }
  const exactLat = numberOrNull(observation.exact_lat);
  const exactLng = numberOrNull(observation.exact_lng);
  const publicCell = parsePublicCell(observation.public_cell);
  const lat = exactLat ?? publicCell?.lat ?? null;
  const lng = exactLng ?? publicCell?.lng ?? null;
  if (lat === null || lng === null) {
    throw new HttpError(400, "occurrence_location_required");
  }
  const previousRow = await env.OBS_DB.prepare(
    "SELECT structured_json FROM observation_environment_records WHERE occurrence_id = ? ORDER BY created_at DESC LIMIT 1"
  ).bind(occurrenceId).first<{ structured_json: string }>();
  const previous = parseCompatibleStructuredJson(previousRow?.structured_json);
  const structured = mergeCompatibleUserEnvironmentRecordValues(previous, values, userId);
  structured.environment_record_location_source = exactLat !== null && exactLng !== null ? "exact_observation" : "public_cell";
  const recordId = newId("envrec");
  const ownerPlan = await existingOwnerObservationDualWritePlan(occurrenceId, userId, env);
  const editPlan = observationDualWriteEnabled(env)
    ? await buildHumanObservationEditPlan({
      recordId: occurrenceId,
      actorUserId: userId,
      editKind: "environment-record",
      payload: { fields: Object.keys(values).sort() },
    })
    : null;
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      "INSERT INTO observation_environment_records (record_id, occurrence_id, lat, lng, structured_json, source_lang) VALUES (?, ?, ?, ?, ?, 'ja')"
    ).bind(recordId, occurrenceId, lat, lng, JSON.stringify(structured)),
    compatibleOccurrenceDetailEditEvent(env, occurrenceId, userId, "environment-record", { values }),
    compatibleReadmodelRefreshOutbox(env, occurrenceId, null),
    ...observationDualWriteStatements(env, ownerPlan),
    ...observationDualWriteStatements(env, editPlan),
  ]);
  return { recordId };
}

async function requireCompatibleEnvironmentRecordStorage(env: Env): Promise<void> {
  const rows = await env.OBS_DB.prepare(
    "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('observation_environment_records', 'observation_detail_edit_events')"
  ).all<{ name: string }>();
  const available = new Set((rows.results ?? []).map((row) => row.name));
  if (!available.has("observation_environment_records") || !available.has("observation_detail_edit_events")) {
    throw new HttpError(503, "environment_record_storage_unavailable");
  }
}

function compatibleOccurrenceDetailEditEvent(
  env: Env,
  observationId: string,
  actorUserId: string,
  editKind: string,
  payload: Record<string, unknown>
): D1PreparedStatement {
  return env.OBS_DB.prepare(
    "INSERT INTO observation_detail_edit_events (edit_id, observation_id, actor_user_id, edit_kind, payload_json) VALUES (?, ?, ?, ?, ?)"
  ).bind(newId("edit"), observationId, actorUserId, editKind, JSON.stringify(payload));
}

function compatibleReadmodelRefreshOutbox(env: Env, observationId: string, partitionMonth: string | null): D1PreparedStatement {
  return env.OBS_DB.prepare(
    "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
  ).bind(newId("outbox"), "readmodel.refresh", observationId, JSON.stringify({ observationId }), partitionMonth);
}

function normalizeCompatibleOrganismOrigin(value: unknown): CompatibleOrganismOrigin {
  const raw = String(value ?? "").trim().toLowerCase();
  const option = COMPATIBLE_ORGANISM_ORIGIN_OPTIONS.find((item) => item.value === raw);
  if (!option) throw new HttpError(400, "invalid_organism_origin");
  return option.value;
}

function compatibleOrganismOriginLabel(value: CompatibleOrganismOrigin): string {
  return COMPATIBLE_ORGANISM_ORIGIN_OPTIONS.find((item) => item.value === value)?.label ?? "不明";
}

function normalizeCompatibleObservedAt(value: unknown): string {
  const raw = String(value ?? "").trim();
  const parsed = new Date(raw);
  if (!raw || Number.isNaN(parsed.getTime())) {
    throw new HttpError(400, "invalid_observed_at");
  }
  if (parsed.getTime() > Date.now() + 24 * 60 * 60 * 1000) {
    throw new HttpError(400, "invalid_observed_at");
  }
  return parsed.toISOString();
}

function normalizeCompatibleLatitude(value: unknown): number {
  const latitude = Number(value);
  if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) {
    throw new HttpError(400, "invalid_latitude");
  }
  return Number(latitude.toFixed(6));
}

function normalizeCompatibleLongitude(value: unknown): number {
  const longitude = Number(value);
  if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) {
    throw new HttpError(400, "invalid_longitude");
  }
  return Number(longitude.toFixed(6));
}

function normalizeCompatibleEnvironmentRecordField(value: unknown): CompatibleEnvironmentRecordField {
  const raw = String(value ?? "").trim();
  if (raw in COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS) return raw as CompatibleEnvironmentRecordField;
  throw new HttpError(400, "invalid_environment_record_field");
}

function normalizeCompatibleEnvironmentRecordValue(field: CompatibleEnvironmentRecordField, value: unknown): string {
  const raw = String(value ?? "").trim();
  if (COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS[field].some((item) => item.value === raw)) return raw;
  throw new HttpError(400, "invalid_environment_record_value");
}

function compatibleEnvironmentRecordLabel(field: CompatibleEnvironmentRecordField, value: string): string {
  return COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS[field].find((item) => item.value === value)?.label ?? "不明";
}

function parseCompatibleStructuredJson(value: string | null | undefined): Record<string, string> {
  if (!value) return {};
  try {
    const parsed = JSON.parse(value) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    return Object.fromEntries(
      Object.entries(parsed as Record<string, unknown>)
        .filter((entry): entry is [string, string] => typeof entry[1] === "string" && entry[1].trim() !== "")
    );
  } catch {
    return {};
  }
}

function mergeCompatibleUserEnvironmentRecordValues(
  previous: Record<string, string>,
  values: Partial<Record<CompatibleEnvironmentRecordField, string>>,
  updatedBy: string
): Record<string, string> {
  const updatedAt = new Date().toISOString();
  const structured = { ...previous };
  for (const field of Object.keys(COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS) as CompatibleEnvironmentRecordField[]) {
    const value = values[field];
    if (value == null) continue;
    structured[field] = normalizeCompatibleEnvironmentRecordValue(field, value);
    structured[`${field}_source`] = "user";
    structured[`${field}_confidence`] = "1.00";
    structured[`${field}_updated_at`] = updatedAt;
  }
  structured.environment_record_status = "user_edited";
  structured.environment_record_updated_by = updatedBy;
  structured.environment_record_updated_at = updatedAt;
  structured.updated_by = updatedBy;
  structured.updated_at = updatedAt;
  return structured;
}

function compatibleEnvironmentRecordDraftHasValues(record: Record<string, string>): boolean {
  return (Object.keys(COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS) as CompatibleEnvironmentRecordField[])
    .some((field) => {
      const value = record[field];
      return typeof value === "string" && value.trim() !== "" && value !== "unknown";
    });
}

function compatibleEnvironmentRecordFieldSource(record: Record<string, string>, field: CompatibleEnvironmentRecordField): string {
  const source = String(record[`${field}_source`] ?? "").trim();
  if (source === "user" || source === "derived" || source === "legacy") return source;
  return record[field] && record[field] !== "unknown" ? "legacy" : "unknown";
}

function normalizeCompatibleEnvironmentRecordDraft(value: unknown, sourceMethod: string): Record<string, string> {
  const raw = value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const updatedAt = new Date().toISOString();
  const structured: Record<string, string> = {
    environment_record_source: sourceMethod,
    environment_record_status: "auto_draft",
    environment_record_updated_by: sourceMethod,
    environment_record_updated_at: updatedAt
  };
  for (const field of Object.keys(COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS) as CompatibleEnvironmentRecordField[]) {
    const rawFieldValue = raw[field];
    const nested = rawFieldValue && typeof rawFieldValue === "object" && !Array.isArray(rawFieldValue)
      ? rawFieldValue as Record<string, unknown>
      : {};
    const candidateValue = typeof rawFieldValue === "string" ? rawFieldValue : nested.value;
    if (typeof candidateValue !== "string" || candidateValue.trim() === "" || candidateValue === "unknown") continue;
    let normalizedValue = "";
    try {
      normalizedValue = normalizeCompatibleEnvironmentRecordValue(field, candidateValue);
    } catch {
      continue;
    }
    const confidenceNumber = Number(nested.confidence ?? 0.44);
    const confidence = Number.isFinite(confidenceNumber)
      ? Math.max(0, Math.min(1, confidenceNumber)).toFixed(2)
      : "0.44";
    structured[field] = normalizedValue;
    structured[`${field}_source`] = "derived";
    structured[`${field}_confidence`] = confidence;
    structured[`${field}_method`] = sourceMethod;
  }
  return compatibleEnvironmentRecordDraftHasValues(structured) ? structured : {};
}

function mergeCompatibleAutoEnvironmentRecordValues(
  previous: Record<string, string>,
  draft: Record<string, string>,
  sourceMethod: string
): Record<string, string> {
  if (!compatibleEnvironmentRecordDraftHasValues(draft)) return previous;
  const updatedAt = new Date().toISOString();
  const structured = { ...previous };
  let changed = false;
  for (const field of Object.keys(COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS) as CompatibleEnvironmentRecordField[]) {
    const incoming = draft[field];
    if (!incoming || incoming === "unknown") continue;
    const current = structured[field];
    const currentSource = compatibleEnvironmentRecordFieldSource(structured, field);
    if (currentSource === "user" || currentSource === "legacy") continue;
    const currentConfidence = Number(structured[`${field}_confidence`] ?? "0");
    const incomingConfidence = Number(draft[`${field}_confidence`] ?? "0.44");
    if (current && current !== "unknown" && Number.isFinite(currentConfidence) && incomingConfidence < currentConfidence) continue;
    structured[field] = incoming;
    structured[`${field}_source`] = "derived";
    structured[`${field}_confidence`] = Number.isFinite(incomingConfidence)
      ? Math.max(0, Math.min(1, incomingConfidence)).toFixed(2)
      : "0.44";
    structured[`${field}_method`] = sourceMethod;
    changed = true;
  }
  if (changed) {
    structured.environment_record_source = draft.environment_record_source ?? sourceMethod;
    structured.environment_record_status = structured.environment_record_status === "user_edited" ? "user_edited" : "auto_draft";
    structured.environment_record_updated_by = sourceMethod;
    structured.environment_record_updated_at = updatedAt;
    structured.updated_by = sourceMethod;
    structured.updated_at = updatedAt;
  }
  return structured;
}

async function insertCompatibleAutoEnvironmentRecordIfPresent(
  input: {
    occurrenceId: string;
    actorUserId: string;
    latitude: number;
    longitude: number;
    draft: unknown;
    sourceMethod: string;
  },
  env: Env
): Promise<void> {
  const draft = normalizeCompatibleEnvironmentRecordDraft(input.draft, input.sourceMethod);
  if (!compatibleEnvironmentRecordDraftHasValues(draft)) return;
  await requireCompatibleEnvironmentRecordStorage(env);
  const previousRow = await env.OBS_DB.prepare(
    "SELECT structured_json FROM observation_environment_records WHERE occurrence_id = ? ORDER BY created_at DESC LIMIT 1"
  ).bind(input.occurrenceId).first<{ structured_json: string }>();
  const previous = parseCompatibleStructuredJson(previousRow?.structured_json);
  const structured = mergeCompatibleAutoEnvironmentRecordValues(previous, draft, input.sourceMethod);
  if (!compatibleEnvironmentRecordDraftHasValues(structured) || JSON.stringify(structured) === JSON.stringify(previous)) return;
  structured.environment_record_location_source = "exact_observation";
  const recordId = newId("envrec");
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      "INSERT INTO observation_environment_records (record_id, occurrence_id, lat, lng, structured_json, source_lang) VALUES (?, ?, ?, ?, ?, 'ja')"
    ).bind(recordId, input.occurrenceId, input.latitude, input.longitude, JSON.stringify(structured)),
    compatibleOccurrenceDetailEditEvent(env, input.occurrenceId, input.actorUserId, "environment-record-auto-draft", {
      source: input.sourceMethod,
      fields: Object.keys(COMPATIBLE_ENVIRONMENT_RECORD_OPTIONS).filter((field) => structured[field])
    }),
    compatibleReadmodelRefreshOutbox(env, input.occurrenceId, null)
  ]);
}

async function attachVideoAssetToObservation(input: {
  uid: string;
  observationId: string;
  ownerUserId: string;
  objectKey: string;
  bytes: number;
  durationMs: number;
}, env: Env): Promise<{ sent: number; pending: number }> {
  const observation = await env.OBS_DB.prepare(
    "SELECT draft_id, owner_user_id, partition_month FROM observations WHERE observation_id = ?"
  ).bind(input.observationId).first<{ draft_id: string; owner_user_id: string; partition_month: string | null }>();
  if (!observation) {
    throw new HttpError(404, `observation not found: ${input.observationId}`);
  }
  const partitionMonth = observation.partition_month ?? partitionMonthFromDate(new Date().toISOString());

  const assetId = `video_asset_${input.uid}`;
  const outboxMediaId = newId("outbox");
  const outboxReadModelId = newId("outbox");
  const ownerPlan = await existingOwnerObservationDualWritePlan(
    input.observationId,
    observation.owner_user_id,
    env
  );
  const mediaPlan = observationDualWriteEnabled(env)
    ? await buildMediaReassignmentDualWritePlan({
      recordId: input.observationId,
      mediaId: assetId,
      actorUserId: observation.owner_user_id,
      role: "supporting_evidence",
      sourcePayload: { streamUid: input.uid, mime: "video/mp4" },
    })
    : null;

  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT OR REPLACE INTO asset_ledger
       (asset_id, draft_id, observation_id, owner_user_id, object_key, sha256, mime, bytes, width, height, duration_ms, visibility, processing_state, uploaded_at, partition_month)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'private', 'uploaded', CURRENT_TIMESTAMP, ?)`
    ).bind(
      assetId,
      observation.draft_id,
      input.observationId,
      observation.owner_user_id,
      input.objectKey,
      null,
      "video/mp4",
      input.bytes,
      null,
      null,
      input.durationMs,
      partitionMonth
    ),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxMediaId, "media.process", input.observationId, JSON.stringify({ observationId: input.observationId, assetId }), partitionMonth),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxReadModelId, "readmodel.refresh", input.observationId, JSON.stringify({ observationId: input.observationId }), partitionMonth),
    ...observationDualWriteStatements(env, ownerPlan),
    ...observationDualWriteStatements(env, mediaPlan),
    rollbackLedgerInsert(env, {
      eventType: "asset.video.finalize",
      targetId: assetId,
      partitionMonth,
      sourceEndpoint: "POST /api/v1/videos/:uid/finalize",
      payload: {
        assetId,
        observationId: input.observationId,
        ownerUserId: observation.owner_user_id,
        objectKey: input.objectKey,
        streamUid: input.uid,
        bytes: input.bytes,
        durationMs: input.durationMs,
        readyToStream: true
      },
      replaySql: postgresAssetReplaySql(assetId, input.observationId, observation.owner_user_id, input.objectKey, null, "video/mp4", input.bytes, "private")
    })
  ]);

  return dispatchOutboxBestEffort(env, [
    { outboxId: outboxMediaId, topic: "media.process", targetId: input.observationId },
    { outboxId: outboxReadModelId, topic: "readmodel.refresh", targetId: input.observationId }
  ]);
}

type LegacyObservationIdempotencyRow = {
  user_id: string;
  visit_id: string | null;
  occurrence_id: string | null;
  occurrence_ids: string | null;
  place_id: string | null;
  request_fingerprint: string;
  write_status: string;
};

const LEGACY_IDEMPOTENCY_WAIT_ATTEMPTS = 40;
const LEGACY_IDEMPOTENCY_WAIT_MS = 25;

function normalizeCompatibleClientSubmissionId(value: unknown): string | null {
  const text = normalizeOptionalText(value);
  if (!text) return null;
  if (text.length > 180) {
    throw new HttpError(400, "client_submission_id_too_long");
  }
  if (!/^[A-Za-z0-9._:-]+$/.test(text)) {
    throw new HttpError(400, "client_submission_id_invalid");
  }
  return text;
}

function parseLegacyOccurrenceIds(raw: string | null | undefined, fallback: string): string[] {
  if (!raw) return [fallback];
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [fallback];
    const ids = parsed.filter((id): id is string => typeof id === "string" && id.trim() !== "");
    return ids.length > 0 ? ids : [fallback];
  } catch {
    return [fallback];
  }
}

async function legacyObservationRequestFingerprint(input: LegacyObservationUpsertInput): Promise<string> {
  const subjects = (input.subjects ?? []).map((subject) => ({
    scientificName: normalizeOptionalText(subject.scientificName),
    vernacularName: normalizeOptionalText(subject.vernacularName),
    rank: normalizeOptionalText(subject.rank),
    isPrimary: Boolean(subject.isPrimary)
  }));
  const clientPhotoHashes = Array.isArray(input.sourcePayload?.client_photo_sha256s)
    ? input.sourcePayload?.client_photo_sha256s.filter((value): value is string => typeof value === "string")
    : null;
  const fingerprintPayload = Object.fromEntries(
    Object.entries(input).filter(([key]) => key !== "observationId" && key !== "clientSubmissionId" && key !== "sourcePayload"),
  );
  return sha256Hex(textToArrayBuffer(stableJson({
    ...fingerprintPayload,
    clientPhotoHashes,
    subjects,
    taxon: input.taxon ?? null
  })));
}

function normalizeSafePublicAreaLabelCandidate(value: unknown): string | null {
  const text = normalizeOptionalText(value);
  if (!text) return null;
  const normalized = text.normalize("NFKC").replace(/\s+/g, "");
  if (!normalized || normalized.length > PUBLIC_AREA_LABEL_MAX_LENGTH) return null;
  if (PUBLIC_AREA_LABEL_SENSITIVE_PATTERN.test(normalized)) return null;
  if (PUBLIC_AREA_LABEL_ADDRESS_PATTERN.test(normalized)) return null;
  return normalized;
}

function shouldCoarsenPublicAreaLabel(label: string): boolean {
  const normalized = label.normalize("NFKC").toLowerCase();
  return normalized.endsWith("村")
    || normalized.endsWith("mura")
    || normalized.endsWith("son")
    || normalized.endsWith("village");
}

function resolveSafePublicAreaLabel(input: Pick<LegacyObservationUpsertInput, "municipality" | "prefecture">): string | null {
  const municipality = normalizeSafePublicAreaLabelCandidate(input.municipality);
  const prefecture = normalizeSafePublicAreaLabelCandidate(input.prefecture);
  if (municipality && !shouldCoarsenPublicAreaLabel(municipality)) return municipality;
  return prefecture;
}

function publicStreamAllowsLocationPrecision(value: unknown): boolean {
  const precision = normalizeOptionalText(value);
  return !precision || PUBLIC_STREAM_ALLOWED_LOCATION_PRECISIONS.has(precision);
}

function buildLegacyCompatibleObservationResponse(input: {
  visitId: string;
  occurrenceId: string;
  occurrenceIds: string[];
  placeId: string;
  placeName: string;
  taxonLabel: string | null;
  clientSubmissionId: string | null;
  idempotencyReused: boolean;
  placeMemory?: unknown;
  placeMemorySample?: unknown;
}, source: LegacyObservationUpsertInput) {
  return {
    ok: true,
    visitId: input.visitId,
    occurrenceId: input.occurrenceId,
    occurrenceIds: input.occurrenceIds,
    placeId: input.placeId,
    impact: {
      placeName: input.placeName,
      visitCount: 1,
      previousObservedAt: null,
      focusLabel: input.taxonLabel,
      captureState: normalizeOptionalText(source.sourcePayload?.quick_capture_state) ?? null
    },
    compatibility: {
      attempted: false,
      succeeded: false
    },
    idempotency: input.clientSubmissionId ? {
      clientSubmissionId: input.clientSubmissionId,
      reused: input.idempotencyReused
    } : undefined,
    placeMemory: input.placeMemory ?? null,
    placeMemorySample: input.placeMemorySample ?? [],
    contributionReceipts: buildLegacyContributionReceipts(input.visitId, input.occurrenceId, input.occurrenceIds.length, input.placeName, source),
    feedbackLoop: buildLegacyRecordFeedbackLoop(input.visitId, input.occurrenceId)
  };
}

type ObservationEventRegistrationBridge = {
  sessionId: string;
  clearEventCookie: boolean;
  registrationSucceeded: boolean;
  metricActorKey: string;
};

async function claimObservationEventRegistrationBridge(
  request: Request,
  env: Env,
  input: LegacyObservationUpsertInput,
  auth: SessionSnapshot | null
): Promise<ObservationEventRegistrationBridge | null> {
  if (!auth) return null;
  const eventSession = await resolveNativeObservationEventSession(env, input).catch(() => null);
  if (!eventSession) return null;
  const guestCredential = await readObservationEventGuestCredential(request.headers.get("cookie"), eventSession.sessionId);
  if (!guestCredential) return null;
  const guestToken = await observationEventGuestCredentialDigest(guestCredential);
  const [userParticipantBefore, guestParticipant] = await Promise.all([
    findObservationEventParticipant(env, eventSession.sessionId, auth.userId, null),
    findObservationEventParticipant(env, eventSession.sessionId, null, guestToken)
  ]);
  if (guestParticipant) {
    await claimObservationEventGuestParticipant(env, eventSession.sessionId, auth.userId, guestToken);
  }
  const userParticipantAfter = userParticipantBefore
    ?? await findObservationEventParticipant(env, eventSession.sessionId, auth.userId, null);
  if (!userParticipantAfter) return null;
  return {
    sessionId: eventSession.sessionId,
    clearEventCookie: true,
    registrationSucceeded: !userParticipantBefore && Boolean(guestParticipant),
    metricActorKey: `user:${auth.userId}`
  };
}

async function observationEventRegistrationBridgeResponseHeaders(
  bridge: ObservationEventRegistrationBridge | null
): Promise<Record<string, string> | undefined> {
  if (!bridge?.clearEventCookie) return undefined;
  return {
    "cache-control": "no-store",
    "set-cookie": await buildClearedObservationEventGuestCookie(bridge.sessionId)
  };
}

async function recordObservationEventRegistrationBridgeMetric(
  env: Env,
  bridge: ObservationEventRegistrationBridge | null
): Promise<void> {
  if (!bridge?.registrationSucceeded) return;
  await recordObservationEventServerFunnelMetric(env, bridge.sessionId, {
    event_name: "event_registration_succeeded",
    page: "record",
    auth_state: "signed_in",
    network_state: "unknown"
  }, bridge.metricActorKey);
}

async function upsertLegacyCompatibleObservation(request: Request, env: Env): Promise<Response> {
  const input = await readJson<LegacyObservationUpsertInput>(request);
  let authenticatedSession: SessionSnapshot | null = null;
  if (env.ENVIRONMENT === "production") {
    authenticatedSession = await readCompatibleSession(request, env);
    if (!authenticatedSession) {
      return json({ ok: false, error: "session_required" }, 401);
    }
    assertNonEmpty(input.userId, "userId");
    if (authenticatedSession.userId !== input.userId) {
      return json({ ok: false, error: "forbidden" }, 403);
    }
  } else {
    assertNonEmpty(input.userId, "userId");
    authenticatedSession = await readCompatibleSession(request, env).catch(() => null);
  }
  if (!Number.isFinite(input.latitude) || !Number.isFinite(input.longitude)) {
    throw new HttpError(400, "missing_location");
  }
  assertNonEmpty(input.observedAt, "observedAt");

  const requestedObservationId = normalizeOptionalId(input.observationId);
  if (requestedObservationId) {
    const existingObservation = await env.OBS_DB.prepare(
      "SELECT owner_user_id FROM observations WHERE observation_id = ?"
    ).bind(requestedObservationId).first<{ owner_user_id: string }>();
    if (existingObservation && existingObservation.owner_user_id !== input.userId) {
      return json({ ok: false, error: "forbidden" }, 403, { "cache-control": "no-store" });
    }
  }

  const clientSubmissionId = normalizeCompatibleClientSubmissionId(input.clientSubmissionId);
  const idempotencyFingerprint = clientSubmissionId
    ? await legacyObservationRequestFingerprint(input)
    : null;
  if (clientSubmissionId && idempotencyFingerprint) {
    const readExistingIdempotency = () => env.OBS_DB.prepare(
      `SELECT user_id, visit_id, occurrence_id, occurrence_ids, place_id, request_fingerprint, write_status
         FROM observation_write_idempotency
        WHERE client_submission_id = ?`
    ).bind(clientSubmissionId).first<LegacyObservationIdempotencyRow>();
    const waitForCompletedIdempotency = async (initial: LegacyObservationIdempotencyRow): Promise<LegacyObservationIdempotencyRow> => {
      let current = initial;
      for (let attempt = 0; attempt < LEGACY_IDEMPOTENCY_WAIT_ATTEMPTS && !current.visit_id; attempt += 1) {
        await new Promise((resolve) => setTimeout(resolve, LEGACY_IDEMPOTENCY_WAIT_MS));
        current = await readExistingIdempotency() ?? current;
      }
      return current;
    };
    const replayExistingIdempotency = async (existing: LegacyObservationIdempotencyRow): Promise<Response> => {
      const visitId = normalizeOptionalId(existing.visit_id);
      if (!visitId) {
        return json({ ok: false, error: "duplicate_submission_in_progress" }, 409);
      }
      const occurrenceId = normalizeOptionalId(existing.occurrence_id) ?? `occ:${visitId}:0`;
      const occurrenceIds = parseLegacyOccurrenceIds(existing.occurrence_ids, occurrenceId);
      await env.OBS_DB.prepare(
        `UPDATE observation_write_idempotency
            SET duplicate_count = duplicate_count + 1,
                last_seen_at = CURRENT_TIMESTAMP,
                updated_at = CURRENT_TIMESTAMP
          WHERE client_submission_id = ?`
      ).bind(clientSubmissionId).run();
      const placeId = normalizeOptionalId(existing.place_id) ?? `place:${blurLocation(input.latitude, input.longitude)}`;
      const placeName = normalizeOptionalText(input.siteName)
        ?? normalizeOptionalText(input.municipality)
        ?? normalizeOptionalText(input.prefecture)
        ?? "unknown place";
      const registrationBridge = await claimObservationEventRegistrationBridge(request, env, input, authenticatedSession);
      await recordObservationEventRegistrationBridgeMetric(env, registrationBridge);
      return json(buildLegacyCompatibleObservationResponse({
        visitId,
        occurrenceId,
        occurrenceIds,
        placeId,
        placeName,
        taxonLabel: resolveLegacyTaxonLabel(input),
        clientSubmissionId,
        idempotencyReused: true
      }, input), 200, await observationEventRegistrationBridgeResponseHeaders(registrationBridge));
    };
    const replayOrRejectExisting = async (initial: LegacyObservationIdempotencyRow): Promise<Response> => {
      if (initial.user_id !== input.userId || initial.request_fingerprint !== idempotencyFingerprint) {
        return json({ ok: false, error: "client_submission_id_conflict" }, 409);
      }
      const existing = initial.visit_id ? initial : await waitForCompletedIdempotency(initial);
      if (!existing.visit_id) {
        return json({ ok: false, error: "duplicate_submission_in_progress" }, 409);
      }
      return replayExistingIdempotency(existing);
    };
    const existing = await readExistingIdempotency();
    if (existing) {
      return replayOrRejectExisting(existing);
    }
    const reservation = await env.OBS_DB.prepare(
      `INSERT OR IGNORE INTO observation_write_idempotency (
         client_submission_id, user_id, request_fingerprint, write_status, source_payload,
         created_at, updated_at, last_seen_at
       ) VALUES (?, ?, ?, 'in_progress', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
    ).bind(
      clientSubmissionId,
      input.userId,
      idempotencyFingerprint,
      JSON.stringify({
        source: "cloudflare_observation_write",
        observation_id: normalizeOptionalId(input.observationId),
        client_photo_sha256s: Array.isArray(input.sourcePayload?.client_photo_sha256s)
          ? input.sourcePayload?.client_photo_sha256s.filter((value): value is string => typeof value === "string")
          : []
      })
    ).run();
    const reservationChanges = Number((reservation as { meta?: { changes?: unknown } } | null)?.meta?.changes);
    if (!Number.isFinite(reservationChanges)) {
      return json({ ok: false, error: "idempotency_reservation_unknown" }, 503, { "cache-control": "no-store" });
    }
    if (reservationChanges !== 1) {
      const concurrent = await readExistingIdempotency();
      if (!concurrent) {
        return json({ ok: false, error: "duplicate_submission_in_progress" }, 409);
      }
      return replayOrRejectExisting(concurrent);
    }
  }

  const draftId = newId("draft");
  const visitId = normalizeOptionalId(input.observationId) ?? newId("obs");
  const partition = resolveObservationPartition(input.observedAt, env);
  const occurrenceIds = resolveLegacyOccurrenceIds(visitId, input);
  const occurrenceId = occurrenceIds[0] ?? `occ:${visitId}:0`;
  const publicCell = blurLocation(input.latitude, input.longitude);
  const taxonLabel = resolveLegacyTaxonLabel(input);
  const placeName = normalizeOptionalText(input.siteName)
    ?? normalizeOptionalText(input.municipality)
    ?? normalizeOptionalText(input.prefecture)
    ?? "unknown place";
  const placeId = normalizeOptionalId(input.siteId) ?? `place:${publicCell}`;
  const visibility = input.visibility === "private" ? "private" : "public";
  const publicAreaLabel = visibility === "public" ? resolveSafePublicAreaLabel(input) : null;
  const dataRights = normalizeObservationDataRightsNative(input.dataRights ?? input.sourcePayload?.dataRights);
  const civicContext = buildObservationCivicContextNative(input, visitId, occurrenceId);
  const placeMemory = await upsertPlaceMemoryForObservationNative(env, input, { visitId, occurrenceId, publicCell });
  const civicContextStatements = civicContext
    ? [env.OBS_DB.prepare(
      `INSERT INTO civic_observation_contexts (
         context_id, visit_id, occurrence_id, context_kind, activity_label, activity_intent,
         participant_role, audience_scope, public_precision, risk_lane, report_consent,
         revisit_of_visit_id, field_id, route_id, plot_id, source_payload_json, updated_at
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(visit_id) DO UPDATE SET
         occurrence_id = excluded.occurrence_id,
         context_kind = excluded.context_kind,
         activity_label = excluded.activity_label,
         activity_intent = excluded.activity_intent,
         participant_role = excluded.participant_role,
         audience_scope = excluded.audience_scope,
         public_precision = excluded.public_precision,
         risk_lane = excluded.risk_lane,
         report_consent = excluded.report_consent,
         revisit_of_visit_id = excluded.revisit_of_visit_id,
         field_id = excluded.field_id,
         route_id = excluded.route_id,
         plot_id = excluded.plot_id,
         source_payload_json = excluded.source_payload_json,
         updated_at = CURRENT_TIMESTAMP`
    ).bind(
      civicContext.contextId,
      civicContext.visitId,
      civicContext.occurrenceId,
      civicContext.contextKind,
      civicContext.activityLabel,
      civicContext.activityIntent,
      civicContext.participantRole,
      civicContext.audienceScope,
      civicContext.publicPrecision,
      civicContext.riskLane,
      civicContext.reportConsent,
      civicContext.revisitOfVisitId,
      civicContext.fieldId,
      civicContext.routeId,
      civicContext.plotId,
      JSON.stringify(civicContext.sourcePayload)
    )]
    : [];
  const ownerDualWritePlan = observationDualWriteEnabled(env)
    ? await buildOwnerObservationUpsertPlan({
      recordId: visitId,
      ownerUserId: input.userId,
      visibility,
      subjectType: taxonLabel ? "organism" : "unknown_subject",
      individualCertainty: occurrenceIds.length > 1 ? "group" : "unknown",
      sourceSnapshot: {
        observedAt: input.observedAt,
        taxonLabel,
        visibility,
        occurrenceCount: occurrenceIds.length,
        hasMedia: Array.isArray(input.sourcePayload?.client_photo_sha256s)
          && input.sourcePayload.client_photo_sha256s.length > 0,
      },
    })
    : null;

  await env.CORE_DB.batch([
    env.CORE_DB.prepare("INSERT OR IGNORE INTO users (user_id) VALUES (?)").bind(input.userId)
  ]);
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT INTO draft_observations
       (draft_id, owner_user_id, observed_at, exact_lat, exact_lng, location_accuracy_m, public_cell, visibility, partition_month)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      draftId,
      input.userId,
      input.observedAt,
      input.latitude,
      input.longitude,
      numberOrNull(input.locationAccuracyM),
      publicCell,
      visibility,
      partition.partitionMonth
    ),
    env.OBS_DB.prepare(
      `INSERT INTO observations
       (observation_id, draft_id, owner_user_id, observed_at, taxon_label, note, exact_lat, exact_lng,
        location_accuracy_m, public_cell, visibility, partition_month, public_area_label)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        + ` ON CONFLICT(observation_id) DO UPDATE SET
          draft_id = excluded.draft_id,
          owner_user_id = excluded.owner_user_id,
          observed_at = excluded.observed_at,
          taxon_label = excluded.taxon_label,
          note = excluded.note,
          exact_lat = excluded.exact_lat,
          exact_lng = excluded.exact_lng,
          location_accuracy_m = excluded.location_accuracy_m,
          public_cell = excluded.public_cell,
          visibility = excluded.visibility,
          partition_month = excluded.partition_month,
          public_area_label = excluded.public_area_label,
          emergency_hidden = 0,
          processing_state = 'accepted'`
    ).bind(
      visitId,
      draftId,
      input.userId,
      input.observedAt,
      taxonLabel,
      input.note ?? null,
      input.latitude,
      input.longitude,
      numberOrNull(input.locationAccuracyM),
      publicCell,
      visibility,
      partition.partitionMonth,
      publicAreaLabel
    ),
    env.OBS_DB.prepare(
      "UPDATE draft_observations SET processing_state = 'finalized', finalized_at = CURRENT_TIMESTAMP WHERE draft_id = ?"
    ).bind(draftId),
    ...(clientSubmissionId ? [env.OBS_DB.prepare(
      `UPDATE observation_write_idempotency
          SET visit_id = ?,
              occurrence_id = ?,
              occurrence_ids = ?,
              place_id = ?,
              write_status = 'succeeded',
              updated_at = CURRENT_TIMESTAMP,
              last_seen_at = CURRENT_TIMESTAMP
        WHERE client_submission_id = ?`
    ).bind(visitId, occurrenceId, JSON.stringify(occurrenceIds), placeId, clientSubmissionId)] : []),
    env.OBS_DB.prepare(
      `INSERT INTO observation_data_rights
         (visit_id, occurrence_id, record_consent, research_use_consent, enterprise_report_consent,
          dataset_license, media_license, external_export_allowed, withdrawal_status, source_payload_json, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(visit_id) DO UPDATE SET
         occurrence_id = excluded.occurrence_id,
         record_consent = excluded.record_consent,
         research_use_consent = excluded.research_use_consent,
         enterprise_report_consent = excluded.enterprise_report_consent,
         dataset_license = excluded.dataset_license,
         media_license = excluded.media_license,
         external_export_allowed = excluded.external_export_allowed,
         withdrawal_status = excluded.withdrawal_status,
         source_payload_json = excluded.source_payload_json,
         updated_at = CURRENT_TIMESTAMP`
    ).bind(
      visitId,
      occurrenceId,
      dataRights.recordConsent,
      dataRights.researchUseConsent,
      dataRights.enterpriseReportConsent,
      dataRights.datasetLicense,
      dataRights.mediaLicense,
      dataRights.externalExportAllowed ? 1 : 0,
      dataRights.withdrawalStatus,
      JSON.stringify(dataRights.sourcePayload)
    ),
    ...placeMemory.statements,
    ...civicContextStatements,
    ...observationDualWriteStatements(env, ownerDualWritePlan),
    rollbackLedgerInsert(env, {
      eventType: "observation.upsert",
      targetId: visitId,
      partitionMonth: partition.partitionMonth,
      sourceEndpoint: "POST /api/v1/observations/upsert",
      payload: {
        visitId,
        occurrenceIds,
        ownerUserId: input.userId,
        observedAt: input.observedAt,
        taxonLabel,
        note: input.note ?? null,
        exactLat: input.latitude,
        exactLng: input.longitude,
        locationAccuracyM: numberOrNull(input.locationAccuracyM),
        publicCell,
        visibility,
        publicAreaLabel,
        placeId,
        placeName
      },
      replaySql: postgresObservationReplaySql(
        visitId,
        input.userId,
        input.observedAt,
        taxonLabel,
        input.note ?? null,
        input.latitude,
        input.longitude,
        numberOrNull(input.locationAccuracyM),
        publicCell,
        visibility
      )
    })
  ]);

  await insertCompatibleAutoEnvironmentRecordIfPresent({
    occurrenceId: visitId,
    actorUserId: input.userId,
    latitude: input.latitude,
    longitude: input.longitude,
    draft: input.environmentRecordDraft ?? input.sourcePayload?.environment_record_draft,
    sourceMethod: "record_photo_feedback_v1"
  }, env).catch((error) => {
    console.warn(JSON.stringify({
      message: "compatible_auto_environment_record_skipped",
      visitId,
      error: error instanceof Error ? error.message : String(error)
    }));
  });

  await upsertCompatibleWaterRecordIfPresent(env, input.waterRecord, {
    visitId,
    occurrenceId,
    effortMinutes: numberOrNull(input.sourcePayload?.effort_minutes) ?? null,
    targetTaxaScope: normalizeOptionalText(input.targetTaxaScope)
  });

  await autoMatchObservationToActiveRalliesNative(env, {
    userId: input.userId,
    visitId,
    occurrenceId,
    lat: input.latitude,
    lng: input.longitude,
    observedAt: input.observedAt
  }).catch((error) => {
    console.error("[observation-rally-auto-match] native post-save match failed", error);
  });

  const registrationBridge = await claimObservationEventRegistrationBridge(request, env, input, authenticatedSession);
  await recordObservationEventRegistrationBridgeMetric(env, registrationBridge);
  await hookLegacyObservationToEventNative(env, input, {
    visitId,
    occurrenceId,
    occurrenceIds,
    taxonLabel
  });

  if (visibility !== "public" || (await publicSafetyGateForObservation(visitId, env)).blocked) {
    await clearObservationPublicAreaLabel(visitId, env);
    await deletePublicReadmodelRow(visitId, env);
  }

  return json(buildLegacyCompatibleObservationResponse({
    visitId,
    occurrenceId,
    occurrenceIds,
    placeId,
    placeName,
    taxonLabel,
    clientSubmissionId,
    idempotencyReused: false,
    placeMemory: placeMemory.result,
    placeMemorySample: placeMemory.sample,
  }, input), 201, await observationEventRegistrationBridgeResponseHeaders(registrationBridge));
}

async function upsertCompatibleWaterRecordIfPresent(
  env: Env,
  input: CompatibleWaterRecordInput | null | undefined,
  context: { visitId: string; occurrenceId: string; effortMinutes: number | null; targetTaxaScope: string | null }
): Promise<void> {
  if (!input || typeof input !== "object") return;
  const catchOutcome = normalizeCatchOutcome(input.catchOutcome);
  if (!catchOutcome) return;

  const publicWaterbodyLabel = normalizeOptionalText(input.publicWaterbodyLabel);
  const waterbodyType = normalizeWaterbodyType(input.waterbodyType);
  const source = normalizeOptionalText(input.source) ?? "ikimon";
  const waterbodyId = normalizeOptionalId(input.waterbodyId)
    ?? (publicWaterbodyLabel ? await compatibleWaterbodyIdFor(publicWaterbodyLabel, waterbodyType, source) : null);
  const sourcePayload = {
    ...(asPlainObject(input.sourcePayload) ?? {}),
    source: "cloudflare_observation_write_water_record"
  };

  if (waterbodyId && publicWaterbodyLabel) {
    await env.OBS_DB.prepare(
      `INSERT INTO waterbodies (
         ikimon_waterbody_id, waterbody_type, parent_waterbody_id, public_label,
         source, source_version, geometry_precision, source_payload_json, updated_at
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(ikimon_waterbody_id) DO UPDATE SET
         waterbody_type = excluded.waterbody_type,
         parent_waterbody_id = excluded.parent_waterbody_id,
         public_label = excluded.public_label,
         source = excluded.source,
         source_version = excluded.source_version,
         geometry_precision = excluded.geometry_precision,
         source_payload_json = excluded.source_payload_json,
         updated_at = CURRENT_TIMESTAMP`
    ).bind(
      waterbodyId,
      waterbodyType,
      normalizeOptionalId(input.parentWaterbodyId),
      publicWaterbodyLabel,
      source,
      normalizeOptionalText(input.sourceVersion) ?? "v0",
      normalizeGeometryPrecision(input.geometryPrecision),
      JSON.stringify(sourcePayload)
    ).run();
  }

  await env.OBS_DB.prepare(
    `INSERT INTO water_record_extensions (
       visit_id, occurrence_id, waterbody_id, catch_outcome, capture_method,
       participant_count, effort_minutes, target_taxa_scope, released_count, kept_count,
       public_waterbody_label, environment_snapshot_json, source_payload_json, updated_at
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(visit_id) DO UPDATE SET
       occurrence_id = excluded.occurrence_id,
       waterbody_id = excluded.waterbody_id,
       catch_outcome = excluded.catch_outcome,
       capture_method = excluded.capture_method,
       participant_count = excluded.participant_count,
       effort_minutes = excluded.effort_minutes,
       target_taxa_scope = excluded.target_taxa_scope,
       released_count = excluded.released_count,
       kept_count = excluded.kept_count,
       public_waterbody_label = excluded.public_waterbody_label,
       environment_snapshot_json = excluded.environment_snapshot_json,
       source_payload_json = excluded.source_payload_json,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(
    context.visitId,
    context.occurrenceId,
    waterbodyId,
    catchOutcome,
    normalizeOptionalText(input.captureMethod),
    integerOrNull(input.participantCount),
    finiteNumberOrNull(input.effortMinutes) ?? context.effortMinutes,
    normalizeOptionalText(input.targetTaxaScope) ?? context.targetTaxaScope,
    integerOrNull(input.releasedCount),
    integerOrNull(input.keptCount),
    publicWaterbodyLabel,
    JSON.stringify(asPlainObject(input.environmentSnapshot) ?? {}),
    JSON.stringify(sourcePayload)
  ).run();
}

function normalizeCatchOutcome(value: unknown): "caught" | "released" | "kept" | "lost" | "no_catch" | "observed_only" | null {
  return value === "caught" || value === "released" || value === "kept" || value === "lost" || value === "no_catch" || value === "observed_only"
    ? value
    : null;
}

function normalizeWaterbodyType(value: unknown): string {
  const allowed = ["unspecified", "basin", "watershed", "river", "river_segment", "lake", "pond", "wetland", "estuary", "coast", "port", "harbor", "artificial_canal"];
  const text = normalizeOptionalText(value);
  return text && allowed.includes(text) ? text : "unspecified";
}

function normalizeGeometryPrecision(value: unknown): string {
  const allowed = ["label_only", "municipality", "mesh", "segment", "polygon", "exact_private"];
  const text = normalizeOptionalText(value);
  return text && allowed.includes(text) ? text : "label_only";
}

async function compatibleWaterbodyIdFor(label: string, type: string, source: string): Promise<string> {
  const hash = await sha256Hex(textToArrayBuffer(`${source}|${type}|${label.trim().toLowerCase()}`));
  return `ikimon_waterbody_${hash.slice(0, 16)}`;
}

type LegacyObservationEventHookResult = {
  visitId: string;
  occurrenceId: string;
  occurrenceIds: string[];
  taxonLabel: string | null;
};

async function hookLegacyObservationToEventNative(
  env: Env,
  input: LegacyObservationUpsertInput,
  result: LegacyObservationEventHookResult
): Promise<void> {
  const session = await resolveNativeObservationEventSession(env, input).catch(() => null);
  if (!session) return;
  const requestedTeamId = normalizeOptionalText(input.teamId)
    ?? normalizeOptionalText(input.sourcePayload?.teamId)
    ?? normalizeOptionalText(input.sourcePayload?.team_id);
  const participant = await findObservationEventParticipant(env, session.sessionId, input.userId, null).catch(() => null);
  const isOrganizer = session.organizerUserId === input.userId;
  if (!isOrganizer && !participant) return;
  if (!isOrganizer && requestedTeamId && participant?.team_id !== requestedTeamId) return;
  const teamId = requestedTeamId ?? participant?.team_id ?? null;
  const eventType = input.fieldScan && typeof input.fieldScan === "object" ? "field_scan_added" : "observation_added";
  try {
    await appendObservationEventLive(env, {
      sessionId: session.sessionId,
      type: eventType,
      scope: "all",
      actorUserId: input.userId,
      teamId,
      payload: {
        visit_id: result.visitId,
        occurrence_id: result.occurrenceId,
        occurrence_ids: result.occurrenceIds,
        observation_id: result.visitId,
        taxon_name: result.taxonLabel,
        public_lat: roundPublicEventCoordinate(input.latitude),
        public_lng: roundPublicEventCoordinate(input.longitude),
        observed_at: input.observedAt,
        source_type: eventType === "field_scan_added" ? "field_scan" : "record",
        participant_role: normalizeOptionalText(input.participantRole)
          ?? normalizeOptionalText(input.sourcePayload?.participantRole)
          ?? normalizeOptionalText(input.sourcePayload?.participant_role),
        field_scan: sanitizeObservationEventFieldScan(input.fieldScan),
        exact_location_stored: false
      }
    });
  } catch (err) {
    console.error("[observation-event-dual-write] native live event failed", err);
  }
  await recordObservationEventServerFunnelMetric(env, session.sessionId, {
    event_name: "event_observation_succeeded",
    page: "record",
    auth_state: "signed_in",
    network_state: "unknown"
  }, participant ? `participant:${participant.participant_id}` : `user:${input.userId}`);
  try {
    await recordObservationEventMeshVisit(env, {
      sessionId: session.sessionId,
      lat: roundPublicEventCoordinate(input.latitude),
      lng: roundPublicEventCoordinate(input.longitude),
      observationDelta: 1,
      teamId
    });
  } catch (err) {
    console.error("[observation-event-dual-write] native mesh upsert failed", err);
  }
  if (result.taxonLabel) {
    await offerNativeObservationEventQuestForNewTaxon(env, session.sessionId, result.taxonLabel, teamId).catch((err) => {
      console.error("[observation-event-dual-write] native quest trigger failed", err);
    });
  }
}

async function resolveNativeObservationEventContextFromPayload(
  env: Env,
  input: Record<string, unknown>,
  auth: SessionSnapshot | null
): Promise<{ sessionId: string; teamId: string | null } | null> {
  const explicitSessionId = normalizeOptionalText(input.eventSessionId)
    ?? normalizeOptionalText(input.event_session_id);
  const eventCode = normalizeOptionalText(input.eventCode)
    ?? normalizeOptionalText(input.event_code);
  const eventSession = explicitSessionId
    ? await getObservationEventSessionById(env, explicitSessionId)
    : eventCode
      ? await getObservationEventSessionByEventCode(env, eventCode)
      : null;
  if (!eventSession || eventSession.endedAt) return null;

  const requestedTeamId = normalizeOptionalText(input.teamId)
    ?? normalizeOptionalText(input.team_id);
  const participant = await findObservationEventParticipant(env, eventSession.sessionId, auth?.userId ?? null, null).catch(() => null);
  const isOrganizer = Boolean(auth?.userId && eventSession.organizerUserId === auth.userId);
  if (!isOrganizer && !participant) return null;
  if (!isOrganizer && requestedTeamId && participant?.team_id !== requestedTeamId) return null;

  return {
    sessionId: eventSession.sessionId,
    teamId: requestedTeamId ?? participant?.team_id ?? null
  };
}

async function appendGuideSceneEventNative(input: {
  env: Env;
  body: Record<string, unknown>;
  session: SessionSnapshot | null;
  guideRecordId: string;
  guideSessionId: string;
  source: string;
  lat: number;
  lng: number;
  capturedAt: string;
  sceneSummary: string;
  detectedSpecies: string[];
  detectedFeatures: unknown[];
  primarySubject: Record<string, unknown>;
}): Promise<boolean> {
  const eventContext = await resolveNativeObservationEventContextFromPayload(input.env, input.body, input.session);
  if (!eventContext) return false;
  await appendObservationEventLive(input.env, {
    sessionId: eventContext.sessionId,
    type: "guide_scene_added",
    scope: "all",
    actorUserId: input.session?.userId ?? null,
    teamId: eventContext.teamId,
    payload: {
      guide_record_id: input.guideRecordId,
      guide_session_id: input.guideSessionId,
      scene_id: normalizeOptionalText(input.body.sceneId ?? input.body.scene_id) ?? null,
      scene_summary: input.sceneSummary,
      detected_species: input.detectedSpecies,
      detected_features: input.detectedFeatures,
      primary_subject: input.primarySubject,
      public_lat: roundPublicEventCoordinate(input.lat),
      public_lng: roundPublicEventCoordinate(input.lng),
      captured_at: input.capturedAt,
      participant_role: normalizeOptionalText(input.body.participantRole)
        ?? normalizeOptionalText(input.body.participant_role),
      source_type: input.source,
      exact_location_stored: false
    }
  });
  return true;
}

async function appendMobileAudioObservationEventNative(input: {
  env: Env;
  body: Record<string, unknown>;
  event: Record<string, unknown>;
  session: SessionSnapshot | null;
  fieldscanSessionId: string;
}): Promise<boolean> {
  const eventContext = await resolveNativeObservationEventContextFromPayload(
    input.env,
    { ...input.body, ...input.event },
    input.session
  );
  if (!eventContext) return false;
  const lat = numberOrNullFromUnknown(input.event.lat ?? input.body.lat);
  const lng = numberOrNullFromUnknown(input.event.lng ?? input.body.lng);
  await appendObservationEventLive(input.env, {
    sessionId: eventContext.sessionId,
    type: "field_scan_added",
    scope: "all",
    actorUserId: input.session?.userId ?? null,
    teamId: eventContext.teamId,
    payload: {
      segment_id: normalizeOptionalText(input.event.segmentId ?? input.event.segment_id ?? input.event.id) ?? crypto.randomUUID(),
      fieldscan_session_id: input.fieldscanSessionId,
      scan_mode: "audio_segment",
      public_lat: lat == null ? null : roundPublicEventCoordinate(lat),
      public_lng: lng == null ? null : roundPublicEventCoordinate(lng),
      recorded_at: normalizeOptionalText(input.event.recordedAt ?? input.event.recorded_at ?? input.body.recordedAt ?? input.body.recorded_at),
      duration_sec: numberOrNullFromUnknown(input.event.durationSec ?? input.event.duration_sec),
      participant_role: normalizeOptionalText(input.event.participantRole ?? input.body.participantRole)
        ?? normalizeOptionalText(input.event.participant_role ?? input.body.participant_role),
      source_type: "field_scan_audio",
      raw_audio_stored: false,
      exact_location_stored: false
    }
  });
  return true;
}

function sanitizeObservationEventFieldScan(input: unknown): Record<string, unknown> | null {
  const payload = asPlainObject(input);
  if (!payload) return null;
  const safe: Record<string, unknown> = {};
  const scanMode = normalizeOptionalText(payload.scan_mode) ?? normalizeOptionalText(payload.scanMode) ?? normalizeOptionalText(payload.mode);
  if (scanMode) safe.scan_mode = scanMode;
  const status = normalizeOptionalText(payload.status) ?? normalizeOptionalText(payload.review_status) ?? normalizeOptionalText(payload.reviewStatus);
  if (status) safe.status = status;
  const confidence = numberOrNullFromUnknown(payload.confidence);
  if (confidence !== null) safe.confidence = confidence;
  const durationSec = numberOrNullFromUnknown(payload.duration_sec ?? payload.durationSec);
  if (durationSec !== null) safe.duration_sec = durationSec;
  const labels = Array.isArray(payload.labels)
    ? payload.labels.map((label) => normalizeOptionalText(label)).filter((label): label is string => Boolean(label)).slice(0, 12)
    : [];
  if (labels.length > 0) safe.labels = labels;
  return Object.keys(safe).length > 0 ? safe : { sanitized: true };
}

async function resolveNativeObservationEventSession(env: Env, input: LegacyObservationUpsertInput) {
  const explicitSessionId = normalizeOptionalText(input.eventSessionId)
    ?? normalizeOptionalText(input.sourcePayload?.eventSessionId)
    ?? normalizeOptionalText(input.sourcePayload?.event_session_id);
  const eventCode = normalizeOptionalText(input.eventCode)
    ?? normalizeOptionalText(input.sourcePayload?.eventCode)
    ?? normalizeOptionalText(input.sourcePayload?.event_code);
  const [sessionById, sessionByCode] = await Promise.all([
    explicitSessionId ? getObservationEventSessionById(env, explicitSessionId) : Promise.resolve(null),
    eventCode ? getObservationEventSessionByEventCode(env, eventCode) : Promise.resolve(null)
  ]);
  if (explicitSessionId && eventCode && (!sessionById || !sessionByCode || sessionById.sessionId !== sessionByCode.sessionId)) {
    return null;
  }
  const session = sessionById ?? sessionByCode;
  const endedAtMs = session?.endedAt ? Date.parse(session.endedAt) : Number.NaN;
  if (!session || (Number.isFinite(endedAtMs) && endedAtMs <= Date.now())) return null;
  return session;
}

async function offerNativeObservationEventQuestForNewTaxon(
  env: Env,
  sessionId: string,
  taxonLabel: string,
  teamId: string | null
): Promise<void> {
  const recent = await env.OBS_DB.prepare(
    `SELECT COUNT(*) AS recent
       FROM observation_event_live_events
      WHERE session_id = ?
        AND type = 'observation_added'
        AND created_at > datetime('now', '-60 seconds')
        AND json_extract(payload_json, '$.taxon_name') = ?`
  ).bind(sessionId, taxonLabel).first<{ recent: number }>();
  if (Number(recent?.recent ?? 0) > 1) return;
  const questId = crypto.randomUUID();
  const payload: Record<string, unknown> = {
    kind: "taxa",
    headline: `${taxonLabel}の周辺をもう少し`,
    prompt: `${taxonLabel}が出た場所の周辺で、似た環境を数分だけ見てみる。`,
    rationale: "同じ時間帯・近い環境の追加記録は、観察会の種リストと努力量の両方を補強します。",
    trigger: "new_species",
    generated_by: "cloudflare-d1-static-quest"
  };
  await env.OBS_DB.prepare(
    `INSERT INTO observation_event_quests
       (quest_id, session_id, team_id, status, payload_json)
     VALUES (?, ?, ?, 'offered', ?)`
  ).bind(questId, sessionId, teamId, JSON.stringify(payload)).run();
  await appendObservationEventLive(env, {
    sessionId,
    type: "quest_offered",
    scope: teamId ? "team" : "all",
    teamId,
    payload: { quest_id: questId, ...payload }
  });
}

type NativeObservationEventQuestTrigger =
  | "interval"
  | "new_species"
  | "target_hit"
  | "stuck"
  | "rare_alert"
  | "ending_soon"
  | "manual";

const OBSERVATION_EVENT_QUEST_TRIGGERS = new Set<NativeObservationEventQuestTrigger>([
  "interval",
  "new_species",
  "target_hit",
  "stuck",
  "rare_alert",
  "ending_soon",
  "manual"
]);

function normalizeObservationEventQuestTrigger(value: unknown): NativeObservationEventQuestTrigger {
  return typeof value === "string" && OBSERVATION_EVENT_QUEST_TRIGGERS.has(value as NativeObservationEventQuestTrigger)
    ? value as NativeObservationEventQuestTrigger
    : "manual";
}

async function runObservationEventQuest(request: Request, env: Env, sessionId: string): Promise<Response> {
  const organizer = await requireObservationEventOrganizer(request, env, sessionId);
  if (organizer instanceof Response) return organizer;
  const body = await readJson<Record<string, unknown>>(request);
  const trigger = normalizeObservationEventQuestTrigger(body.trigger);
  const result = await generateNativeObservationEventQuests(env, organizer.session, {
    trigger,
    skipRecentDedup: true
  });
  return json(result, 200, { "cache-control": "no-store" });
}

async function decideObservationEventQuest(request: Request, env: Env, sessionId: string, questId: string): Promise<Response> {
  const body = await readJson<Record<string, unknown>>(request);
  const decisionRaw = normalizeOptionalText(body.decision);
  const decision = decisionRaw === "accepted" || decisionRaw === "declined" || decisionRaw === "completed"
    ? decisionRaw
    : null;
  if (!decision) return json({ error: "invalid decision" }, 400, { "cache-control": "no-store" });
  const auth = await readCompatibleSession(request, env);
  const row = await env.OBS_DB.prepare(
    "SELECT quest_id, session_id, team_id, status, payload_json FROM observation_event_quests WHERE quest_id = ? AND session_id = ?"
  ).bind(questId, sessionId).first<{ quest_id: string; session_id: string; team_id: string | null; status: string; payload_json: string }>();
  if (!row) return json({ error: "quest not found" }, 404, { "cache-control": "no-store" });
  const payload: Record<string, unknown> = {
    ...jsonObject(row.payload_json),
    decision,
    decided_by: auth?.userId ?? null,
    decided_at: new Date().toISOString()
  };
  await env.OBS_DB.prepare(
    "UPDATE observation_event_quests SET status = ?, payload_json = ?, updated_at = CURRENT_TIMESTAMP WHERE quest_id = ? AND session_id = ?"
  ).bind(decision, JSON.stringify(payload), questId, sessionId).run();
  const eventType = decision === "accepted"
    ? "quest_accepted"
    : decision === "declined"
      ? "quest_declined"
      : "quest_completed";
  await appendObservationEventLive(env, {
    sessionId,
    type: eventType,
    scope: row.team_id ? "team" : "all",
    teamId: row.team_id,
    actorUserId: auth?.userId ?? null,
    payload: {
      quest_id: questId,
      kind: typeof payload.kind === "string" ? payload.kind : "effort",
      headline: typeof payload.headline === "string" ? payload.headline : ""
    }
  });
  return json({ ok: true }, 200, { "cache-control": "no-store" });
}

async function runScheduledObservationEventQuests(env: Env): Promise<void> {
  if (!isAppRuntime(env)) return;
  try {
    const rows = await env.OBS_DB.prepare(
      `SELECT session_id, legacy_event_id, event_code, title, organizer_user_id, corporation_id,
              plan, primary_mode, active_modes_json, location_lat, location_lng, location_radius_m,
              started_at, ended_at, target_species_json, config_json, field_id, template_source_session_id,
              created_at, updated_at
         FROM observation_event_sessions
        WHERE ended_at IS NULL
          AND started_at <= CURRENT_TIMESTAMP
        ORDER BY started_at DESC
        LIMIT 50`
    ).all<ObservationEventSessionD1Row>();
    for (const row of rows.results) {
      await generateNativeObservationEventQuests(env, mapObservationEventSession(row), {
        trigger: "interval",
        skipRecentDedup: false
      }).catch((err) => console.error("[observation-event-quest] scheduled generation failed", err));
    }
  } catch (err) {
    console.error("[observation-event-quest] scheduled tick failed", err);
  }
}

async function generateNativeObservationEventQuests(
  env: Env,
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>,
  options: { trigger: NativeObservationEventQuestTrigger; skipRecentDedup?: boolean }
): Promise<{ quests: number; modelUsed: string | null; trigger: NativeObservationEventQuestTrigger }> {
  if (session.endedAt) return { quests: 0, modelUsed: null, trigger: options.trigger };
  if (!options.skipRecentDedup) {
    const recent = await env.OBS_DB.prepare(
      `SELECT COUNT(*) AS recent
         FROM observation_event_quests
        WHERE session_id = ?
          AND status = 'offered'
          AND created_at > datetime('now', '-90 seconds')
          AND json_extract(payload_json, '$.trigger') = ?`
    ).bind(session.sessionId, options.trigger).first<{ recent: number }>();
    if (Number(recent?.recent ?? 0) > 0) {
      return { quests: 0, modelUsed: null, trigger: options.trigger };
    }
  }
  const teams = await listObservationEventTeams(env, session.sessionId).catch(() => []);
  const candidates = buildNativeObservationEventQuestCandidates(session, teams, options.trigger).slice(0, 3);
  let inserted = 0;
  for (const candidate of candidates) {
    const questId = crypto.randomUUID();
    const payload = {
      kind: candidate.kind,
      headline: candidate.headline,
      prompt: candidate.prompt,
      rationale: candidate.rationale,
      team_name: candidate.teamName,
      trigger: options.trigger,
      generated_by: "cloudflare-d1-static-quest",
      expires_in_minutes: candidate.expiresInMinutes
    };
    await env.OBS_DB.prepare(
      `INSERT INTO observation_event_quests
         (quest_id, session_id, team_id, status, payload_json)
       VALUES (?, ?, ?, 'offered', ?)`
    ).bind(questId, session.sessionId, candidate.teamId, JSON.stringify(payload)).run();
    await appendObservationEventLive(env, {
      sessionId: session.sessionId,
      type: "quest_offered",
      scope: candidate.teamId ? "team" : "all",
      teamId: candidate.teamId,
      payload: { quest_id: questId, ...payload }
    });
    inserted += 1;
  }
  return { quests: inserted, modelUsed: "cloudflare-d1-static-quest", trigger: options.trigger };
}

function buildNativeObservationEventQuestCandidates(
  session: NonNullable<Awaited<ReturnType<typeof getObservationEventSessionById>>>,
  teams: ObservationEventTeamD1Row[],
  trigger: NativeObservationEventQuestTrigger
): Array<{ teamId: string | null; teamName: string; kind: string; headline: string; prompt: string; rationale: string; expiresInMinutes: number }> {
  const out: Array<{ teamId: string | null; teamName: string; kind: string; headline: string; prompt: string; rationale: string; expiresInMinutes: number }> = [];
  const firstTarget = session.targetSpecies[0] ?? null;
  if (firstTarget) {
    out.push({
      teamId: null,
      teamName: "all",
      kind: "taxa",
      headline: `${firstTarget}の手がかり`,
      prompt: `${firstTarget}がいそうな日なた・日陰・水辺・草地を一つ選んで、数分だけ見てみる。`,
      rationale: "観察会の目標種に近い環境を追加で見ると、種リストと探した範囲の両方が残ります。",
      expiresInMinutes: trigger === "ending_soon" ? 8 : 15
    });
  }
  const firstTeam = teams[0] ?? null;
  if (firstTeam) {
    const targetTaxa = jsonArray(firstTeam.target_taxa_json).filter((value): value is string => typeof value === "string");
    out.push({
      teamId: firstTeam.team_id,
      teamName: firstTeam.name,
      kind: targetTaxa[0] ? "taxa" : "effort",
      headline: targetTaxa[0] ? `${firstTeam.name}: ${targetTaxa[0]}` : `${firstTeam.name}: もう一地点`,
      prompt: targetTaxa[0]
        ? `${firstTeam.name}は${targetTaxa[0]}の手がかりを一つ追加で探す。見つからなくても、探した場所を残す。`
        : `${firstTeam.name}はまだ見ていない方向へ短く移動して、同じ条件で一地点だけ追加する。`,
      rationale: "班ごとの小さな追加行動は、偏りを減らし、主催者が後で状況を整理しやすくします。",
      expiresInMinutes: 12
    });
  }
  out.push({
    teamId: null,
    teamName: "all",
    kind: "absence",
    headline: trigger === "ending_soon" ? "最後に未確認を残す" : "見つからなかった条件",
    prompt: "対象を一つ決めて5分だけ探し、見つからなければ条件と場所を短く残す。",
    rationale: "条件つきの未確認は、次回の観察範囲や季節差を考える材料になります。",
    expiresInMinutes: trigger === "ending_soon" ? 6 : 12
  });
  return out;
}

async function uploadLegacyCompatiblePhoto(observationId: string, request: Request, env: Env): Promise<Response> {
  assertNonEmpty(observationId, "observationId");
  const productionSession = env.ENVIRONMENT === "production"
    ? await readCompatibleSession(request, env)
    : null;
  if (env.ENVIRONMENT === "production" && !productionSession) {
    return json({ ok: false, error: "session_required" }, 401);
  }

  const observation = await env.OBS_DB.prepare(
    `SELECT draft_id, owner_user_id, partition_month
     FROM observations
     WHERE observation_id = ?`
  ).bind(observationId).first<{ draft_id: string; owner_user_id: string; partition_month: string | null }>();
  if (!observation) {
    return json({ ok: false, error: `observation not found: ${observationId}` }, 404);
  }
  if (productionSession && productionSession.userId !== observation.owner_user_id) {
    return json({ ok: false, error: "forbidden" }, 403);
  }

  const input = await readJson<LegacyPhotoUploadInput>(request);
  const mimeType = (normalizeOptionalText(input.mimeType) ?? "image/jpeg").split(";", 1)[0]!.trim().toLowerCase();
  const filename = sanitizeFileName(normalizeOptionalText(input.filename) ?? "upload.jpg");
  const body = base64ToArrayBuffer(normalizeOptionalText(input.base64Data) ?? "");
  if (body.byteLength === 0) {
    throw new HttpError(400, "decoded image is empty");
  }
  if (body.byteLength > 10 * 1024 * 1024) {
    throw new HttpError(400, "image exceeds 10MB limit after normalization");
  }
  if (requiresStrictPhotoUploadValidation(request, env)) {
    const validationError = validateObservationPhotoUpload(new Uint8Array(body), mimeType, filename);
    if (validationError) {
      return json({ ok: false, error: validationError }, 415, { "cache-control": "no-store" });
    }
  }
  const partitionMonth = observation.partition_month ?? partitionMonthFromDate(new Date().toISOString());

  const sha256 = await sha256Hex(body);
  const idempotencyKey = `v1-photo:${observationId}:${sha256}`;
  const assetId = `asset_${await sha256Hex(textToArrayBuffer(idempotencyKey))}`;
  const outboxMediaId = `outbox_${assetId}_media`;
  const outboxReadModelId = `outbox_${assetId}_readmodel`;
  const outboxAiId = `outbox_${assetId}_ai`;
  const reassessmentRequestId = `reassess:${observationId}:standard:${observation.owner_user_id}`;
  const objectKey = `original/v1-compat/${observationId}/${assetId}-${newId("upload")}`;
  const relativePath = objectKey;
  const occurrenceId = `occ:${observationId}:0`;
  const facePrivacy = normalizeFacePrivacy(input.facePrivacy);

  const readReassessmentState = async (): Promise<string> => {
    const row = await env.OBS_DB.prepare(
      `SELECT request_state
       FROM observation_reassessment_requests
       WHERE observation_id = ? AND request_kind = 'standard' AND actor_user_id = ?`
    ).bind(observationId, observation.owner_user_id).first<{ request_state: string }>();
    return normalizeOptionalText(row?.request_state) ?? "pending";
  };

  const replayExistingPhoto = async (asset: LegacyPhotoAssetRow): Promise<Response> => {
    if (
      asset.observation_id !== observationId
      || asset.owner_user_id !== observation.owner_user_id
      || asset.sha256 !== sha256
      || asset.mime !== mimeType
      || asset.bytes !== body.byteLength
    ) {
      return json({ ok: false, error: "media_idempotency_conflict" }, 409, { "cache-control": "no-store" });
    }
    if (asset.processing_state !== "uploaded") {
      return json({ ok: false, error: "duplicate_media_in_progress" }, 409, { "cache-control": "no-store" });
    }
    const existingObject = await env.ASSET_BUCKET.head(asset.object_key);
    if (!existingObject || existingObject.size !== body.byteLength) {
      return json({ ok: false, error: "media_integrity_missing" }, 503, { "cache-control": "no-store" });
    }
    return json({
      ok: true,
      visitId: observationId,
      occurrenceId,
      relativePath: asset.object_key,
      publicUrl: `/${asset.object_key}`,
      compatibility: { attempted: false, succeeded: false },
      facePrivacy,
      idempotency: { key: idempotencyKey, reused: true },
      reassessment: {
        state: await readReassessmentState(),
        kind: "standard",
        source: "cloudflare_photo_upload_atomic_reassessment"
      },
      dispatch: { sent: 0, pending: 0, errors: [] }
    }, 200, { "cache-control": "no-store" });
  };

  const existingAsset = await env.OBS_DB.prepare(
    `SELECT asset_id, observation_id, owner_user_id, object_key, sha256, mime, bytes, visibility, processing_state
     FROM asset_ledger
     WHERE asset_id = ?`
  ).bind(assetId).first<LegacyPhotoAssetRow>();
  if (existingAsset) {
    return replayExistingPhoto(existingAsset);
  }

  await env.ASSET_BUCKET.put(objectKey, body, { httpMetadata: { contentType: mimeType } });
  try {
    const batchResults = await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT OR IGNORE INTO asset_ledger
       (asset_id, draft_id, observation_id, owner_user_id, object_key, sha256, mime, bytes, visibility, processing_state, uploaded_at, partition_month)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'uploaded', CURRENT_TIMESTAMP, ?)`
    ).bind(
      assetId,
      observation.draft_id,
      observationId,
      observation.owner_user_id,
      objectKey,
      sha256,
      mimeType,
      body.byteLength,
      "private",
      partitionMonth
    ),
    env.OBS_DB.prepare(
      "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxMediaId, "media.process", observationId, JSON.stringify({ observationId, assetId }), partitionMonth),
    env.OBS_DB.prepare(
      "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxReadModelId, "readmodel.refresh", observationId, JSON.stringify({ observationId }), partitionMonth),
    env.OBS_DB.prepare(
      "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxAiId, "observation.reassess", observationId, JSON.stringify({ observationId, assetId }), partitionMonth),
    env.OBS_DB.prepare(
      `INSERT INTO observation_reassessment_requests (
         request_id, observation_id, request_kind, actor_user_id, request_state, source_payload_json,
         created_at, updated_at
       ) VALUES (?, ?, ?, ?, 'pending', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
       ON CONFLICT(observation_id, request_kind, actor_user_id) DO UPDATE SET
         request_state = 'pending',
         source_payload_json = excluded.source_payload_json,
         updated_at = CURRENT_TIMESTAMP`
    ).bind(
      reassessmentRequestId,
      observationId,
      "standard",
      observation.owner_user_id,
      JSON.stringify({
        source: "cloudflare_photo_upload_atomic_reassessment",
        transactionalIntent: true,
        assetId,
        enqueueId: outboxAiId,
        requestedAt: new Date().toISOString()
      })
    ),
    rollbackLedgerInsert(env, {
      ledgerId: `rollback_${assetId}`,
      eventType: "asset.photo.upload",
      targetId: assetId,
      partitionMonth,
      sourceEndpoint: "POST /api/v1/observations/:id/photos/upload",
      payload: {
        assetId,
        observationId,
        ownerUserId: observation.owner_user_id,
        objectKey,
        sha256,
        mime: mimeType,
        bytes: body.byteLength,
        visibility: "private",
        occurrenceId,
        facePrivacy
      },
      replaySql: postgresAssetReplaySql(assetId, observationId, observation.owner_user_id, objectKey, sha256, mimeType, body.byteLength, "private")
    })
    ]);
    const assetReservationChanges = Number((batchResults[0] as { meta?: { changes?: unknown } } | undefined)?.meta?.changes);
    if (!Number.isFinite(assetReservationChanges)) {
      return json({ ok: false, error: "media_idempotency_reservation_unknown" }, 503, { "cache-control": "no-store" });
    }
    if (assetReservationChanges !== 1) {
      const concurrentAsset = await env.OBS_DB.prepare(
        `SELECT asset_id, observation_id, owner_user_id, object_key, sha256, mime, bytes, visibility, processing_state
         FROM asset_ledger
         WHERE asset_id = ?`
      ).bind(assetId).first<LegacyPhotoAssetRow>();
      if (!concurrentAsset) {
        return json({ ok: false, error: "media_idempotency_reservation_missing" }, 503, { "cache-control": "no-store" });
      }
      if (concurrentAsset.object_key !== objectKey) {
        await env.ASSET_BUCKET.delete(objectKey).catch((cleanupError) => {
          console.error("[photo-upload] R2 compensation failed after reservation loss", cleanupError);
        });
      }
      return replayExistingPhoto(concurrentAsset);
    }
  } catch (error) {
    // R2 and D1 cannot share a transaction. A metadata failure must not leave
    // an orphaned object that could later be mistaken for a completed upload.
    await env.ASSET_BUCKET.delete(objectKey).catch((cleanupError) => {
      console.error("[photo-upload] R2 compensation failed after D1 failure", cleanupError);
    });
    throw error;
  }

  const dispatch = await dispatchOutboxBestEffort(env, [
    { outboxId: outboxMediaId, topic: "media.process", targetId: observationId },
    { outboxId: outboxReadModelId, topic: "readmodel.refresh", targetId: observationId },
    { outboxId: outboxAiId, topic: "observation.reassess", targetId: observationId }
  ]);

  return json({
    ok: true,
    visitId: observationId,
    occurrenceId,
    relativePath,
    publicUrl: `/${relativePath}`,
    compatibility: {
      attempted: false,
      succeeded: false
    },
    facePrivacy,
    idempotency: { key: idempotencyKey, reused: false },
    reassessment: {
      state: "pending",
      kind: "standard",
      source: "cloudflare_photo_upload_atomic_reassessment"
    },
    dispatch
  });
}

const OBSERVATION_PHOTO_EXTENSIONS: Readonly<Record<string, readonly string[]>> = {
  "image/jpeg": ["jpg", "jpeg"],
  "image/png": ["png"],
  "image/webp": ["webp"],
  "image/heic": ["heic"],
  "image/heif": ["heif"],
  "image/avif": ["avif"],
};

function requiresStrictPhotoUploadValidation(request: Request, env: Env): boolean {
  if (env.ENVIRONMENT === "production" || env.ENVIRONMENT === "staging") return true;
  const hostname = new URL(request.url).hostname.toLowerCase();
  return hostname === "staging.ikimon.life" || PUBLIC_CUSTOM_HOSTS.has(hostname);
}

function validateObservationPhotoUpload(bytes: Uint8Array, declaredMime: string, filename: string): string | null {
  if (!Object.prototype.hasOwnProperty.call(OBSERVATION_PHOTO_EXTENSIONS, declaredMime)) {
    return "unsupported_image_type";
  }
  const detectedMime = detectObservationPhotoMime(bytes);
  if (!detectedMime || detectedMime !== declaredMime) {
    return "image_content_type_mismatch";
  }
  const extension = filename.includes(".") ? filename.split(".").pop()?.toLowerCase() ?? "" : "";
  if (!extension || !OBSERVATION_PHOTO_EXTENSIONS[declaredMime]?.includes(extension)) {
    return "image_extension_mismatch";
  }
  return null;
}

function detectObservationPhotoMime(bytes: Uint8Array): string | null {
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return "image/jpeg";
  if (
    bytes.length >= 8 &&
    bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47 &&
    bytes[4] === 0x0d && bytes[5] === 0x0a && bytes[6] === 0x1a && bytes[7] === 0x0a
  ) return "image/png";
  if (
    bytes.length >= 12 &&
    bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46 &&
    bytes[8] === 0x57 && bytes[9] === 0x45 && bytes[10] === 0x42 && bytes[11] === 0x50
  ) return "image/webp";
  if (bytes.length >= 12 && bytes[4] === 0x66 && bytes[5] === 0x74 && bytes[6] === 0x79 && bytes[7] === 0x70) {
    const brand = String.fromCharCode(bytes[8]!, bytes[9]!, bytes[10]!, bytes[11]!).toLowerCase();
    if (brand === "avif" || brand === "avis") return "image/avif";
    if (["heic", "heix", "hevc", "hevx"].includes(brand)) return "image/heic";
    if (["mif1", "msf1", "heif"].includes(brand)) return "image/heif";
  }
  return null;
}

async function uploadStagingCompatibleAudio(observationId: string, request: Request, env: Env): Promise<Response> {
  assertNonEmpty(observationId, "observationId");
  if (env.ENVIRONMENT !== "staging" && env.ENVIRONMENT !== "shadow") {
    return json({ ok: false, error: "not_available" }, 404, { "cache-control": "no-store" });
  }
  const observation = await env.OBS_DB.prepare(
    `SELECT draft_id, owner_user_id, partition_month
     FROM observations
     WHERE observation_id = ?`
  ).bind(observationId).first<{ draft_id: string; owner_user_id: string; partition_month: string | null }>();
  if (!observation) return json({ ok: false, error: `observation not found: ${observationId}` }, 404);

  const authHeaders = [
    request.headers.get("x-ikimon-write-key"),
    request.headers.get("x-v2-privileged-write-api-key"),
    request.headers.get("x-api-key"),
    bearerToken(request.headers.get("authorization"))
  ].some((value) => Boolean(value?.trim()));
  if (authHeaders) {
    const auth = assertPrivilegedWriteAccessNative(request, env);
    if (auth instanceof Response) return auth;
  } else {
    const session = await readCompatibleSession(request, env);
    if (!session) return json({ ok: false, error: "session_required" }, 401, { "cache-control": "no-store" });
    if (session.userId !== observation.owner_user_id) return json({ ok: false, error: "forbidden" }, 403, { "cache-control": "no-store" });
  }

  const input = await readJson<LegacyAudioUploadInput>(request);
  const mimeType = normalizeFieldscanAudioMime(input.mimeType);
  const filename = sanitizeFileName(normalizeOptionalText(input.filename) ?? "clean-audio.webm");
  const body = base64ToArrayBuffer(normalizeOptionalText(input.base64Data) ?? "");
  if (body.byteLength === 0) throw new HttpError(400, "decoded_audio_empty");
  if (body.byteLength > FIELDSCAN_AUDIO_MAX_BYTES) throw new HttpError(400, "audio_too_large");
  const audioBytes = new Uint8Array(body);
  const magic = validateFieldscanAudioMagic(audioBytes, mimeType);
  if (magic !== "ok") throw new HttpError(400, `audio_quarantined_${magic}`);

  const privacyStatus = normalizeOptionalText(input.privacyStatus) ?? "";
  if (privacyStatus !== "clean") throw new HttpError(400, "audio_privacy_not_clean");
  const voiceFlag = typeof input.voiceFlag === "boolean"
    ? (input.voiceFlag ? "human_voice" : "no_voice")
    : normalizeOptionalText(input.voiceFlag);
  if (voiceFlag && voiceFlag !== "no_voice" && voiceFlag !== "none" && voiceFlag !== "clean") {
    throw new HttpError(400, "audio_voice_flag_not_clean");
  }
  if (normalizeOptionalText(input.transcriptionStatus) === "skipped") {
    throw new HttpError(400, "audio_transcription_skipped");
  }
  const meta = asPlainObject(input.meta) ?? {};
  const privacyDecision = decideFieldscanInitialPrivacy(meta, true);
  if (privacyDecision.decision !== "clean") throw new HttpError(400, `audio_not_clean_${privacyDecision.reason}`);
  const partitionMonth = observation.partition_month ?? partitionMonthFromDate(new Date().toISOString());

  const sha256 = await sha256Hex(body);
  const assetId = newId("asset_audio");
  const outboxMediaId = newId("outbox");
  const outboxReadModelId = newId("outbox");
  const objectKey = `original/v1-compat/${observationId}/${assetId}-${filename}`;
  const relativePath = objectKey;
  const occurrenceId = `occ:${observationId}:0`;
  await env.ASSET_BUCKET.put(objectKey, body, { httpMetadata: { contentType: mimeType } });
  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT INTO asset_ledger
       (asset_id, draft_id, observation_id, owner_user_id, object_key, sha256, mime, bytes, visibility, processing_state, uploaded_at, partition_month)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'private', 'uploaded', CURRENT_TIMESTAMP, ?)`
    ).bind(
      assetId,
      observation.draft_id,
      observationId,
      observation.owner_user_id,
      objectKey,
      sha256,
      mimeType,
      body.byteLength,
      partitionMonth
    ),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxMediaId, "media.process", observationId, JSON.stringify({ observationId, assetId }), partitionMonth),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxReadModelId, "readmodel.refresh", observationId, JSON.stringify({ observationId }), partitionMonth),
    rollbackLedgerInsert(env, {
      eventType: "asset.audio.upload",
      targetId: assetId,
      partitionMonth,
      sourceEndpoint: "POST /api/v1/observations/:id/audio/upload",
      payload: {
        assetId,
        observationId,
        ownerUserId: observation.owner_user_id,
        objectKey,
        sha256,
        mime: mimeType,
        bytes: body.byteLength,
        visibility: "private",
        occurrenceId,
        mediaRole: normalizeOptionalText(input.mediaRole) ?? "observation_audio",
        privacyStatus,
        voiceFlag: voiceFlag ?? "no_voice",
        transcriptionStatus: normalizeOptionalText(input.transcriptionStatus) ?? "done",
        privacyReason: privacyDecision.reason
      },
      replaySql: postgresAssetReplaySql(assetId, observationId, observation.owner_user_id, objectKey, sha256, mimeType, body.byteLength, "private")
    })
  ]);

  const dispatch = await dispatchOutboxBestEffort(env, [
    { outboxId: outboxMediaId, topic: "media.process", targetId: observationId },
    { outboxId: outboxReadModelId, topic: "readmodel.refresh", targetId: observationId }
  ]);

  return json({
    ok: true,
    visitId: observationId,
    occurrenceId,
    assetId,
    mediaRole: "observation_audio",
    relativePath,
    publicUrl: `/${relativePath}`,
    privacyStatus,
    voiceFlag: voiceFlag ?? "no_voice",
    transcriptionStatus: normalizeOptionalText(input.transcriptionStatus) ?? "done",
    dispatch
  }, 200, { "cache-control": "no-store", "x-ikimon-cloudflare-native": "staging-audio-upload" });
}

function normalizeObservationDataRightsNative(input: unknown): {
  recordConsent: string;
  researchUseConsent: string;
  enterpriseReportConsent: string;
  datasetLicense: string | null;
  mediaLicense: string | null;
  externalExportAllowed: boolean;
  withdrawalStatus: string;
  sourcePayload: Record<string, unknown>;
} {
  const value = asPlainObject(input) ?? {};
  const recordConsent = pickEnum(value.recordConsent, ["private", "internal", "public_summary", "external_export"], "private");
  const researchUseConsent = pickEnum(value.researchUseConsent, ["none", "internal", "research_allowed", "public_export"], "none");
  const enterpriseReportConsent = pickEnum(value.enterpriseReportConsent, ["none", "internal", "aggregated", "identified"], "none");
  const datasetLicense = pickNullableEnum(value.datasetLicense, ["CC0-1.0", "CC-BY-4.0"]);
  const mediaLicense = pickNullableEnum(value.mediaLicense, ["all_rights_reserved", "CC-BY-4.0", "CC-BY-NC-4.0"]);
  const withdrawalStatus = pickEnum(value.withdrawalStatus, ["active", "withdrawn", "delete_requested", "deleted"], "active");
  const externalExportAllowed = value.externalExportAllowed === true
    && recordConsent === "external_export"
    && researchUseConsent === "public_export"
    && Boolean(datasetLicense)
    && mediaLicense !== null
    && mediaLicense !== "all_rights_reserved"
    && withdrawalStatus === "active";
  return {
    recordConsent,
    researchUseConsent,
    enterpriseReportConsent,
    datasetLicense,
    mediaLicense,
    externalExportAllowed,
    withdrawalStatus,
    sourcePayload: value
  };
}

type NativeCivicObservationContext = {
  contextId: string;
  visitId: string;
  occurrenceId: string | null;
  contextKind: string;
  activityLabel: string | null;
  activityIntent: string | null;
  participantRole: string | null;
  audienceScope: string;
  publicPrecision: string;
  riskLane: string;
  reportConsent: string;
  revisitOfVisitId: string | null;
  fieldId: string | null;
  routeId: string | null;
  plotId: string | null;
  sourcePayload: Record<string, unknown>;
};

function normalizeObservationCivicContextNative(input: Record<string, unknown>, visitId: string, occurrenceId: string | null): NativeCivicObservationContext {
  const riskLane = pickEnum(input.riskLane ?? input.risk_lane, ["normal", "danger_candidate", "invasive_candidate", "tree_anomaly", "rare_sensitive"], "normal");
  const requestedPrecision = pickEnum(input.publicPrecision ?? input.public_precision, ["exact_private", "site", "mesh", "municipality", "hidden"], "municipality");
  const publicPrecision = riskLane === "rare_sensitive"
    ? "hidden"
    : riskLane !== "normal" && requestedPrecision === "exact_private"
      ? "municipality"
      : requestedPrecision;
  const hasEvent = typeof input.eventSessionId === "string" || typeof input.eventCode === "string";
  return {
    contextId: normalizeOptionalText(input.contextId ?? input.context_id) ?? `civic:${visitId}`,
    visitId,
    occurrenceId,
    contextKind: pickEnum(input.contextKind ?? input.context_kind, ["ordinary", "event", "school", "satoyama", "risk", "site_summary"], hasEvent ? "event" : riskLane === "normal" ? "ordinary" : "risk"),
    activityLabel: normalizeOptionalText(input.activityLabel ?? input.activity_label),
    activityIntent: pickNullableEnum(input.activityIntent ?? input.activity_intent, ["discover", "revisit", "compare", "learn", "manage", "confirm", "share"]),
    participantRole: pickNullableEnum(input.participantRole ?? input.participant_role, ["finder", "photographer", "context_recorder", "note_taker", "guide", "reviewer", "manager", "teacher", "student", "participant"]),
    audienceScope: pickEnum(input.audienceScope ?? input.audience_scope, ["private", "class_group", "event_participants", "public", "partner_internal", "research_internal"], "private"),
    publicPrecision,
    riskLane,
    reportConsent: pickEnum(input.reportConsent ?? input.report_consent, ["none", "internal", "public_summary", "research_export"], "none"),
    revisitOfVisitId: normalizeOptionalText(input.revisitOfVisitId ?? input.revisit_of_visit_id),
    fieldId: normalizeOptionalText(input.fieldId ?? input.field_id),
    routeId: normalizeOptionalText(input.routeId ?? input.route_id),
    plotId: normalizeOptionalText(input.plotId ?? input.plot_id),
    sourcePayload: asPlainObject(input.sourcePayload ?? input.source_payload) ?? {}
  };
}

function buildObservationCivicContextNative(
  input: LegacyObservationUpsertInput,
  visitId: string,
  occurrenceId: string | null
): NativeCivicObservationContext | null {
  const explicit = asPlainObject(input.civicContext);
  if (explicit) {
    return normalizeObservationCivicContextNative({
      ...explicit,
      sourcePayload: asPlainObject(explicit.sourcePayload ?? explicit.source_payload) ?? {}
    }, visitId, occurrenceId);
  }
  const hasEvent = typeof input.eventSessionId === "string" || typeof input.eventCode === "string";
  const riskLane = normalizeOptionalText(input.sourcePayload?.risk_lane);
  if (!hasEvent && !riskLane) return null;
  return normalizeObservationCivicContextNative({
    contextKind: hasEvent ? "event" : "risk",
    activityIntent: hasEvent ? "share" : "discover",
    participantRole: hasEvent ? "participant" : "finder",
    riskLane: riskLane ?? "normal",
    eventSessionId: input.eventSessionId ?? null,
    eventCode: input.eventCode ?? null,
    sourcePayload: {
      derived: true,
      event_session_id: input.eventSessionId ?? null,
      event_code: input.eventCode ?? null
    }
  }, visitId, occurrenceId);
}

function pickEnum(value: unknown, allowed: string[], fallback: string): string {
  const text = normalizeOptionalText(value);
  return text && allowed.includes(text) ? text : fallback;
}

function pickNullableEnum(value: unknown, allowed: string[]): string | null {
  const text = normalizeOptionalText(value);
  return text && allowed.includes(text) ? text : null;
}

async function putAssetBody(assetId: string, request: Request, env: Env): Promise<Response> {
  assertNonEmpty(assetId, "assetId");
  const asset = await env.OBS_DB.prepare("SELECT object_key, mime FROM asset_ledger WHERE asset_id = ?")
    .bind(assetId)
    .first<{ object_key: string; mime: string }>();
  if (!asset) return json({ error: "asset_not_found" }, 404);
  if (!request.body) return json({ error: "missing_body" }, 400);

  await env.ASSET_BUCKET.put(asset.object_key, request.body, { httpMetadata: { contentType: asset.mime } });
  await env.OBS_DB.prepare(
    "UPDATE asset_ledger SET processing_state = 'uploaded', uploaded_at = CURRENT_TIMESTAMP WHERE asset_id = ?"
  ).bind(assetId).run();

  return json({ ok: true, assetId });
}

async function finalizeObservation(request: Request, env: Env): Promise<Response> {
  const input = await readJson<FinalizeObservationInput>(request);
  assertNonEmpty(input.draftId, "draftId");

  const draft = await env.OBS_DB.prepare("SELECT * FROM draft_observations WHERE draft_id = ?")
    .bind(input.draftId)
    .first<Record<string, D1Value>>();
  if (!draft) return json({ error: "draft_not_found" }, 404);

  const observationId = newId("obs");
  const outboxMediaId = newId("outbox");
  const outboxReadModelId = newId("outbox");
  const outboxAiId = `outbox_${observationId}_ai`;
  const reassessmentRequestId = `reassess:${observationId}:standard:${stringValue(draft.owner_user_id) ?? "unknown"}`;
  const observedAt = stringValue(draft.observed_at) ?? new Date().toISOString();
  const partition = resolveObservationPartition(observedAt, env);
  const ownerUserId = stringValue(draft.owner_user_id);
  const publicCell = stringValue(draft.public_cell) ?? "unknown";
  const visibility = stringValue(draft.visibility) === "public" ? "public" : "private";

  if (!ownerUserId) return json({ error: "draft_missing_owner" }, 500);

  const ownerDualWritePlan = observationDualWriteEnabled(env)
    ? await buildOwnerObservationUpsertPlan({
      recordId: observationId,
      ownerUserId,
      visibility,
      subjectType: input.taxonLabel ? "organism" : "unknown_subject",
      sourceSnapshot: {
        observedAt,
        taxonLabel: input.taxonLabel ?? null,
        visibility,
        finalizedFromDraft: true,
      },
    })
    : null;
  const draftAssets = (await env.OBS_DB.prepare(
    "SELECT asset_id, mime FROM asset_ledger WHERE draft_id = ? ORDER BY created_at, asset_id"
  ).bind(input.draftId).all<{ asset_id: string; mime: string }>()).results;
  const hasAiMedia = draftAssets.some((asset) => asset.mime.startsWith("image/"));
  const mediaDualWritePlans = observationDualWriteEnabled(env)
    ? await Promise.all(draftAssets.map((asset) =>
      buildMediaReassignmentDualWritePlan({
        recordId: observationId,
        mediaId: asset.asset_id,
        actorUserId: ownerUserId,
        role: asset.mime.startsWith("audio/") ? "audio_evidence" : "primary_evidence",
        sourcePayload: { draftId: input.draftId, mime: asset.mime },
      })
    ))
    : [];

  await env.OBS_DB.batch([
    env.OBS_DB.prepare(
      `INSERT INTO observations
       (observation_id, draft_id, owner_user_id, observed_at, taxon_label, note, exact_lat, exact_lng,
        location_accuracy_m, public_cell, visibility, partition_month)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      observationId,
      input.draftId,
      ownerUserId,
      observedAt,
      input.taxonLabel ?? null,
      input.note ?? null,
      numberOrNull(draft.exact_lat),
      numberOrNull(draft.exact_lng),
      numberOrNull(draft.location_accuracy_m),
      publicCell,
      visibility,
      partition.partitionMonth
    ),
    env.OBS_DB.prepare(
      "UPDATE draft_observations SET processing_state = 'finalized', finalized_at = CURRENT_TIMESTAMP WHERE draft_id = ?"
    ).bind(input.draftId),
    env.OBS_DB.prepare(
      "UPDATE asset_ledger SET observation_id = ? WHERE draft_id = ?"
    ).bind(observationId, input.draftId),
    ...observationDualWriteStatements(env, ownerDualWritePlan),
    ...mediaDualWritePlans.flatMap((plan) => observationDualWriteStatements(env, plan)),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxMediaId, "media.process", observationId, JSON.stringify({ observationId }), partition.partitionMonth),
    env.OBS_DB.prepare(
      "INSERT INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
    ).bind(outboxReadModelId, "readmodel.refresh", observationId, JSON.stringify({ observationId }), partition.partitionMonth),
    ...(hasAiMedia ? [
      env.OBS_DB.prepare(
        "INSERT OR IGNORE INTO outbox (outbox_id, topic, target_id, payload_json, partition_month) VALUES (?, ?, ?, ?, ?)"
      ).bind(outboxAiId, "observation.reassess", observationId, JSON.stringify({ observationId }), partition.partitionMonth),
      env.OBS_DB.prepare(
        `INSERT OR IGNORE INTO observation_reassessment_requests (
           request_id, observation_id, request_kind, actor_user_id, request_state, source_payload_json,
           created_at, updated_at
         ) VALUES (?, ?, 'standard', ?, 'pending', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
      ).bind(
        reassessmentRequestId,
        observationId,
        ownerUserId,
        JSON.stringify({
          source: "cloudflare_observation_finalize_atomic_reassessment",
          transactionalIntent: true,
          enqueueId: outboxAiId,
          requestedAt: new Date().toISOString(),
        }),
      ),
    ] : []),
    rollbackLedgerInsert(env, {
      eventType: "observation.finalize",
      targetId: observationId,
      partitionMonth: partition.partitionMonth,
      sourceEndpoint: "POST /api/v0/observations/finalize",
      payload: {
        observationId,
        draftId: input.draftId,
        ownerUserId,
        observedAt,
        taxonLabel: input.taxonLabel ?? null,
        note: input.note ?? null,
        exactLat: numberOrNull(draft.exact_lat),
        exactLng: numberOrNull(draft.exact_lng),
        locationAccuracyM: numberOrNull(draft.location_accuracy_m),
        publicCell,
        visibility
      },
      replaySql: postgresObservationReplaySql(
        observationId,
        ownerUserId,
        observedAt,
        input.taxonLabel ?? null,
        input.note ?? null,
        numberOrNull(draft.exact_lat),
        numberOrNull(draft.exact_lng),
        numberOrNull(draft.location_accuracy_m),
        publicCell,
        visibility
      )
    })
  ]);

  const dispatch = await dispatchOutboxBestEffort(env, [
    { outboxId: outboxMediaId, topic: "media.process", targetId: observationId },
    { outboxId: outboxReadModelId, topic: "readmodel.refresh", targetId: observationId },
    ...(hasAiMedia ? [{ outboxId: outboxAiId, topic: "observation.reassess" as const, targetId: observationId }] : []),
  ]);

  return json({ observationId, processingState: "accepted", dispatch }, 201);
}

async function drainOutbox(env: Env): Promise<Response> {
  const rows = await queryPendingOutbox(env);
  for (const row of rows) {
    await sendOutbox(env, { outboxId: row.outbox_id, topic: row.topic, targetId: row.target_id });
  }
  return json({ dispatched: rows.length });
}

async function r2Inventory(url: URL, env: Env): Promise<Response> {
  if (env.ENVIRONMENT !== "shadow") {
    return json({ error: "not_available" }, 404);
  }
  const prefix = url.searchParams.get("prefix") ?? "original/";
  const limit = Math.min(Math.max(Number(url.searchParams.get("limit") ?? "100"), 1), 1000);
  const cursor = url.searchParams.get("cursor") ?? undefined;
  const listed = await env.ASSET_BUCKET.list({ prefix, limit, cursor });
  return json({
    prefix,
    limit,
    cursor: cursor ?? null,
    nextCursor: listed.cursor ?? null,
    truncated: Boolean(listed.truncated),
    count: listed.objects.length,
    bytes: listed.objects.reduce((sum, object) => sum + object.size, 0),
    objects: listed.objects.map((object) => ({
      key: object.key,
      size: object.size,
      etag: object.etag ?? null,
      uploaded: object.uploaded ? new Date(object.uploaded).toISOString() : null,
      checksums: object.checksums ?? null
    }))
  });
}

async function queryPendingOutbox(env: Env): Promise<Array<{ outbox_id: string; topic: MediaJob["topic"]; target_id: string }>> {
  const result = await env.OBS_DB.prepare(
    "SELECT outbox_id, topic, target_id FROM outbox WHERE dispatch_state = 'pending' ORDER BY created_at LIMIT 100"
  ).all<{ outbox_id: string; topic: MediaJob["topic"]; target_id: string }>();
  return result.results;
}

async function dispatchOutboxBestEffort(env: Env, jobs: MediaJob[]): Promise<{ sent: number; pending: number; errors: string[] }> {
  let sent = 0;
  const errors: string[] = [];
  for (const job of jobs) {
    try {
      await sendOutbox(env, job);
      sent++;
    } catch (error) {
      const message = error instanceof Error ? error.message : "unknown dispatch error";
      errors.push(message);
      await env.OBS_DB.prepare(
        "UPDATE outbox SET attempts = attempts + 1, last_error = ? WHERE outbox_id = ?"
      ).bind(message, job.outboxId).run();
    }
  }
  return { sent, pending: jobs.length - sent, errors };
}

async function sendOutbox(env: Env, job: MediaJob): Promise<void> {
  await env.MEDIA_QUEUE.send(job);
  await env.OBS_DB.prepare(
    "UPDATE outbox SET dispatch_state = 'dispatched', dispatched_at = CURRENT_TIMESTAMP WHERE outbox_id = ?"
  ).bind(job.outboxId).run();
}

async function applyMediaJob(job: MediaJob, env: Env): Promise<void> {
  if (job.topic === "media.process") {
    await markUploadedAssetsPublicReady(job.targetId, env);
    await refreshPublicReadmodel(job.targetId, env);
    return;
  }

  if (job.topic === "readmodel.refresh") {
    await refreshPublicReadmodel(job.targetId, env);
    return;
  }

  if (job.topic === "observation.reassess") {
    await submitGeminiObservationReassessmentGroups([job.targetId], env);
  }
}

async function runScheduledOutboxDrain(env: Env): Promise<void> {
  const rows = await queryPendingOutbox(env);
  for (const row of rows) {
    await sendOutbox(env, { outboxId: row.outbox_id, topic: row.topic, targetId: row.target_id });
  }
}

async function recoverLegacyFalsePositiveImageDerivatives(env: Env): Promise<void> {
  let rows: { results: Array<{ observation_id: string }> };
  try {
    rows = await env.OBS_DB.prepare(
      `SELECT DISTINCT observation_id
         FROM asset_ledger
        WHERE observation_id IS NOT NULL
          AND mime LIKE 'image/%'
          AND processing_state = 'uploaded'
          AND exif_scrub_state = 'failed'
          AND public_derivative_metadata_json LIKE '%"reason":"derivative_privacy_check_failed"%'
          AND public_derivative_metadata_json NOT LIKE '%"inspectionVersion":"webp-chunk-v2"%'
        ORDER BY created_at
        LIMIT 10`
    ).all<{ observation_id: string }>();
  } catch (error) {
    console.error("[media-recovery] failed to query legacy derivative failures", error);
    return;
  }
  for (const row of rows.results) {
    await markUploadedAssetsPublicReady(row.observation_id, env);
    await refreshPublicReadmodel(row.observation_id, env);
  }
}

async function runScheduledObservationReassessments(env: Env): Promise<void> {
  if (!env.GEMINI_API_KEY) return;
  await requeueLatestPublicGeminiUpgradeTargets(env);
  await requeuePublicGeminiQualityBacklog(env);
  await resumeGeminiObservationBatchGroups(env);
  await submitGeminiObservationReassessmentGroups([], env);
}

async function requeueLatestPublicGeminiUpgradeTargets(env: Env): Promise<void> {
  const latestPublicIds = (await recentPublicRecordCards(env, 120))
    .filter((item) => Boolean(item.photoUrl))
    .slice(0, 30)
    .map((item) => item.visitId);
  if (latestPublicIds.length === 0) return;
  const rows = await env.OBS_DB.prepare(
    `SELECT rr.request_id, o.observation_id, o.owner_user_id,
            rr.actor_user_id, rr.request_state, rr.source_payload_json
       FROM observations o
       LEFT JOIN observation_reassessment_requests rr
         ON rr.observation_id = o.observation_id
        AND rr.request_kind = 'standard'
        AND rr.actor_user_id = o.owner_user_id
      WHERE o.visibility = 'public' AND o.emergency_hidden = 0
        AND o.observation_id IN (${latestPublicIds.map(() => "?").join(", ")})`
  ).bind(...latestPublicIds).all<ObservationReassessmentUpgradeTargetRow>();
  const targetsById = new Map(rows.results.map((row) => [row.observation_id, row]));
  for (const observationId of latestPublicIds) {
    const row = targetsById.get(observationId);
    if (!row) continue;
    if (!row.request_id) {
      const requestId = `reassess:${row.observation_id}:standard:${row.owner_user_id}`;
      await env.OBS_DB.prepare(
        `INSERT INTO observation_reassessment_requests (
           request_id, observation_id, request_kind, actor_user_id, request_state, source_payload_json,
           created_at, updated_at
         ) VALUES (?, ?, 'standard', ?, 'pending', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
         ON CONFLICT(observation_id, request_kind, actor_user_id) DO NOTHING`
      ).bind(
        requestId,
        row.observation_id,
        row.owner_user_id,
        JSON.stringify({
          source: "latest_public_record_ai_upgrade_v3",
          reason: "missing_reassessment_request",
          executionStatus: "pending",
          attemptCount: 0,
          requestedRuleVersion: GEMINI_OBSERVATION_RULE_VERSION,
          requestedAt: new Date().toISOString(),
        }),
      ).run();
      continue;
    }
    if (!row.source_payload_json || !["completed", "failed"].includes(row.request_state ?? "")) continue;
    if (String(reassessmentPayload(row.source_payload_json).ruleVersion ?? "") === GEMINI_OBSERVATION_RULE_VERSION) continue;
    const source = reassessmentPayload(row.source_payload_json);
    delete source.batchExecution;
    const nextPayload = JSON.stringify({
      ...source,
      source: "latest_public_record_ai_upgrade_v3",
      executionStatus: "pending",
      attemptCount: 0,
      requestedRuleVersion: GEMINI_OBSERVATION_RULE_VERSION,
      requestedAt: new Date().toISOString(),
    });
    await env.OBS_DB.prepare(
      `UPDATE observation_reassessment_requests SET request_state = 'pending', source_payload_json = ?, updated_at = CURRENT_TIMESTAMP
        WHERE request_id = ? AND request_state IN ('completed', 'failed') AND source_payload_json = ?`
    ).bind(nextPayload, row.request_id, row.source_payload_json).run();
  }
}

async function requeuePublicGeminiQualityBacklog(env: Env): Promise<void> {
  const active = await env.OBS_DB.prepare(
    `SELECT COUNT(*) AS count
       FROM observation_reassessment_requests
      WHERE request_kind = 'standard'
        AND request_state IN ('pending', 'processing')`
  ).first<{ count: number | string }>();
  const available = observationAiQualityBacklogCapacity(Number(active?.count ?? 0));
  if (available === 0) return;

  const rows = await env.OBS_DB.prepare(
    OBSERVATION_AI_QUALITY_BACKLOG_SELECT_SQL
  ).bind(GEMINI_OBSERVATION_RULE_VERSION, available).all<ObservationAiQualityBacklogTargetRow>();

  for (const row of rows.results) {
    const reason = observationAiQualityBacklogReason(row);
    if (!row.request_id) {
      const requestId = `reassess:${row.observation_id}:standard:${row.owner_user_id}`;
      await env.OBS_DB.prepare(
        `INSERT INTO observation_reassessment_requests (
           request_id, observation_id, request_kind, actor_user_id, request_state, source_payload_json,
           created_at, updated_at
         ) VALUES (?, ?, 'standard', ?, 'pending', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
         ON CONFLICT(observation_id, request_kind, actor_user_id) DO NOTHING`
      ).bind(
        requestId,
        row.observation_id,
        row.owner_user_id,
        JSON.stringify({
          source: "public_record_ai_quality_backlog_v3",
          reason,
          executionStatus: "pending",
          attemptCount: 0,
          requestedRuleVersion: GEMINI_OBSERVATION_RULE_VERSION,
          requestedAt: new Date().toISOString(),
        }),
      ).run();
      continue;
    }
    if (!row.source_payload_json || !["completed", "failed"].includes(row.request_state ?? "")) continue;
    if (String(reassessmentPayload(row.source_payload_json).ruleVersion ?? "") === GEMINI_OBSERVATION_RULE_VERSION) continue;
    const source = reassessmentPayload(row.source_payload_json);
    delete source.batchExecution;
    const nextPayload = JSON.stringify({
      ...source,
      source: "public_record_ai_quality_backlog_v3",
      reason,
      executionStatus: "pending",
      attemptCount: 0,
      requestedRuleVersion: GEMINI_OBSERVATION_RULE_VERSION,
      requestedAt: new Date().toISOString(),
    });
    // The unique observation/kind/actor key handles concurrent inserts. Existing
    // rows use an old-payload compare-and-swap so overlapping cron ticks cannot
    // claim the same completed result twice.
    await env.OBS_DB.prepare(
      `UPDATE observation_reassessment_requests
          SET request_state = 'pending', source_payload_json = ?, updated_at = CURRENT_TIMESTAMP
        WHERE request_id = ? AND request_state IN ('completed', 'failed') AND source_payload_json = ?`
    ).bind(nextPayload, row.request_id, row.source_payload_json).run();
  }
}

